import { z } from 'zod';
import { appError, err, ok, type AppError, type Result } from '@/kernel';
import { issuesOf, OPS } from './ops';

const num = z.number().nullish().transform((v) => v ?? null);
const strN = z.string().nullish().transform((v) => v ?? null);
const bool = (d: boolean) => z.boolean().nullish().transform((v) => v ?? d);

/** Check-in window settings (minutes); field names as the server (and domain/checkin-windows) spell them. */
const windowShape = {
  remoteBefore: num,
  remoteAfter: num,
  strictBefore: num,
  strictAfter: num,
  remoteEnabled: bool(false),
  strictEnabled: bool(false),
};
const checkInDefaultsSchema = z.object(windowShape);
export type CheckInDefaults = z.infer<typeof checkInDefaultsSchema>;

const roomCheckInSchema = z.object({ ...windowShape, isUseDefaultCheckInSettings: bool(true) });
export type RoomCheckInSettings = z.infer<typeof roomCheckInSchema>;

const spaceSchema = z.object({
  id: z.string(),
  name: z.string().nullish().transform((v) => v ?? ''),
  capacity: num,
  startWorking: strN,
  endWorking: strN,
  useDefaultSettings: bool(true),
  timezone: strN,
  officeId: strN,
  checkInSettings: roomCheckInSchema.nullish().transform((v) => v ?? roomCheckInSchema.parse({})),
});
export type DeviceSpace = z.infer<typeof spaceSchema>;

const deviceSchema = z.object({
  id: z.string(),
  name: z.string().nullish().transform((v) => v ?? ''),
  space: spaceSchema.nullish().transform((v) => v ?? null),
  abilityToBook: bool(false),
  abilityToStop: bool(false),
  abilityToCheckin: bool(false),
  abilityToCheckinByQR: bool(false),
  backgroundImage: strN,
});

const meSchema = z.object({
  id: z.string(),
  firstName: strN,
  lastName: strN,
  fullName: strN,
  role: strN,
  device: deviceSchema.nullish().transform((v) => v ?? null),
});

/** Abilities as `domain/permissions` DeviceAbilities expects them (SCH-ME-DEVICE). */
export interface DeviceAbilities {
  abilityToBook: boolean;
  abilityToStop: boolean;
  abilityToCheckin: boolean;
  abilityToCheckinByQR: boolean;
}

export interface MeDevice {
  id: string;
  name: string;
  abilities: DeviceAbilities;
  backgroundImage: string | null;
  /** null → no room → rooms board. */
  space: DeviceSpace | null;
}

/** OP-PROFILE-ME: the device user (id = organizer of display-made bookings, DEV-D-60) and its device. */
export interface Me {
  id: string;
  firstName: string | null;
  lastName: string | null;
  fullName: string | null;
  role: string | null;
  device: MeDevice | null;
}

const roomDetailSchema = z.object({
  id: z.string(),
  name: z.string().nullish().transform((v) => v ?? ''),
  isSharedRoom: bool(false),
  privacyLevel: num,
  maxBookingDuration: num,
  defaultBookingDuration: num,
  meetingTitleRequired: bool(false),
  privateByDefault: bool(false),
});
/** OP-ROOMS-DETAIL fields the display reads (calendar and other personal data are dropped). */
export type RoomDetail = z.infer<typeof roomDetailSchema>;

const companySettingsSchema = z.object({
  defaultCompanyWorkingStartTime: strN,
  defaultCompanyWorkingEndTime: strN,
  defaultTimezone: strN,
  dateFormat: z.string().nullish().transform((v) => v ?? 'european'),
  firstDayOfWeek: z.string().nullish().transform((v) => v ?? 'monday'),
  timeFormat: z.string().nullish().transform((v) => v ?? '24 hour'),
});
/** OP-SETTINGS-COMMON (shape of domain/working-hours CompanyHoursSource + formats). */
export type CompanySettings = z.infer<typeof companySettingsSchema>;

const companyCardSchema = z.object({
  blocked: bool(false),
  subDomain: z.string(),
  whiteLogo: strN,
  blackLogo: strN,
});
/** OP-AUTH-COMPANY-CARD. */
export type CompanyCard = z.infer<typeof companyCardSchema>;

function parseWith<T>(schema: z.ZodType<T, z.ZodTypeDef, unknown>, op: string, body: unknown): Result<T, AppError> {
  const r = schema.safeParse(body);
  if (r.success) return ok(r.data);
  return err(appError('invalid-response', 'invalid-response', { op, fieldErrors: { issues: issuesOf(r.error).join(', ') } }));
}

export function parseMe(body: unknown): Result<Me, AppError> {
  const r = parseWith(meSchema, OPS.me, body);
  if (!r.ok) return r;
  const { device, ...user } = r.value;
  if (!device) return ok({ ...user, device: null });
  const { abilityToBook, abilityToStop, abilityToCheckin, abilityToCheckinByQR, ...rest } = device;
  return ok({ ...user, device: { ...rest, abilities: { abilityToBook, abilityToStop, abilityToCheckin, abilityToCheckinByQR } } });
}

export const parseRoomDetail = (body: unknown): Result<RoomDetail, AppError> => parseWith(roomDetailSchema, OPS.roomDetail, body);
export const parseCompanySettings = (body: unknown): Result<CompanySettings, AppError> =>
  parseWith(companySettingsSchema, OPS.settingsCommon, body);
export const parseCompanyCard = (body: unknown): Result<CompanyCard, AppError> => parseWith(companyCardSchema, OPS.companyCard, body);

export function parseCheckInDefaults(body: unknown): Result<CheckInDefaults, AppError> {
  const inner = (body as { defaultRoomCheckInSettings?: unknown } | null)?.defaultRoomCheckInSettings;
  return parseWith(checkInDefaultsSchema, OPS.checkInDefaults, inner);
}

/** EVT-COMPANY-CHECKIN-SETTINGS-UPDATED data → new CheckInDefaults (null when unusable). */
export function parseCheckInSettingsEvent(data: unknown): CheckInDefaults | null {
  const r = checkInDefaultsSchema.safeParse(data);
  return r.success ? r.data : null;
}

/** EVT-ROOM-CHECKIN-SETTINGS-UPDATED data → {roomId, settings} (null when unusable). */
export function parseRoomSettingsEvent(data: unknown): { roomId: string; settings: RoomCheckInSettings } | null {
  const r = roomCheckInSchema.extend({ roomId: z.string() }).safeParse(data);
  if (!r.success) return null;
  const { roomId, ...settings } = r.data;
  return { roomId, settings };
}
