import { useEffect, useRef, type RefObject } from 'react';

/**
 * Calls `handler` on a pointer down outside `ref` (legacy un-click-outside directive). `enabled=false` detaches the
 * listener (e.g. while a dropdown is closed). The latest handler is used without re-subscribing.
 */
export function useClickOutside<T extends HTMLElement>(ref: RefObject<T>, handler: (event: Event) => void, enabled = true): void {
  const latest = useRef(handler);
  latest.current = handler;
  useEffect(() => {
    if (!enabled) return undefined;
    const listener = (event: Event): void => {
      const el = ref.current;
      if (!el || (event.target instanceof Node && el.contains(event.target))) return;
      latest.current(event);
    };
    document.addEventListener('mousedown', listener);
    document.addEventListener('touchstart', listener);
    return () => {
      document.removeEventListener('mousedown', listener);
      document.removeEventListener('touchstart', listener);
    };
  }, [ref, enabled]);
}
