import { QBIC_COLOURS, CRESTRON_SIGNALS, QBIC_ORIGIN, QBIC_PROBE_TIMEOUT_MS, noopLedDriver } from './led';
import type { LedDriver, LedDeps, LedFetch, CrestronGlobal, CrestronSignal } from './led';

const SIGNALS: readonly CrestronSignal[] = ['USB_RED_LED_CONTROL', 'USB_GREEN_LED_CONTROL', 'USB_BLUE_LED_CONTROL'];
let probeSeq = 0;

const defaultFetch: LedFetch = (url, init) => fetch(url, init);

/** OP-LED-QBIC POST /v1/led/all_leds, JSON {red, green, blue, alpha:1}; no Authorization header (DEV-D-89); answer not read. */
export function createQbicLedDriver(deps: Pick<LedDeps, 'fetchFn' | 'onError'> = {}): LedDriver {
  const fetchFn = deps.fetchFn ?? defaultFetch;
  return {
    kind: 'qbic',
    setStatus: async (status) => {
      try {
        await fetchFn(`${QBIC_ORIGIN}/v1/led/all_leds`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(QBIC_COLOURS[status]),
        });
      } catch (e) {
        deps.onError?.(e);
      }
    },
  };
}

/** LED-CRESTRON: three `sendBooleanSignal` calls (R, G, B) per update; a throwing panel call is swallowed. */
export function createCrestronLedDriver(crestron: CrestronGlobal, deps: Pick<LedDeps, 'onError'> = {}): LedDriver {
  return {
    kind: 'crestron',
    setStatus: (status) => {
      const values = CRESTRON_SIGNALS[status];
      try {
        SIGNALS.forEach((s, i) => crestron.sendBooleanSignal(s, values[i] ?? false));
      } catch (e) {
        deps.onError?.(e);
      }
      return Promise.resolve();
    },
  };
}

function crestronOf(host: { Crestron?: unknown }): CrestronGlobal | null {
  const c = host.Crestron as Partial<CrestronGlobal> | undefined;
  return c && typeof c.sendBooleanSignal === 'function' ? (c as CrestronGlobal) : null;
}

/** OP-LED-QBIC probe: GET /v1/led, any 2xx = Qbic; error, non-2xx or timeout (DEV-D-108, 2 s) = not Qbic. */
async function probeQbic(deps: LedDeps): Promise<boolean> {
  const fetchFn = deps.fetchFn ?? defaultFetch;
  const controller = new AbortController();
  const job = `led-probe-timeout-${++probeSeq}`;
  const timeout = new Promise<boolean>((resolve) => {
    deps.scheduler.after(job, deps.probeTimeoutMs ?? QBIC_PROBE_TIMEOUT_MS, () => {
      controller.abort();
      resolve(false);
    });
  });
  const request = fetchFn(`${QBIC_ORIGIN}/v1/led`, { method: 'GET', signal: controller.signal }).then(
    (r) => r.ok,
    () => false,
  );
  try {
    return await Promise.race([request, timeout]);
  } finally {
    deps.scheduler.cancel(job);
  }
}

/** FLAG-LED / led.yaml probe_order: Qbic first, then a `Crestron` global, else the no-op driver. One probe per call. */
export async function detectLedDriver(deps: LedDeps): Promise<LedDriver> {
  if (await probeQbic(deps)) return createQbicLedDriver(deps);
  const crestron = crestronOf(deps.host ?? (globalThis as { Crestron?: unknown }));
  if (crestron) return createCrestronLedDriver(crestron, deps);
  return noopLedDriver;
}

export interface LedDetector {
  /** Resolves the driver; a found driver is kept for the page life, "none" is not kept (next call probes again). */
  detect(): Promise<LedDriver>;
}

/** led.yaml probe_order rule: the first supported driver is kept; when none is found every later call probes Qbic again. */
export function createLedDetector(deps: LedDeps): LedDetector {
  let found: LedDriver | null = null;
  let inFlight: Promise<LedDriver> | null = null;
  return {
    detect: () => {
      if (found) return Promise.resolve(found);
      if (inFlight) return inFlight;
      inFlight = detectLedDriver(deps).then((d) => {
        inFlight = null;
        if (d.kind !== 'none') found = d;
        return d;
      });
      return inFlight;
    },
  };
}
