/** One in-memory booking for both server shapes (SCH-BOOKING-NORMALIZED, DEV-D-86). Times are epoch ms. */
export interface Organizer {
  id: string;
  fullName: string;
  email: string | null;
  role: string | null;
}

export interface CheckInMarks {
  /** Remote (QR / app) check-in: who and when (checkIn.checkInBy / event checkinBy). */
  remoteBy: string | null;
  remoteAt: number | null;
  /** Strict (on the display) check-in. */
  strictBy: string | null;
  strictAt: number | null;
}

export interface Booking {
  id: string;
  title: string;
  start: number;
  end: number;
  roomIds: string[];
  organizer: Organizer;
  /** organizer.role === 'ROLE_DEVICE' */
  madeByDisplay: boolean;
  /** isVisible ?? !room.privateByDefault (DEV-D-86) */
  isVisible: boolean;
  checkIn: CheckInMarks;
  stopReason: string | null;
}

export interface DateRange {
  start: number;
  end: number;
}

export interface RoomRef {
  id: string;
  name: string;
  privateByDefault: boolean;
}

export const NO_CHECKIN: CheckInMarks = { remoteBy: null, remoteAt: null, strictBy: null, strictAt: null };

export function overlaps(a: DateRange, b: DateRange): boolean {
  return a.start < b.end && b.start < a.end;
}

export function isActiveAt(b: DateRange, now: number): boolean {
  return b.start <= now && now < b.end;
}

export function isCheckedIn(b: Booking): boolean {
  return b.checkIn.remoteAt !== null || b.checkIn.strictAt !== null || b.checkIn.remoteBy !== null || b.checkIn.strictBy !== null;
}

/** Sort by start, then end, then id — stable order for timelines and lists. */
export function byStart(a: Booking, b: Booking): number {
  return a.start - b.start || a.end - b.end || a.id.localeCompare(b.id);
}
