import type { ReactNode } from 'react';
import type { BookingBodyView, BookingLine, FreeBodyView, QrCaption } from '@/domain/room-status';
import { formatRemain, formatTime, getLanguage, useT, type I18nKey } from '@/i18n';
import { QrCard } from '@/ui/qr';
import styles from './room-display.module.css';

const QR_CAPTIONS: Record<QrCaption, I18nKey> = {
  BOOK_ON_CHECKIN_ON: 'SPACE.QR_SETTINGS.BOOK_ON_CHECKIN_ON',
  BOOK_ON_CHECKIN_OFF: 'SPACE.QR_SETTINGS.BOOK_ON_CHECKIN_OFF',
  BOOK_OFF_CHECKIN_ON: 'SPACE.QR_SETTINGS.BOOK_OFF_CHECKIN_ON',
  BOOK_OFF_CHECKIN_OFF: 'SPACE.QR_SETTINGS.BOOK_OFF_CHECKIN_OFF',
};

export interface RoomTitleProps {
  name: string;
  capacity: number | null;
  inAccent: boolean;
}

/** Seats + room name (accent colour when asked; up to 3 lines, TOK-ROOM-NAME-CLAMP). */
export function RoomTitle({ name, capacity, inAccent }: RoomTitleProps): JSX.Element {
  const t = useT();
  return (
    <>
      {capacity !== null ? <div className={styles.capacity}>{t('SPACE.SEATS_COUNT', { COUNT: capacity })}</div> : null}
      <h1 className={[styles.name, 'u-clamp-lines', inAccent ? styles.accent : ''].join(' ')}>{name}</h1>
    </>
  );
}

export interface TimeFormat {
  zone: string;
  hour12: boolean;
}

export interface FreeBodyProps extends RoomTitleProps, TimeFormat {
  free: FreeBodyView | null;
  /** Quick-booking block of the booking panel (part 'free'). */
  panel: ReactNode;
  roomQrLink: string | null;
  onOpenQr(link: string): void;
}

/** Body A (SCR-ROOM body.free): seats, name, "Available for …", quick buttons (panel), room QR. */
export function FreeBody({ free, panel, roomQrLink, onOpenQr, zone, hour12, ...title }: FreeBodyProps): JSX.Element {
  const t = useT();
  const freeFor = free?.freeFor ?? null;
  return (
    <div className={styles.body} data-testid="room.body.free">
      <RoomTitle {...title} />
      {freeFor ? (
        <div className={styles.freeUntil}>
          {t('SPACE.FREE_UNTIL', { FOR: formatRemain(freeFor.minutes), UNTIL: formatTime(freeFor.until, zone, getLanguage(), { hour12 }) })}
        </div>
      ) : null}
      {panel}
      {free?.roomQr && roomQrLink ? (
        <QrCard value={roomQrLink} caption={t(QR_CAPTIONS[free.roomQr.caption])} openLabel={t('SPACE.QR_TITLE')} onOpen={() => onOpenQr(roomQrLink)} />
      ) : null}
    </div>
  );
}

function LineText({ line, zone, hour12 }: { line: BookingLine } & TimeFormat): JSX.Element {
  const t = useT();
  const time = (ms: number): string => formatTime(ms, zone, getLanguage(), { hour12 });
  if (line.kind === 'confirm-until') return <>{t('SPACE.CONFIRM_UNTIL', { UNTIL: time(line.until) })}</>;
  if (line.kind === 'locked-until') return <>{t('SPACE.BOOKING_INFO.BOOKED_UNTIL', { BOOKED_UNTIL: time(line.end) })}</>;
  return (
    <>
      <span className={styles.rowLabel}>{t('SPACE.BOOKING_INFO.BOOKED')}</span>{' '}
      {t('SPACE.BOOKING_INFO.BOOKED_FROM_TO', { BOOKED_FROM: time(line.start), BOOKED_UNTIL: time(line.end) })}
    </>
  );
}

export interface BookingBodyProps extends TimeFormat {
  name: string;
  capacity: number | null;
  info: BookingBodyView;
  /** Buttons row of the booking panel (part 'booking'). */
  panel: ReactNode;
  checkinQrLink: string | null;
  onOpenQr(link: string): void;
}

/** Body C (SCR-ROOM part booking-info): time line, event name and organizer per privacy, buttons (panel), check-in QR. */
export function BookingBody({ name, capacity, info, panel, checkinQrLink, onOpenQr, zone, hour12 }: BookingBodyProps): JSX.Element {
  const t = useT();
  const b = info.booking;
  const organizer = b.organizer.fullName || b.organizer.email || '';
  return (
    <div className={styles.body} data-testid="room.body.booking">
      <RoomTitle name={name} capacity={capacity} inAccent={info.nameInAccent} />
      <div className={styles.row}>
        <LineText line={info.line} zone={zone} hour12={hour12} />
      </div>
      {info.showTitle ? (
        <div className={[styles.row, 'u-clamp-lines'].join(' ')}>
          <span className={styles.rowLabel}>{t('SPACE.BOOKING_INFO.EVENT_NAME')}</span> {b.title}
        </div>
      ) : null}
      {info.showOrganizer ? (
        <div className={[styles.row, 'u-clamp-lines'].join(' ')}>
          <span className={styles.rowLabel}>{t('SPACE.BOOKING_INFO.ORGANIZER')}</span> {organizer}
        </div>
      ) : null}
      <div className={styles.actions}>
        {panel}
        {info.checkinQr && checkinQrLink ? (
          <QrCard value={checkinQrLink} caption={t('SPACE.CHECKIN_QR_AVAILABLE_TEXT')} openLabel={t('SPACE.QR_TITLE')} separator={false} onOpen={() => onOpenQr(checkinQrLink)} />
        ) : null}
      </div>
    </div>
  );
}
