import * as Sentry from '@sentry/react';
import type { Breadcrumb, ErrorEvent } from '@sentry/react';
import type { Clock } from '@/kernel';
import { createTelemetryCore, noopTelemetry, type Telemetry, type TelemetrySink } from './telemetry';
import { redact, redactString, REDACTED } from './redact';

/** The part of the Sentry 8 SDK the adapter uses (tests pass a fake). */
export type SentrySdk = Pick<
  typeof Sentry,
  'init' | 'captureException' | 'captureMessage' | 'setUser' | 'setTag' | 'setExtra' | 'flush' | 'makeBrowserOfflineTransport' | 'makeFetchTransport'
>;

export interface SentryTelemetryOptions {
  /** Build env `VITE_SENTRY_DSN` or runtime config `sentryDsn`; empty → no-op telemetry, SDK not started. */
  dsn: string | null | undefined;
  environment?: string;
  release?: string;
  clock: Clock;
  sdk?: SentrySdk;
}

/** beforeSend: whole event through `redact`; request body/cookies/query dropped; user reduced to its id. */
export function redactEvent<T extends ErrorEvent>(event: T): T {
  const out = redact(event) as T;
  if (out.request) {
    delete out.request.data;
    delete out.request.cookies;
    if (out.request.url) out.request.url = redactString(out.request.url);
  }
  if (event.user) out.user = event.user.id !== undefined ? { id: event.user.id } : {};
  return out;
}

/** beforeBreadcrumb: strings redacted (URLs lose `authorization=`), bodies dropped; console arguments removed. */
export function redactBreadcrumb(crumb: Breadcrumb): Breadcrumb {
  const out = redact(crumb) as Breadcrumb;
  if (out.category === 'console' && out.data) out.data = { arguments: REDACTED };
  return out;
}

function sentrySink(sdk: SentrySdk): TelemetrySink {
  return {
    error: (error, extras) => {
      sdk.captureException(error, { extra: extras });
    },
    event: (name, level, extras) => {
      sdk.captureMessage(name, { level, extra: extras, tags: { event_name: name } });
    },
    context: (ctx) => {
      if (ctx.deviceId !== undefined) sdk.setUser(ctx.deviceId ? { id: ctx.deviceId } : null);
      if (ctx.tenant !== undefined) sdk.setTag('tenant', ctx.tenant || 'unknown');
      if (ctx.deviceName !== undefined) sdk.setExtra('unspotDevice', ctx.deviceName);
    },
    flush: (ms) => sdk.flush(ms),
  };
}

/**
 * Sentry 8 adapter (ADR-0001, TEL-INIT, DEV-D-36, -39, -40): sendDefaultPii off, offline transport (STO-TEL-QUEUE),
 * default integrations (global onerror + unhandledrejection, no console capture), redaction in beforeSend / beforeBreadcrumb.
 * Call once, before the app code (T01). Empty DSN → `noopTelemetry`.
 */
export function createSentryTelemetry(options: SentryTelemetryOptions): Telemetry {
  if (!options.dsn) return noopTelemetry;
  const sdk = options.sdk ?? Sentry;
  sdk.init({
    dsn: options.dsn,
    environment: options.environment,
    release: options.release,
    sendDefaultPii: false,
    transport: sdk.makeBrowserOfflineTransport(sdk.makeFetchTransport),
    beforeSend: (event) => redactEvent(event),
    beforeBreadcrumb: (crumb) => redactBreadcrumb(crumb),
  });
  return createTelemetryCore(sentrySink(sdk), options.clock);
}
