/** Inputs of the two display QR links (product/contract/deep-links.yaml). */
export interface QrLinkInput {
  /** MOBILE_ROUTER_SUB_DOMAIN (config). */
  mobileRouterSubDomain: string | null;
  /** SERVER_HOST (config). */
  serverHost: string | null;
  /** company.subDomain (OP-AUTH-COMPANY-CARD), else the session's. */
  subDomain: string | null;
  /** me.device.space.officeId; null → the key is left out (DEV-D-101). */
  officeId: string | null;
  /** me.device.space.id */
  roomId: string;
}

export interface QrLinks {
  /** LINK-DISPLAY-QR-ROOM (action empty). */
  room: string;
  /** LINK-DISPLAY-QR-CHECKIN (action=bookingByQR). */
  checkin: string;
}

function link(input: QrLinkInput, action: string): string {
  const q = [
    ...(input.officeId ? [`officeId=${encodeURIComponent(input.officeId)}`] : []),
    `meetingRoom=${encodeURIComponent(input.roomId)}`,
    `action=${action}`,
  ].join('&');
  const target = `${input.subDomain}.${input.serverHost}/meeting-rooms?${q}`;
  return `https://${input.mobileRouterSubDomain}.${input.serverHost}/?target=${encodeURIComponent(target)}`;
}

/** Both links, or null when a host part is not configured (no QR is drawn then). */
export function qrLinks(input: QrLinkInput): QrLinks | null {
  if (!input.mobileRouterSubDomain || !input.serverHost || !input.subDomain) return null;
  return { room: link(input, ''), checkin: link(input, 'bookingByQR') };
}
