import { z } from 'zod';
import type { Booking, Organizer, RoomRef } from '@/domain/booking-model';
import { issuesOf, OPS, type OnInvalid } from './ops';

/** ISO 8601 with offset → must parse. */
const isoDate = z.string().refine((s) => !Number.isNaN(Date.parse(s)), 'bad-date');
const markCode = z.union([z.number(), z.string()]).nullish();

const organizerSchema = z.object({
  id: z.string().nullish(),
  email: z.string().nullish(),
  fullName: z.string().nullish(),
  firstName: z.string().nullish(),
  lastName: z.string().nullish(),
  role: z.string().nullish(),
});
type OrganizerDto = z.infer<typeof organizerSchema>;

/** SCH-BOOKING-LIST-ITEM (only the fields the display reads). */
export const listItemSchema = z.object({
  id: z.string().min(1),
  title: z.string().nullish(),
  start: isoDate,
  end: isoDate,
  room: z.object({ id: z.string(), privateByDefault: z.boolean().nullish() }).nullish(),
  organizer: organizerSchema.nullish(),
  checkIn: z
    .object({ checkInAt: isoDate.nullish(), checkInBy: markCode, strictCheckInAt: isoDate.nullish(), strictCheckInBy: markCode })
    .nullish(),
  isVisible: z.boolean().nullish(),
  organizerEmail: z.string().nullish(),
});
export type BookingListItemDto = z.infer<typeof listItemSchema>;

/** SCH-BOOKING-EVENT (data of booking_created / _updated / _deleted). */
export const eventDataSchema = z.object({
  id: z.string().min(1),
  title: z.string().nullish(),
  start: isoDate,
  end: isoDate,
  organizer: organizerSchema.nullish(),
  spaces: z.array(z.object({ id: z.string() })).nullish(),
  checkinAt: isoDate.nullish(),
  checkinBy: markCode,
  strictCheckinAt: isoDate.nullish(),
  strictCheckinBy: markCode,
  stopReason: markCode,
  isVisible: z.boolean().nullish(),
  organizerEmail: z.string().nullish(),
});
export type BookingEventDto = z.infer<typeof eventDataSchema>;

const ms = (iso: string | null | undefined): number | null => (iso ? Date.parse(iso) : null);
const code = (v: number | string | null | undefined): string | null => (v === null || v === undefined ? null : String(v));

/** Trimmed fullName; an empty one is rebuilt from first/last name (SCH-BOOKING-NORMALIZED); no organizer → email only. */
function toOrganizer(o: OrganizerDto | null | undefined, organizerEmail: string | null | undefined): Organizer {
  if (!o) return { id: '', fullName: '', email: organizerEmail ?? null, role: null };
  const full = o.fullName?.trim() ?? '';
  const rebuilt = full || [o.firstName ?? '', o.lastName ?? ''].join(' ').trim();
  return { id: o.id ?? '', fullName: rebuilt, email: o.email ?? null, role: o.role ?? null };
}

export interface ListContext {
  /** Fallback room when an item lacks `room` (privateByDefault source). */
  room?: Pick<RoomRef, 'id' | 'privateByDefault'>;
}

export function fromListDto(dto: BookingListItemDto, ctx: ListContext = {}): Booking {
  const room = dto.room ?? (ctx.room ? { id: ctx.room.id, privateByDefault: ctx.room.privateByDefault } : null);
  const organizer = toOrganizer(dto.organizer, dto.organizerEmail);
  return {
    id: dto.id,
    title: dto.title ?? '',
    start: Date.parse(dto.start),
    end: Date.parse(dto.end),
    roomIds: room ? [room.id] : [],
    organizer,
    madeByDisplay: organizer.role === 'ROLE_DEVICE',
    isVisible: dto.isVisible ?? !(room?.privateByDefault ?? false),
    checkIn: {
      remoteBy: code(dto.checkIn?.checkInBy),
      remoteAt: ms(dto.checkIn?.checkInAt),
      strictBy: code(dto.checkIn?.strictCheckInBy),
      strictAt: ms(dto.checkIn?.strictCheckInAt),
    },
    stopReason: null,
  };
}

export interface EventContext {
  /** Rooms the screen knows (room card on the room screen, rooms list on the board) — privateByDefault source (DEV-D-86). */
  knownRooms: ReadonlyArray<Pick<RoomRef, 'id' | 'privateByDefault'>>;
  onInvalid?: OnInvalid;
}

export function fromEventDto(dto: BookingEventDto, ctx: EventContext): Booking {
  const roomIds = (dto.spaces ?? []).map((s) => s.id);
  const known = ctx.knownRooms.find((r) => r.id === roomIds[0]);
  const organizer = toOrganizer(dto.organizer, dto.organizerEmail);
  return {
    id: dto.id,
    title: dto.title ?? '',
    start: Date.parse(dto.start),
    end: Date.parse(dto.end),
    roomIds,
    organizer,
    madeByDisplay: organizer.role === 'ROLE_DEVICE',
    isVisible: dto.isVisible ?? !(known?.privateByDefault ?? false),
    checkIn: { remoteBy: code(dto.checkinBy), remoteAt: ms(dto.checkinAt), strictBy: code(dto.strictCheckinBy), strictAt: ms(dto.strictCheckinAt) },
    stopReason: code(dto.stopReason),
  };
}

export function parseListItem(raw: unknown): BookingListItemDto | null {
  const r = listItemSchema.safeParse(raw);
  return r.success ? r.data : null;
}

export function parseEventData(raw: unknown): BookingEventDto | null {
  const r = eventDataSchema.safeParse(raw);
  return r.success ? r.data : null;
}

export interface ListBodyOptions extends ListContext {
  onInvalid?: OnInvalid;
}

/** `body` of OP-BOOKINGS-LIST → Booking[]; each bad item is dropped and reported, the rest kept. */
export function bookingsFromListBody(body: unknown, opts: ListBodyOptions = {}): Booking[] {
  const items = (body as { roomBookings?: unknown } | null)?.roomBookings;
  if (!Array.isArray(items)) {
    opts.onInvalid?.({ op: OPS.bookingsList, issues: ['roomBookings:invalid_type'] });
    return [];
  }
  const out: Booking[] = [];
  items.forEach((raw, index) => {
    const r = listItemSchema.safeParse(raw);
    if (r.success) out.push(fromListDto(r.data, opts));
    else opts.onInvalid?.({ op: OPS.bookingsList, index, issues: issuesOf(r.error) });
  });
  return out;
}

/** `data` of a booking event → Booking, or null (reported) when it does not parse. */
export function bookingFromEvent(raw: unknown, ctx: EventContext): Booking | null {
  const r = eventDataSchema.safeParse(raw);
  if (r.success) return fromEventDto(r.data, ctx);
  ctx.onInvalid?.({ op: 'EVT-BOOKING', issues: issuesOf(r.error) });
  return null;
}
