/** Typed app events (ARCHITECTURE §3). Adding a variant is a contract-first change. */
export type AppEvent =
  | { type: 'session.expired'; reason: string }
  | { type: 'device.deleted'; deviceId: string }
  | { type: 'device.reloadRequested'; deviceId?: string }
  | { type: 'connectivity.changed'; state: 'online' | 'offline' | 'reconnecting' }
  | { type: 'realtime.reconnected' }
  | { type: 'day.changed'; day: string }
  | { type: 'idle.timeout' }
  | { type: 'app.reinitRequested' };

export type AppEventType = AppEvent['type'];
type Handler<K extends AppEventType> = (e: Extract<AppEvent, { type: K }>) => void;

export interface EventBus {
  emit(e: AppEvent): void;
  on<K extends AppEventType>(type: K, handler: Handler<K>): () => void;
}

export function createEventBus(): EventBus {
  const handlers = new Map<AppEventType, Set<(e: AppEvent) => void>>();
  return {
    emit(e) {
      for (const h of [...(handlers.get(e.type) ?? [])]) {
        try {
          h(e);
        } catch (x) {
          console.error(`[events] handler of ${e.type} failed`, x);
        }
      }
    },
    on(type, handler) {
      const set = handlers.get(type) ?? new Set();
      const h = handler as (e: AppEvent) => void;
      set.add(h);
      handlers.set(type, set);
      return () => set.delete(h);
    },
  };
}
