import { err, ok, type AppError, type Result } from '@/kernel';
import { cancelOutcomeFromMessage, OPS, refineRefusal, type CancelOutcome } from '@/contract';
import { cachePatches } from '@/data/queries';
import { staleSession, useCommand, type Command, type CommandContext } from './command-runner';

const USER_MARK = '10';
const STOP_BY_USER = '10';

export interface CancelRoomBookingEffect {
  bookingId: string;
  /** From the server answer (DEV-D-135); `unknown` → the day was re-read. */
  outcome: CancelOutcome;
}

async function cancelRoomBooking(ctx: CommandContext, input: { bookingId: string }): Promise<Result<CancelRoomBookingEffect, AppError>> {
  const { bookingId } = input;
  const r = await ctx.http.delete(`/api/bookings/meeting-room/${encodeURIComponent(bookingId)}`, { actionBy: 'Display' }, { op: OPS.cancelRoom });
  if (!ctx.isCurrent()) return staleSession(OPS.cancelRoom);
  if (!r.ok) {
    const e = refineRefusal(OPS.cancelRoom, r.error);
    if (e.code === 'booking.not_found') cachePatches.removeBooking(ctx.qc, ctx.generation, bookingId); // wanted state holds
    if (e.kind === 'outcome-unknown' || e.code === 'booking.not_found') await ctx.rereadDays();
    return err(e);
  }
  const outcome = cancelOutcomeFromMessage(r.value.message);
  if (outcome === 'deleted') cachePatches.removeBooking(ctx.qc, ctx.generation, bookingId);
  else if (outcome === 'stopped') {
    const now = ctx.clock.now();
    // a booking_updated that already arrived carries the server end; keep it
    cachePatches.patchBooking(ctx.qc, ctx.generation, bookingId, (b) => (b.stopReason ? b : { ...b, end: Math.min(b.end, now), stopReason: STOP_BY_USER }));
  } else await ctx.rereadDays();
  return ok({ bookingId, outcome });
}

/** OP-BOOKINGS-CANCEL-ROOM (room screen Remove / Stop): the server decides stop vs delete. */
export function useCancelRoomBookingCommand(): Command<{ bookingId: string }, CancelRoomBookingEffect> {
  return useCommand(cancelRoomBooking);
}

export interface CheckInEffect {
  bookingId: string;
  mode: 'remote' | 'strict';
}

export interface CheckInInput {
  bookingId: string;
  /** true asks for strict check-in, false for remote (the mode of the open window, DEV-D-55). */
  byQr: boolean;
}

async function checkIn(ctx: CommandContext, input: CheckInInput): Promise<Result<CheckInEffect, AppError>> {
  const { bookingId, byQr } = input;
  const r = await ctx.http.request({
    method: 'PATCH',
    path: `/api/bookings/${encodeURIComponent(bookingId)}/checkin`,
    query: { actionBy: 'Display' },
    body: { byQr },
    op: OPS.checkIn,
  });
  if (!ctx.isCurrent()) return staleSession(OPS.checkIn);
  const mode = byQr ? 'strict' : 'remote';
  const mark = (): void => {
    const at = ctx.clock.now();
    cachePatches.patchBooking(ctx.qc, ctx.generation, bookingId, (b) => {
      if (byQr) return b.checkIn.strictBy ? b : { ...b, checkIn: { ...b.checkIn, strictBy: USER_MARK, strictAt: at } };
      return b.checkIn.remoteBy ? b : { ...b, checkIn: { ...b.checkIn, remoteBy: USER_MARK, remoteAt: at } };
    });
  };
  if (!r.ok) {
    const e = refineRefusal(OPS.checkIn, r.error);
    if (e.code === 'booking.checkin.already') mark(); // wanted state holds: mark and re-read
    if (e.code === 'booking.not_found') cachePatches.removeBooking(ctx.qc, ctx.generation, bookingId);
    if (e.kind === 'outcome-unknown' || e.code === 'booking.checkin.already' || e.code === 'booking.not_found') await ctx.rereadDays();
    return err(e);
  }
  mark();
  return ok({ bookingId, mode });
}

/** OP-BOOKINGS-CHECKIN ("Begin meeting"). */
export function useCheckInCommand(): Command<CheckInInput, CheckInEffect> {
  return useCommand(checkIn);
}
