import { autoCheckinMarks, type CheckinSettings } from '@/domain/checkin-windows';
import { defaultLength, initialFormRange } from '@/domain/booking-slots';
import { useCreateRoomBookingCommand } from '@/data/commands';
import { useT } from '@/i18n';
import { useClock } from '@/kernel';
import { useUiStore } from '@/state/ui';
import { Button } from '@/ui/primitives';
import { toastError } from './errors';
import type { PanelProps } from './types';
import styles from './booking-actions.module.css';

/** Auto check-in marks the server sets when the booking starts inside an open window (RULE-CHECKIN-AUTO-LOCAL, DEV-D-116). */
export function autoCheckIn(start: number, now: number, settings: CheckinSettings): { remote: boolean; strict: boolean } {
  const m = autoCheckinMarks(start, now, settings);
  return { remote: m.remoteBy !== null, strict: m.strictBy !== null };
}

/**
 * SCR-ROOM body.free.quick: "15/30/60 min" (`view.free.quick`, DT-QUICK-01..08) + "Another" (SPACE.SELECT_TIME).
 * FLOW-DISP-QUICK-BOOK: create from now; title required → form with N minutes; error → toast, buttons enabled.
 */
export function QuickButtons({ view, room, bookings, workingRanges, checkin }: PanelProps): JSX.Element | null {
  const t = useT();
  const clock = useClock();
  const create = useCreateRoomBookingCommand();
  const quick = view.free?.quick ?? null;
  if (!quick) return null;
  const ui = useUiStore.getState;

  const openForm = (minutes: number): void => {
    const range = initialFormRange(bookings, workingRanges, clock.now(), minutes);
    if (range) ui().openForm(range); // no free slot → nothing happens
  };
  const book = async (minutes: number): Promise<void> => {
    if (quick.opensForm) return openForm(minutes);
    const now = clock.now();
    ui().setQuickBookingInFlight(true);
    ui().requestScrollToNow();
    const r = await create.run({ kind: 'quick', roomId: room.id, minutes, autoCheckIn: autoCheckIn(now, now, checkin) });
    ui().setQuickBookingInFlight(false);
    if (!r.ok) toastError(r.error, t); // success: the command put the booking into the cache (DEV-D-135)
  };

  return (
    <div className={styles.quick}>
      {quick.durations.map((n) => (
        <Button key={n} variant="accent-outline" blur disabled={quick.disabled} onClick={() => void book(n)}>
          {`${n} ${t('SPACE.MIN')}`}
        </Button>
      ))}
      {quick.another ? (
        <Button variant="white-outline" blur onClick={() => openForm(defaultLength(room))}>
          {t('SPACE.SELECT_TIME')}
        </Button>
      ) : null}
    </div>
  );
}
