export type ToastType = 'error' | 'success' | 'warning' | 'info';

export interface ToastItem {
  id: number;
  type: ToastType;
  /** Plain text (DEV-D-37), never HTML. */
  message: string;
  title?: string;
}

/** TMR-TOAST: every toast hides after 3000 ms (fe:…/un-toaster.service.ts:16-18). */
export const TOAST_TIMEOUT_MS = 3000;

type Listener = () => void;
let items: readonly ToastItem[] = [];
let seq = 0;
const listeners = new Set<Listener>();
const emit = (): void => listeners.forEach((l) => l());

/**
 * Toast queue rendered by <ToastHost/> (SCR-TOAST). The display raises only error toasts (create / stop / delete
 * failures); success never shows a toast. Newest on top.
 */
export const toast = {
  show(input: Omit<ToastItem, 'id'>): number {
    const id = ++seq;
    items = [{ ...input, id }, ...items];
    emit();
    return id;
  },
  error(message: string, title?: string): number {
    return toast.show({ type: 'error', message, ...(title ? { title } : {}) });
  },
  dismiss(id: number): void {
    if (!items.some((i) => i.id === id)) return;
    items = items.filter((i) => i.id !== id);
    emit();
  },
  clear(): void {
    items = [];
    emit();
  },
  /** @internal used by ToastHost */
  subscribe(listener: Listener): () => void {
    listeners.add(listener);
    return () => listeners.delete(listener);
  },
  /** @internal used by ToastHost */
  snapshot(): readonly ToastItem[] {
    return items;
  },
};
