import type { Clock } from '@/kernel';
import { redact } from './redact';

export type TelemetryLevel = 'info' | 'warning' | 'error';
export type TelemetryExtras = Record<string, unknown>;

export interface TelemetryEventOptions {
  level?: TelemetryLevel;
  extras?: TelemetryExtras;
  /** TMR-TEL-RATE-LIMIT: repeats of the same key within 15 min are suppressed and counted. */
  rateLimitKey?: string;
}

/** TEL-CONTEXT without the leaks (DEV-D-36): device id, tenant tag, device name. */
export interface TelemetryContext {
  deviceId?: string | null;
  tenant?: string | null;
  deviceName?: string | null;
}

/** Port (T33). Every adapter redacts tokens and personal data before anything leaves the page. Never throws. */
export interface Telemetry {
  captureError(error: unknown, options?: Omit<TelemetryEventOptions, 'level'>): void;
  captureEvent(name: string, options?: TelemetryEventOptions): void;
  setContext(context: TelemetryContext): void;
  /** TMR-TEL-FLUSH-BEFORE-RELOAD: resolves true when the queue was sent within `timeoutMs` (default 10 s). */
  flush(timeoutMs?: number): Promise<boolean>;
}

/** What an adapter must provide; `createTelemetryCore` adds redaction and the rate limit on top. */
export interface TelemetrySink {
  error(error: unknown, extras: TelemetryExtras): void;
  event(name: string, level: TelemetryLevel, extras: TelemetryExtras): void;
  context(context: TelemetryContext): void;
  flush(timeoutMs: number): Promise<boolean>;
}

export const TELEMETRY_RATE_LIMIT_MS = 15 * 60_000;
export const TELEMETRY_FLUSH_MS = 10_000;

/** DEV-D-39: error for 5xx and network failures (no status, 0 or negative), warning otherwise. */
export function levelForHttpStatus(status?: number | null): TelemetryLevel {
  if (status === undefined || status === null || status <= 0 || status >= 500) return 'error';
  return 'warning';
}

export const noopTelemetry: Telemetry = {
  captureError: () => undefined,
  captureEvent: () => undefined,
  setContext: () => undefined,
  flush: () => Promise.resolve(true),
};

/** Redaction + TMR-TEL-RATE-LIMIT (suppress repeats per key for 15 min, report `suppressed_count` on the next send). */
export function createTelemetryCore(sink: TelemetrySink, clock: Clock, windowMs = TELEMETRY_RATE_LIMIT_MS): Telemetry {
  const states = new Map<string, { lastSentAt: number; suppressed: number }>();
  const admit = (key: string | undefined, extras: TelemetryExtras): TelemetryExtras | null => {
    if (!key) return extras;
    const now = clock.now();
    const st = states.get(key);
    if (st && now - st.lastSentAt < windowMs) {
      st.suppressed += 1;
      return null;
    }
    states.set(key, { lastSentAt: now, suppressed: 0 });
    return st && st.suppressed > 0 ? { ...extras, suppressed_count: st.suppressed, rate_limit_window_ms: windowMs } : extras;
  };
  const safe = (fn: () => void): void => {
    try {
      fn();
    } catch (e) {
      console.warn('[telemetry] sink failed', redact(e));
    }
  };
  return {
    captureError(error, options = {}) {
      const extras = admit(options.rateLimitKey, options.extras ?? {});
      if (extras) safe(() => sink.error(error, redact(extras) as TelemetryExtras));
    },
    captureEvent(name, options = {}) {
      const extras = admit(options.rateLimitKey, options.extras ?? {});
      if (extras) safe(() => sink.event(name, options.level ?? 'warning', redact(extras) as TelemetryExtras));
    },
    setContext(context) {
      safe(() => sink.context(context));
    },
    flush(timeoutMs = TELEMETRY_FLUSH_MS) {
      return sink.flush(timeoutMs).catch(() => false);
    },
  };
}
