import { useState, type ReactNode } from 'react';
import { Navigate } from 'react-router-dom';
import { useSession } from '@/state/session';
import { BootSpinner } from './boot-spinner';
import { BoardPlaceholder } from './board-placeholder';
import { RoomRoute } from './room-route';
import { ROUTES } from './routes';
import { useBootInit } from './use-boot-init';

/**
 * SCR-ACTIVATION guard: an activated device never sees /login (→ room route). The status is read once at mount: after
 * a successful activation the page reloads (DEV-D-17), so the screen must not navigate away before it.
 */
export function AnonymousOnly({ children }: { children: ReactNode }): JSX.Element {
  const status = useSession((s) => s.status);
  const [initial] = useState(status);
  return initial === 'ready' ? <Navigate to={ROUTES.spacesView} replace /> : <>{children}</>;
}

/** Not authenticated (token or API origin missing) → /login. */
export function ReadyOnly({ children }: { children: ReactNode }): JSX.Element {
  const status = useSession((s) => s.status);
  return status === 'ready' ? <>{children}</> : <Navigate to={ROUTES.login} replace />;
}

/** /spaces/view/new: boot bundle first; a device without a room goes to the board before any room screen (DEV-D-50). */
export function RoomPage(): JSX.Element {
  const boot = useBootInit();
  if (boot.status !== 'ready') return <BootSpinner />;
  if (!boot.me?.device?.space) return <Navigate to={ROUTES.board} replace />;
  return <RoomRoute isSharedRoom={!!boot.room?.isSharedRoom} />;
}

/** /spaces/all: boot bundle first, then the board (placeholder until stage 3). */
export function BoardPage(): JSX.Element {
  const boot = useBootInit();
  if (boot.status !== 'ready') return <BootSpinner />;
  return <BoardPlaceholder hasRoom={!!boot.me?.device?.space} />;
}
