import { useId, useState, type FormEvent } from 'react';
import { formTitle, TITLE_MAX_LENGTH } from '@/domain/booking-slots';
import { useCreateRoomBookingCommand } from '@/data/commands';
import { useT } from '@/i18n';
import { useClock } from '@/kernel';
import { useUiStore } from '@/state/ui';
import { Button } from '@/ui/primitives';
import { TimeRangePicker } from '@/ui/time-picker';
import { toastError } from './errors';
import { autoCheckIn } from './quick-buttons';
import type { PanelProps } from './types';
import styles from './booking-actions.module.css';

/**
 * Body B (SCR-ROOM part booking-form, FLOW-DISP-PLANNED-BOOK): heading, title (validated on submit, RULE-SLOT-TITLE),
 * time range (every change moves the timeline outline), Book (disabled in flight) and Close. Success closes the form;
 * an error shows a toast and keeps the form (ST-FORM-SUBMITTING).
 */
export function BookingForm({ view, room, zone, hour12, checkin }: PanelProps): JSX.Element | null {
  const t = useT();
  const clock = useClock();
  const create = useCreateRoomBookingCommand();
  const [title, setTitle] = useState('');
  const [error, setError] = useState<'required' | 'maxlength' | null>(null);
  const inputId = useId();
  const errorId = useId();
  const form = view.form;
  if (!form) return null;
  const ui = useUiStore.getState;

  const submit = async (e: FormEvent): Promise<void> => {
    e.preventDefault();
    const v = formTitle(title, room.meetingTitleRequired);
    if (!v.ok) return setError(v.error);
    setError(null);
    const { start, end } = form.range;
    const r = await create.run({ kind: 'form', roomId: room.id, title: v.title, start, end, autoCheckIn: autoCheckIn(start, clock.now(), checkin) });
    if (r.ok) ui().closeForm();
    else toastError(r.error, t);
  };

  return (
    <form className={styles.form} noValidate autoComplete="off" onSubmit={(e) => void submit(e)}>
      <h2 className={styles.heading}>{t('SPACE.BOOKING_FORM.CREATE_BOOKING')}</h2>
      <div className={styles.inputGroup}>
        <label htmlFor={inputId} className={styles.inputLabel}>
          {t('SPACE.BOOKING_FORM.TITLE_LABEL')}
        </label>
        <input
          id={inputId}
          className={[styles.input, error ? styles.invalid : ''].join(' ')}
          type="text"
          placeholder={t('SPACE.BOOKING_FORM.ENTER_NAME')}
          value={title}
          maxLength={TITLE_MAX_LENGTH + 1}
          aria-invalid={error !== null}
          aria-describedby={error ? errorId : undefined}
          onChange={(e) => setTitle(e.target.value)}
        />
        {error ? (
          <div id={errorId} className={styles.error}>
            {t(error === 'required' ? 'SPACE.BOOKING_FORM.TITLE_REQUIRED_ERROR' : 'SPACE.BOOKING_FORM.TITLE_MAXLENGTH_ERROR')}
          </div>
        ) : null}
      </div>
      <div className={styles.picker}>
        <TimeRangePicker
          value={form.range}
          freeRanges={form.freeRanges}
          onChange={(range) => ui().setRange(range)}
          zone={zone}
          hour12={hour12}
          maxDurationMinutes={room.maxBookingDuration}
        />
      </div>
      <div className={styles.row}>
        <Button type="submit" variant="success" disabled={create.isPending}>
          {t('SPACE.BOOKING_FORM.BOOK')}
        </Button>
        <Button variant="secondary-outline" onClick={() => ui().closeForm()}>
          {t('SPACE.BOOKING_FORM.CLOSE_FORM')}
        </Button>
      </div>
    </form>
  );
}
