import { useCallback, useState } from 'react';
import { useQueryClient, type QueryClient } from '@tanstack/react-query';
import { appError, err, useClock, type AppError, type Clock, type Result } from '@/kernel';
import { useDataServices, type HttpClient } from '@/data/http';
import { queryKeys } from '@/data/queries';
import { useSessionStore } from '@/state/session';

/** A write: `run` never throws; `isPending` while any run of this hook is in flight (keep the button disabled). */
export interface Command<I, E> {
  run(input: I): Promise<Result<E, AppError>>;
  isPending: boolean;
}

export interface CommandContext {
  qc: QueryClient;
  http: HttpClient;
  clock: Clock;
  /** Session generation the command started under. */
  generation: number;
  /** False once the session changed (logout / re-activation): the answer must be dropped. */
  isCurrent(): boolean;
  /** Re-read every shown day of this generation and wait for it (unknown outcome, DEV-D-135). */
  rereadDays(): Promise<void>;
}

/** Result for an answer that arrived after the session changed (ADR-0004 addendum); never shown (kind aborted). */
export const staleSession = (op: string): Result<never, AppError> => err(appError('aborted', 'session-changed', { op }));

export function useCommand<I, E>(exec: (ctx: CommandContext, input: I) => Promise<Result<E, AppError>>): Command<I, E> {
  const qc = useQueryClient();
  const { http } = useDataServices();
  const store = useSessionStore();
  const clock = useClock();
  const [pending, setPending] = useState(0);
  const run = useCallback(
    async (input: I): Promise<Result<E, AppError>> => {
      const generation = store.getState().generation;
      const ctx: CommandContext = {
        qc,
        http,
        clock,
        generation,
        isCurrent: () => store.getState().generation === generation,
        rereadDays: () => qc.invalidateQueries({ queryKey: queryKeys.bookingsDayAll(generation) }),
      };
      setPending((n) => n + 1);
      try {
        return await exec(ctx, input);
      } finally {
        setPending((n) => n - 1);
      }
    },
    [qc, http, store, clock, exec],
  );
  return { run, isPending: pending > 0 };
}
