import { useEffect, useRef, useSyncExternalStore } from 'react';
import { useScheduler } from '@/kernel';
import { toast, TOAST_TIMEOUT_MS, type ToastItem, type ToastType } from './toasts';
import styles from './toast.module.css';

/** Toast icons (TOK-TOAST-ICONS): 32×32 rounded squares; info has none (fe:…/un-toaster.component.html:3-15). */
function ToastIcon({ type }: { type: ToastType }): JSX.Element | null {
  if (type === 'info') return null;
  return (
    <svg width="32" height="32" viewBox="0 0 32 32" aria-hidden="true" focusable="false">
      <rect className={styles.iconBox} width="32" height="32" rx="10" />
      {type === 'success' ? (
        <path className={styles.glyph} fillRule="evenodd" clipRule="evenodd" d="M22.545 10.1617C23.0081 10.4627 23.1394 11.082 22.8384 11.5451L16.3384 21.5451C16.1774 21.7929 15.9149 21.9568 15.6214 21.9927C15.328 22.0286 15.0338 21.9329 14.8177 21.7312L9.31769 16.5978C8.91393 16.221 8.89211 15.5882 9.26895 15.1845C9.64578 14.7807 10.2786 14.7589 10.6823 15.1357L15.3111 19.4559L21.1616 10.4551C21.4625 9.99207 22.0819 9.86068 22.545 10.1617Z" />
      ) : null}
      {type === 'error' ? (
        <path className={styles.glyph} fillRule="evenodd" clipRule="evenodd" d="M9.70711 8.29289C9.31658 7.90237 8.68342 7.90237 8.29289 8.29289C7.90237 8.68342 7.90237 9.31658 8.29289 9.70711L14.5858 16L8.29289 22.2929C7.90237 22.6834 7.90237 23.3166 8.29289 23.7071C8.68342 24.0976 9.31658 24.0976 9.70711 23.7071L16 17.4142L22.2929 23.7071C22.6834 24.0976 23.3166 24.0976 23.7071 23.7071C24.0976 23.3166 24.0976 22.6834 23.7071 22.2929L17.4142 16L23.7071 9.70711C24.0976 9.31658 24.0976 8.68342 23.7071 8.29289C23.3166 7.90237 22.6834 7.90237 22.2929 8.29289L16 14.5858L9.70711 8.29289Z" />
      ) : null}
      {type === 'warning' ? (
        <>
          <path className={styles.glyph} fillRule="evenodd" clipRule="evenodd" d="M24 16C24 20.4183 20.4183 24 16 24C11.5817 24 8 20.4183 8 16C8 11.5817 11.5817 8 16 8C20.4183 8 24 11.5817 24 16ZM26 16C26 21.5228 21.5228 26 16 26C10.4772 26 6 21.5228 6 16C6 10.4772 10.4772 6 16 6C21.5228 6 26 10.4772 26 16ZM15.9999 21C16.5522 21 16.9999 20.5523 16.9999 20C16.9999 19.4477 16.5522 19 15.9999 19C15.4477 19 14.9999 19.4477 14.9999 20C14.9999 20.5523 15.4477 21 15.9999 21Z" />
          <path className={styles.glyphStroke} d="M16 16V12" strokeWidth="2" strokeLinecap="round" />
        </>
      ) : null}
    </svg>
  );
}

function ToastView({ item }: { item: ToastItem }): JSX.Element {
  return (
    <div
      role={item.type === 'error' || item.type === 'warning' ? 'alert' : 'status'}
      className={[styles.toast, styles[item.type]].join(' ')}
      onClick={() => toast.dismiss(item.id)}
    >
      <span className={styles.icon}>
        <ToastIcon type={item.type} />
      </span>
      <div className={styles.content}>
        {item.title ? <div className={styles.title}>{item.title}</div> : null}
        <div className={styles.message}>{item.message}</div>
      </div>
    </div>
  );
}

/**
 * Renders the toast queue once (app shell, stays mounted under the offline overlay). Each toast hides after 3 s via
 * the Scheduler job `toast-3s:<id>` (TMR-TOAST); a tap dismisses it. Needs KernelProvider.
 */
export function ToastHost(): JSX.Element {
  const items = useSyncExternalStore(toast.subscribe, toast.snapshot, toast.snapshot);
  const scheduler = useScheduler();
  const scheduled = useRef(new Set<number>());

  useEffect(() => {
    for (const item of items) {
      if (scheduled.current.has(item.id)) continue;
      scheduled.current.add(item.id);
      scheduler.after(`toast-3s:${item.id}`, TOAST_TIMEOUT_MS, () => toast.dismiss(item.id));
    }
    const alive = new Set(items.map((i) => i.id));
    for (const id of scheduled.current) {
      if (!alive.has(id)) {
        scheduler.cancel(`toast-3s:${id}`);
        scheduled.current.delete(id);
      }
    }
  }, [items, scheduler]);

  useEffect(() => {
    const set = scheduled.current;
    return () => {
      set.forEach((id) => scheduler.cancel(`toast-3s:${id}`));
      set.clear();
    };
  }, [scheduler]);

  return (
    <div className={styles.container} aria-live="assertive">
      {items.map((item) => (
        <ToastView key={item.id} item={item} />
      ))}
    </div>
  );
}
