import type { QueryClient } from '@tanstack/react-query';
import type { EventBus } from '@/kernel';
import type { Booking, RoomRef } from '@/domain/booking-model';
import { bookingFromEvent, parseCheckInSettingsEvent, parseRoomSettingsEvent, type Me, type OnInvalid, type RoomDetail } from '@/contract';
import { bookingMatchesScope, cachePatches, queryKeys, type BookingsDayScope } from '@/data/queries';
import type { RealtimeClient, RealtimeMessage } from '@/realtime/mercure-client';

/** Rooms the shown screen knows (room card on the room screen; rooms list on the board) — DEV-D-86. */
export type KnownRoom = Pick<RoomRef, 'id' | 'privateByDefault'>;

/** Everything a row handler may read or do. Built once per message by `startRealtimeBridge`. */
export interface BridgeContext {
  queryClient: QueryClient;
  events: EventBus;
  /** Session generation read when the message arrived (all patches are scoped to it). */
  generation: number;
  /** Own device id (`me.device.id`), null until OP-PROFILE-ME answered. */
  deviceId: string | null;
  knownRooms: readonly KnownRoom[];
  onInvalid?: OnInvalid;
}

export type BridgeHandler = (data: unknown, ctx: BridgeContext) => void;

export interface BridgeDeps {
  client: Pick<RealtimeClient, 'subscribe'>;
  queryClient: QueryClient;
  events: EventBus;
  /** Current session generation (state/session). */
  generation: () => number;
  deviceId: () => string | null;
  knownRooms: () => readonly KnownRoom[];
  /** Error sink (telemetry): the error and the action only, never the payload (DEV-D-36, -97). */
  report?: (error: unknown, where: string) => void;
  /** Dropped event items (zod issues only). */
  onInvalid?: OnInvalid;
}

/** booking_updated adds an unknown booking on the ROOM screen only (events.yaml EVT-BOOKING-UPDATED reaction). */
const roomScopeOnly = (b: Booking, s: BookingsDayScope): boolean => s.scope === 'room' && bookingMatchesScope(b, s);

const booking = (data: unknown, ctx: BridgeContext): Booking | null =>
  bookingFromEvent(data, { knownRooms: ctx.knownRooms, onInvalid: ctx.onInvalid });

const idOf = (data: unknown, key: string): string | null => {
  if (!data || typeof data !== 'object') return null;
  const v = (data as Record<string, unknown>)[key];
  return typeof v === 'string' && v ? v : null;
};

/**
 * ADR-0004 §3: one row per EVT-* of product/contract/events.yaml (action → patch | AppEvent). Unknown actions are
 * dropped (`not_handled`). Filters: `bookingMatchesScope` = own room + shown day (room) / shown day (board).
 */
export const realtimeTable: Readonly<Record<string, BridgeHandler>> = {
  // EVT-BOOKING-CREATED: insert where the scope matches and the id is unknown (dedup of the own create answer).
  booking_created: (data, ctx) => {
    const b = booking(data, ctx);
    if (b) cachePatches.insertBooking(ctx.queryClient, ctx.generation, b);
  },
  // EVT-BOOKING-UPDATED: replace by id where known (room + board); unknown → added on the room screen only.
  booking_updated: (data, ctx) => {
    const b = booking(data, ctx);
    if (!b) return;
    cachePatches.replaceBooking(ctx.queryClient, ctx.generation, b);
    cachePatches.insertBooking(ctx.queryClient, ctx.generation, b, roomScopeOnly);
  },
  // EVT-BOOKING-DELETED: remove by id everywhere (the payload is the full booking).
  booking_deleted: (data, ctx) => {
    const id = idOf(data, 'id');
    if (id) cachePatches.removeBooking(ctx.queryClient, ctx.generation, id);
  },
  // EVT-COMPANY-CHECKIN-SETTINGS-UPDATED: patch the company defaults.
  checkin_settings_updated: (data, ctx) => {
    const s = parseCheckInSettingsEvent(data);
    if (s) cachePatches.setCheckInDefaults(ctx.queryClient, ctx.generation, s);
    else ctx.onInvalid?.({ op: 'EVT-COMPANY-CHECKIN-SETTINGS-UPDATED', issues: ['data:invalid'] });
  },
  // EVT-ROOM-CHECKIN-SETTINGS-UPDATED: own room only (cachePatches checks the room id against me.device.space).
  room_settings_updated: (data, ctx) => {
    const s = parseRoomSettingsEvent(data);
    if (s) cachePatches.setRoomCheckInSettings(ctx.queryClient, ctx.generation, s.roomId, s.settings);
    else ctx.onInvalid?.({ op: 'EVT-ROOM-CHECKIN-SETTINGS-UPDATED', issues: ['data:invalid'] });
  },
  // EVT-DEVICE-DELETED: own id → logout on every screen (DEV-D-22) through state/session.
  device_deleted: (data, ctx) => {
    const id = idOf(data, 'id');
    if (id && ctx.deviceId && id === ctx.deviceId) ctx.events.emit({ type: 'device.deleted', deviceId: id });
  },
  // EVT-DEVICE-RELOAD: no deviceId (all devices) or the own id → kiosk runtime flushes telemetry and reloads (DEV-D-10).
  device_reload: (data, ctx) => {
    const target = idOf(data, 'deviceId');
    if (target === null) ctx.events.emit({ type: 'device.reloadRequested' });
    else if (ctx.deviceId && target === ctx.deviceId) ctx.events.emit({ type: 'device.reloadRequested', deviceId: target });
  },
  // EVT-OFFICE-STATUS-UPDATED: ignored on every screen (DEV-D-74).
  office_visited_status_updated: () => undefined,
};

/**
 * Subscribes the table to the stream. Each message runs isolated (a throwing row is reported, the stream goes on);
 * a message is dropped when the session generation changed since the bridge started (logout / re-activation).
 * Returns stop().
 */
export function startRealtimeBridge(deps: BridgeDeps, table: Readonly<Record<string, BridgeHandler>> = realtimeTable): () => void {
  const startGeneration = deps.generation();
  return deps.client.subscribe((m: RealtimeMessage) => {
    const handler = Object.prototype.hasOwnProperty.call(table, m.action) ? table[m.action] : undefined;
    if (!handler) return;
    const generation = deps.generation();
    if (generation !== startGeneration) return;
    try {
      handler(m.data, {
        queryClient: deps.queryClient,
        events: deps.events,
        generation,
        deviceId: deps.deviceId(),
        knownRooms: deps.knownRooms(),
        onInvalid: deps.onInvalid,
      });
    } catch (e) {
      deps.report?.(e, `bridge:${m.action}`);
    }
  });
}

/** Room screen: the own room card from the cache (`me.device.space.id` + `roomDetail.privateByDefault`). */
export function knownRoomsFromCache(qc: QueryClient, generation: number): KnownRoom[] {
  const me = qc.getQueryData<Me>(queryKeys.me(generation));
  const roomId = me?.device?.space?.id;
  if (!roomId) return [];
  const detail = qc.getQueryData<RoomDetail>(queryKeys.roomDetail(generation, roomId));
  return [{ id: roomId, privateByDefault: detail?.privateByDefault ?? false }];
}
