import { useEffect, useState } from 'react';
import { RoomScreen } from '@/features/room-display';
import { BookingPanel } from '@/features/booking-actions';
import { LedStatus } from '@/features/led-status';
import { noopLedDriver, type LedDriver } from '@/platform/led';
import { useAppContainer } from '@/app/providers';
import { Menu } from './menu';

/**
 * SCR-ROOM composition (ARCHITECTURE §3 slots): the room screen gets the booking panel and the menu (none on a shared
 * room, DEV-D-91); LedStatus gets the no-op driver until the detector resolves, probed in parallel with the first bookings read
 * (DEV-D-108). The reload button (RLD-MANUAL) goes through the one reload of app/bootstrap.
 */
export function RoomRoute({ isSharedRoom }: { isSharedRoom: boolean }): JSX.Element {
  const { ledDetector, reload } = useAppContainer();
  const [driver, setDriver] = useState<LedDriver>(noopLedDriver);
  useEffect(() => {
    let alive = true;
    void ledDetector.detect().then((d) => alive && setDriver(d));
    return () => {
      alive = false;
    };
  }, [ledDetector]);
  return (
    <>
      <RoomScreen bookingPanel={BookingPanel} menuSlot={isSharedRoom ? undefined : <Menu hasRoom />} onReload={() => reload('manual')} />
      <LedStatus driver={driver} />
    </>
  );
}
