import { createRoot } from 'react-dom/client';
import '@/ui/theme';
import { loadConfig, type AppConfig } from '@/config';
import { createSystemClock } from '@/kernel';
import { initI18n } from '@/i18n';
import { registerServiceWorker } from '@/platform/service-worker';
import { AppProviders, createAppTelemetry, createContainer, type AppContainer } from '@/app/providers';
import { AppRouter } from '@/app/router';
import { browserBootGuardDeps, createBootGuard } from './boot-guard';
import { reloadPage } from './reload';

/** config.json loader injected into `loadConfig` (fetch is banned outside data/http, platform/ and app/bootstrap). */
export const fetchJson = (url: string): Promise<unknown> =>
  fetch(url, { cache: 'no-store' }).then((r) => {
    if (!r.ok) throw new Error(String(r.status));
    return r.json();
  });

export interface StartedApp {
  container: AppContainer;
  config: AppConfig;
}

/**
 * T01 boot (kiosk-runtime.yaml boot.sequence): 45 s guard armed first (BOOT-3), telemetry before any app code
 * (DEV-D-40), config.json (BOOT-4), i18n, the container (kernel, storage, http, session, query client, connectivity,
 * Mercure + bridge per session, LED detector, host bridge), render (BOOT-5), then the service worker (VITE_SW).
 * A throw before the render → bootstrap recovery (DT-BOOT-2/3). Resolves null when the boot failed.
 */
export async function startApp(root: HTMLElement | null = document.getElementById('root')): Promise<StartedApp | null> {
  const pageLoadedAt = Date.now();
  const guard = createBootGuard(browserBootGuardDeps(reloadPage));
  guard.arm();
  const clock = createSystemClock();
  const telemetry = createAppTelemetry({
    clock,
    buildDsn: import.meta.env.VITE_SENTRY_DSN as string | undefined,
    environment: import.meta.env.VITE_ENV as string | undefined,
    release: __BUILD_ID__,
    dev: import.meta.env.DEV,
  });
  try {
    if (!root) throw new Error('#root missing');
    const config = await loadConfig(fetchJson);
    telemetry.configure(config.sentryDsn);
    initI18n();
    const container = createContainer({ config, clock, telemetry, reload: reloadPage, pageLoadedAt, onFirstReady: () => guard.clearMarks() });
    container.start();
    createRoot(root).render(
      <AppProviders container={container}>
        <AppRouter />
      </AppProviders>,
    );
    guard.bootstrapped();
    container.health.markBootstrapped();
    void registerServiceWorker({ onUpdateReady: () => reloadPage('sw_update'), onError: (e) => telemetry.captureError(e, { rateLimitKey: 'sw' }) });
    return { container, config };
  } catch (e) {
    telemetry.captureError(e, { extras: { where: 'bootstrap' } });
    guard.fail('bootstrap_failed');
    return null;
  }
}
