import type { CSSProperties, ReactNode, Ref } from 'react';
import type { Booking, DateRange } from '@/domain/booking-model';
import type { RoomStatusView } from '@/domain/room-status';
import { Spinner } from '@/ui/primitives';
import { statusToneAttrs } from '@/ui/theme';
import { Timeline, type BlockTitleTexts, type TimelineHandle } from '@/ui/timeline';
import { BookingBody, FreeBody } from './bodies';
import { Footer } from './footer';
import { Header } from './header';
import type { QrLinks } from './qr-links';
import styles from './room-display.module.css';

/** Plain props of the room screen (no data hooks): one evaluation + the facts to show. */
export interface RoomViewProps {
  /** null = loading (SCR-ROOM/ST-LOADING; also the first read failed, DEV-D-42). */
  view: RoomStatusView | null;
  /** The evaluation instant of `view` (DEV-D-134). */
  now: number;
  zone: string;
  hour12: boolean;
  american: boolean;
  room: { name: string; capacity: number | null };
  logo: string | null;
  backgroundImage: string | null;
  qr: QrLinks | null;
  dayRange: DateRange;
  workingRanges: readonly DateRange[];
  bookings: readonly Booking[];
  titlesOf?: (b: Booking) => BlockTitleTexts;
  onSlotTap?: (at: number) => void;
  onBookingTap?: (b: Booking) => void;
  updatedAt: number | null;
  menuSlot?: ReactNode;
  onReload(): void;
  onOpenQr(link: string): void;
  renderPanel(part: 'free' | 'form' | 'booking'): ReactNode;
  timelineRef?: Ref<TimelineHandle>;
}

function Body(p: RoomViewProps & { view: RoomStatusView }): JSX.Element | null {
  const { view, room, zone, hour12, qr } = p;
  if (view.body === 'form') return <div className={styles.body}>{p.renderPanel('form')}</div>;
  if (view.body === 'booking' && view.booking) {
    return <BookingBody {...room} info={view.booking} panel={p.renderPanel('booking')} checkinQrLink={qr?.checkin ?? null} onOpenQr={p.onOpenQr} zone={zone} hour12={hour12} />;
  }
  return (
    <FreeBody {...room} inAccent free={view.free} panel={p.renderPanel('free')} roomQrLink={qr?.room ?? null} onOpenQr={p.onOpenQr} zone={zone} hour12={hour12} />
  );
}

/** SCR-ROOM: timeline left, info block right (header + body), footer bottom-right; both orientations. */
export function RoomView(p: RoomViewProps): JSX.Element {
  const { view } = p;
  const footer = <Footer updatedAt={p.updatedAt} now={p.now} zone={p.zone} hour12={p.hour12} onReload={p.onReload} />;
  if (!view || view.body === 'spinner') {
    return (
      <div className={styles.root} data-testid="room" data-state="loading">
        <Spinner className={styles.spinner} />
        {footer}
      </div>
    );
  }
  const custom = p.backgroundImage && !view.selectedRange;
  const bg = custom ? ({ backgroundImage: `var(--tok-bg-image-scrim), url("${p.backgroundImage}")` } as CSSProperties) : undefined;
  return (
    <div className={styles.root} data-testid="room" data-state={view.body} {...statusToneAttrs(view.status)}>
      <div className={styles.timeline}>
        <Timeline
          ref={p.timelineRef}
          range={p.dayRange}
          now={p.now}
          zone={p.zone}
          bookings={p.bookings}
          workingRanges={p.workingRanges}
          selectedBookingId={view.selectedBookingId}
          selectedRange={view.selectedRange}
          hour12={p.hour12}
          titlesOf={p.titlesOf}
          onSlotTap={p.onSlotTap}
          onBookingTap={p.onBookingTap}
        />
      </div>
      <div className={[styles.info, custom ? styles.customBackground : ''].join(' ')} style={bg}>
        <Header logo={p.logo} now={p.now} zone={p.zone} hour12={p.hour12} american={p.american} menuSlot={p.menuSlot} showMenu={view.menu} />
        <Body {...p} view={view} />
      </div>
      {footer}
    </div>
  );
}
