/** Operation ids of product/contract/operations/display.yaml used in AppError.op and reports. */
export const OPS = {
  companyCard: 'OP-AUTH-COMPANY-CARD',
  pinLogin: 'OP-AUTH-PIN-LOGIN',
  me: 'OP-PROFILE-ME',
  roomDetail: 'OP-ROOMS-DETAIL',
  settingsCommon: 'OP-SETTINGS-COMMON',
  checkInDefaults: 'OP-SETTINGS-CHECKIN-DEFAULTS',
  bookingsList: 'OP-BOOKINGS-LIST',
  createRoom: 'OP-BOOKINGS-CREATE-ROOM',
  cancelRoom: 'OP-BOOKINGS-CANCEL-ROOM',
  checkIn: 'OP-BOOKINGS-CHECKIN',
  stop: 'OP-BOOKINGS-STOP',
  delete: 'OP-BOOKINGS-DELETE',
  roomsTree: 'OP-ROOMS-TREE',
} as const;

export type OpId = (typeof OPS)[keyof typeof OPS];

/** A dropped (unparseable) item: never carries the payload (DEV-D-36, ADR-0004 §2). */
export interface InvalidItemInfo {
  op: string;
  index?: number;
  /** zod issue paths and codes only, e.g. `start:custom`. */
  issues: string[];
}

export type OnInvalid = (info: InvalidItemInfo) => void;

export function issuesOf(error: { issues: ReadonlyArray<{ path: ReadonlyArray<string | number>; code: string }> }): string[] {
  return error.issues.map((i) => `${i.path.join('.')}:${i.code}`);
}
