import { decodeLegacy, encodeLegacy, type StoredValue } from './legacy-codec';

/** Legacy key names (STO-TOKEN, STO-REFRESH-TOKEN, STO-API-BASE-DOMAIN, STO-HIDE-INSTALL-APP). */
export const STORAGE_KEYS = {
  token: 'unspot-space-token',
  refreshToken: 'unspot-space-refresh-token',
  apiBaseDomain: 'unspot-space-api-base-domain',
  hideInstallApp: 'hideInstallApp',
} as const;

/** Port: decoded key-value store with the legacy on-disk format. */
export interface KeyValueStorage {
  /** Decoded value per DT-STO-1…5; null when absent or undecodable (DT-STO-4, reported once). */
  get(key: string): StoredValue;
  /** The value when it is a string, else null. */
  getString(key: string): string | null;
  /** Presence of the raw item (legacy `has`). */
  has(key: string): boolean;
  /** Writes `{value, type}` exactly as legacy. */
  set(key: string, value: StoredValue): void;
  remove(key: string): void;
}

/** The raw Web Storage surface the adapter needs (a memory backend implements it in tests). */
export type RawBackend = Pick<Storage, 'getItem' | 'setItem' | 'removeItem'>;

export interface WebStorageOptions {
  backend: RawBackend;
  /** Called once per key whose stored JSON has no known type (DT-STO-4; legacy throws). Never gets the value. */
  onDecodeError?: (key: string) => void;
}

export function createWebStorage({ backend, onDecodeError }: WebStorageOptions): KeyValueStorage {
  const reported = new Set<string>();
  const get = (key: string): StoredValue => {
    const raw = backend.getItem(key);
    if (raw === null) return null; // DT-STO-5
    const d = decodeLegacy(raw);
    if (d.ok) return d.value;
    if (!reported.has(key)) {
      reported.add(key);
      onDecodeError?.(key);
    }
    return null;
  };
  return {
    get,
    getString: (key) => {
      const v = get(key);
      return typeof v === 'string' ? v : null;
    },
    has: (key) => backend.getItem(key) !== null,
    set: (key, value) => backend.setItem(key, encodeLegacy(value)),
    remove: (key) => backend.removeItem(key),
  };
}

interface StorageHost {
  localStorage: RawBackend | null;
  sessionStorage: RawBackend | null;
}

/** storage.backend: localStorage when available, else sessionStorage (iOS WebView comment in legacy). */
export function pickBackend(host: StorageHost): RawBackend | null {
  try {
    if (host.localStorage) return host.localStorage;
  } catch {
    // access can throw (SecurityError) — fall through
  }
  try {
    return host.sessionStorage;
  } catch {
    return null;
  }
}

/** Browser adapter: localStorage, else sessionStorage, else memory (never throws at boot). */
export function createBrowserStorage(onDecodeError?: (key: string) => void): KeyValueStorage {
  const backend = (typeof window !== 'undefined' ? pickBackend(window) : null) ?? createMemoryBackend();
  return createWebStorage({ backend, onDecodeError });
}

/** In-memory raw backend (fake for tests; last-resort fallback in the browser). */
export function createMemoryBackend(initial: Record<string, string> = {}): RawBackend {
  const m = new Map(Object.entries(initial));
  return {
    getItem: (k) => m.get(k) ?? null,
    setItem: (k, v) => {
      m.set(k, String(v));
    },
    removeItem: (k) => {
      m.delete(k);
    },
  };
}
