import { fromZonedTime } from 'date-fns-tz';
import { overlaps, type Booking, type DateRange } from '@/domain/booking-model';
import { addDaysInZone } from '@/kernel';

/** One shown day: the room screen (one room) or the rooms board (every room). `day` = 'yyyy-MM-dd' in `tz`. */
export type BookingsDayScope = { scope: 'room'; roomId: string; day: string; tz: string } | { scope: 'board'; day: string; tz: string };

/** The ONLY place query keys are built (ADR-0004 §1). Every key starts with ['s', generation] (ADR-0004 addendum). */
export const queryKeys = {
  all: (g: number) => ['s', g] as const,
  companyCard: (g: number, subDomain: string) => ['s', g, 'companyCard', subDomain] as const,
  me: (g: number) => ['s', g, 'me'] as const,
  roomDetail: (g: number, roomId: string) => ['s', g, 'roomDetail', roomId] as const,
  companySettings: (g: number) => ['s', g, 'companySettings'] as const,
  checkInDefaults: (g: number) => ['s', g, 'checkInDefaults'] as const,
  bookingsDay: (g: number, scope: BookingsDayScope) => ['s', g, 'bookingsDay', scope] as const,
  /** Prefix of every bookingsDay key of a generation (invalidate / patch all shown days). */
  bookingsDayAll: (g: number) => ['s', g, 'bookingsDay'] as const,
};

/** The local day [midnight, next midnight) of a scope in its zone, epoch ms (DST-safe zone math). */
export function dayWindow(scope: BookingsDayScope): DateRange {
  const start = fromZonedTime(`${scope.day}T00:00:00`, scope.tz).getTime();
  return { start, end: addDaysInZone(start, 1, scope.tz) };
}

/** Default insert filter: room scope = own room + overlaps the day; board = overlaps the day (DEV-D-136). */
export function bookingMatchesScope(b: Booking, scope: BookingsDayScope): boolean {
  if (scope.scope === 'room' && !b.roomIds.includes(scope.roomId)) return false;
  return overlaps(b, dayWindow(scope));
}

/** Scope of a bookingsDay key, or null for any other key. */
export function scopeOfKey(key: readonly unknown[]): BookingsDayScope | null {
  return key[2] === 'bookingsDay' && key[3] && typeof key[3] === 'object' ? (key[3] as BookingsDayScope) : null;
}
