import type { DateRange } from '@/domain/booking-model';
import { formatInZone } from '@/kernel';

/** TOK-TIMELINE: 100 px per hour (50 px per half hour), 2400 px for a 24 h day. */
export const PX_PER_MINUTE = 100 / 60;
const MIN = 60_000;

/** Pixels from the range start for a minute offset. */
export const px = (minutes: number): number => Math.round(minutes * PX_PER_MINUTE * 1000) / 1000;

/** Minutes of the range (1380 / 1500 on DST days). */
export const rangeMinutes = (range: DateRange): number => (range.end - range.start) / MIN;

/**
 * Hour labels of the vertical timeline (SCR-ROOM region timeline: one per hour of the day plus the closing one, 25 on
 * a normal day; "HH", or "hh am|pm" for 12-hour companies). Wall time in `zone`, computed once per day.
 */
export function hourLabels(range: DateRange, zone: string, hour12: boolean): string[] {
  const count = Math.round(rangeMinutes(range) / 60) + 1;
  return Array.from({ length: count }, (_, i) => {
    const at = range.start + i * 60 * MIN;
    return hour12 ? formatInZone(at, zone, 'hh aaa') : formatInZone(at, zone, 'HH');
  });
}

/** Instant of a tap `y` px below the range start (floored to the minute, clamped to the range). */
export function instantAt(range: DateRange, y: number): number {
  const minutes = Math.floor(Math.max(0, y) / PX_PER_MINUTE);
  return Math.min(range.start + minutes * MIN, range.end - MIN);
}
