import { isCancelledError, type QueryClient } from '@tanstack/react-query';
import type { AppError, EventBus, Scheduler } from '@/kernel';
import { queryKeys } from './query-keys';

export interface BookingsJobsDeps {
  queryClient: QueryClient;
  events: EventBus;
  /** Current session generation (state/session). */
  generation: () => number;
  /**
   * Delays of the first-read retry; the last one repeats. Default [60 s] = DEV-D-42 (retry every 60 s until the
   * first read succeeds). ADR-0004 §1 still names 15, 30, 60 s; see REV-T-2.4.2-bookings-retry-period.
   */
  retryDelaysMs?: readonly number[];
}

export const BOOKINGS_REFRESH_MS = 10 * 60_000;
const DEFAULT_RETRY = [60_000] as const;

/**
 * Jobs that keep the shown bookings fresh (ARCHITECTURE §3): `bookings-10m` (TMR-ROOM-REFETCH, board too DEV-D-63),
 * invalidation on `day.changed` (RLD-MIDNIGHT) and `realtime.reconnected` (DEV-D-83), `bookings-retry` while the
 * first read of a day has failed (DEV-D-42; a failed periodic read keeps the old list). Returns stop().
 */
export function startBookingsJobs(scheduler: Scheduler, deps: BookingsJobsDeps): () => void {
  const { queryClient: qc, events, generation } = deps;
  const delays = deps.retryDelaysMs && deps.retryDelaysMs.length ? deps.retryDelaysMs : DEFAULT_RETRY;
  let attempt = 0;
  const prefix = (): readonly unknown[] => queryKeys.bookingsDayAll(generation());
  const isDayKey = (key: readonly unknown[]): boolean => key[0] === 's' && key[1] === generation() && key[2] === 'bookingsDay';
  const invalidate = (): void => void qc.invalidateQueries({ queryKey: prefix() });
  const retryFailedFirstReads = (): void =>
    void qc.refetchQueries({ queryKey: prefix(), type: 'active', predicate: (q) => q.state.data === undefined && q.state.status === 'error' });

  scheduler.every('bookings-10m', BOOKINGS_REFRESH_MS, invalidate);
  const offs = [events.on('day.changed', invalidate), events.on('realtime.reconnected', invalidate)];

  const unsubscribeCache = qc.getQueryCache().subscribe((event) => {
    if (event.type !== 'updated' || !isDayKey(event.query.queryKey)) return;
    if (event.action.type === 'success') {
      const stillFailing = qc
        .getQueryCache()
        .findAll({ queryKey: prefix(), type: 'active' })
        .some((q) => q.state.data === undefined && q.state.status === 'error');
      if (!stillFailing) {
        attempt = 0;
        scheduler.cancel('bookings-retry');
      }
      return;
    }
    if (event.action.type !== 'error') return;
    const error = event.action.error as AppError | null;
    if (isCancelledError(error) || error?.kind === 'aborted' || event.query.state.data !== undefined) return;
    const delay = delays[Math.min(attempt, delays.length - 1)]!;
    attempt += 1;
    scheduler.after('bookings-retry', delay, retryFailedFirstReads);
  });

  return () => {
    scheduler.cancel('bookings-10m');
    scheduler.cancel('bookings-retry');
    offs.forEach((off) => off());
    unsubscribeCache();
  };
}
