/**
 * Runtime + build configuration (T36, ARCHITECTURE §4, ADR-0004 §6, ADR-0005 §1).
 * Runtime file: `<BASE_URL>assets/config/config.json` (legacy path). Legacy keys are accepted; a new key wins.
 */
export interface AppConfig {
  /** Build/runtime environment name (VITE_ENV or ENV). */
  env: string;
  /** e.g. `https://{company}.unspot.ru`; null → legacy derivation from the page host (FLAG-API-HOST). */
  apiOriginTemplate: string | null;
  /** Auth host for OP-AUTH-COMPANY-CARD (API_AUTH_DOMAIN). '' when not configured. */
  authOrigin: string;
  /** Private Mercure hub URL (PRIVATE_MERCURE_URL); null when not configured. */
  mercureHubUrl: string | null;
  /** '' = telemetry off. */
  sentryDsn: string;
  rolloutUrl: string | null;
  /** QR link host parts (SERVER_HOST, MOBILE_ROUTER_SUB_DOMAIN). */
  serverHost: string | null;
  mobileRouterSubDomain: string | null;
}

/** Values known at build time (VITE_*), used when the runtime file does not set them. */
export interface BuildEnv {
  env?: string;
  sentryDsn?: string;
}

/** Reads a JSON document; injected because only app/bootstrap and platform may call fetch. */
export type FetchJson = (url: string) => Promise<unknown>;

const str = (raw: Record<string, unknown>, ...keys: string[]): string | null => {
  for (const k of keys) {
    const v = raw[k];
    if (typeof v === 'string' && v.trim() !== '') return v.trim();
  }
  return null;
};

const origin = (v: string | null): string | null => (v === null ? null : v.replace(/\/+$/, ''));

export function parseConfig(input: unknown, build: BuildEnv = {}): AppConfig {
  const raw = (input !== null && typeof input === 'object' ? input : {}) as Record<string, unknown>;
  const dsn = raw.sentryDsn;
  return {
    env: str(raw, 'env', 'ENV') ?? build.env ?? 'production',
    apiOriginTemplate: origin(str(raw, 'apiOriginTemplate')),
    authOrigin: origin(str(raw, 'authOrigin', 'API_AUTH_DOMAIN')) ?? '',
    mercureHubUrl: str(raw, 'mercureHubUrl', 'PRIVATE_MERCURE_URL'),
    sentryDsn: typeof dsn === 'string' ? dsn : (build.sentryDsn ?? ''),
    rolloutUrl: str(raw, 'rolloutUrl'),
    serverHost: str(raw, 'serverHost', 'SERVER_HOST'),
    mobileRouterSubDomain: str(raw, 'mobileRouterSubDomain', 'MOBILE_ROUTER_SUB_DOMAIN'),
  };
}

export function configUrl(baseUrl: string): string {
  return `${baseUrl.endsWith('/') ? baseUrl : `${baseUrl}/`}assets/config/config.json`;
}

let current: AppConfig | null = null;
let pending: Promise<AppConfig> | null = null;

function buildEnv(): BuildEnv {
  const e = import.meta.env as Record<string, string | undefined>;
  return { env: e.VITE_ENV, sentryDsn: e.VITE_SENTRY_DSN };
}

/** Loads the runtime config once per page (later calls return the same promise). Rejects when the file is unreadable. */
export function loadConfig(fetchJson: FetchJson, baseUrl: string = import.meta.env.BASE_URL): Promise<AppConfig> {
  if (pending) return pending;
  pending = fetchJson(configUrl(baseUrl)).then(
    (raw) => {
      current = parseConfig(raw, buildEnv());
      return current;
    },
    (e: unknown) => {
      pending = null;
      throw e instanceof Error ? e : new Error('config.json unavailable');
    },
  );
  return pending;
}

/** Sync getter after `loadConfig` resolved; throws before (a programming error). */
export function getConfig(): AppConfig {
  if (!current) throw new Error('config not loaded: await loadConfig() at boot');
  return current;
}

export function setConfigForTests(partial: Partial<AppConfig>): AppConfig {
  current = { ...parseConfig({}), ...partial };
  pending = Promise.resolve(current);
  return current;
}

export function resetConfigForTests(): void {
  current = null;
  pending = null;
}
