import { useQuery, useQueryClient, type QueryClient, type UseQueryResult } from '@tanstack/react-query';
import { byStart, type Booking } from '@/domain/booking-model';
import type { AppError } from '@/kernel';
import { bookingsFromListBody, OPS, refineRefusal, type OnInvalid } from '@/contract';
import { useDataServices, type HttpClient } from '@/data/http';
import { useSession } from '@/state/session';
import { beginRead, finishRead } from './journal';
import { dayWindow, queryKeys, type BookingsDayScope } from './query-keys';

/** `select` of OP-BOOKINGS-LIST, the same comma list for both forms (verbatim from the card). */
export const BOOKINGS_SELECT =
  'booking.id, booking.title, booking.datetime, booking.organizer, booking.organizerEmail, booking.isVisible, booking.checkIn, ' +
  'organizer.id, organizer.email, organizer.firstName, organizer.lastName, organizer.fullName, organizer.role, ' +
  'roomBooking.room, roomBooking.organizerEmail, roomBooking.isVisible, room.id, room.isPrivateByDefault';

const SIX_HOURS_S = 6 * 3600;

/** Query of OP-BOOKINGS-LIST: room-day form (one local day, roomId) or all-rooms-day form (day + 6 h, DEV-D-87). */
export function bookingsListQuery(scope: BookingsDayScope): Record<string, string | number> {
  const w = dayWindow(scope);
  const start = Math.floor(w.start / 1000);
  const nextMidnight = Math.floor(w.end / 1000);
  const base = { start, tz: scope.tz, type: 'MEETING_ROOM', select: BOOKINGS_SELECT };
  return scope.scope === 'room' ? { ...base, end: nextMidnight, roomId: scope.roomId } : { ...base, end: nextMidnight + SIX_HOURS_S - 1 };
}

/** Reads one day; patches landing meanwhile are re-applied over the answer (ADR-0004 addendum). Throws AppError. */
export async function fetchBookingsDay(
  http: HttpClient,
  qc: QueryClient,
  generation: number,
  scope: BookingsDayScope,
  signal?: AbortSignal,
  onInvalid?: OnInvalid,
): Promise<Booking[]> {
  const startSeq = beginRead(qc);
  const r = await http.get('/api/v2/bookings', { op: OPS.bookingsList, query: bookingsListQuery(scope), signal });
  if (!r.ok) {
    finishRead(qc, startSeq, generation, scope, null);
    throw refineRefusal(OPS.bookingsList, r.error);
  }
  const list = bookingsFromListBody(r.value.body, { onInvalid });
  return finishRead(qc, startSeq, generation, scope, list).sort(byStart);
}

/**
 * OP-BOOKINGS-LIST for one shown day. `null` scope (no room yet / no day) → disabled. Freshness is owned by
 * `startBookingsJobs` (10 min, day change, real-time reconnect, first-read retry), never by the library.
 */
export function useBookingsDayQuery(scope: BookingsDayScope | null): UseQueryResult<Booking[], AppError> {
  const generation = useSession((s) => s.generation);
  const ready = useSession((s) => s.status === 'ready');
  const { http, onInvalidItem } = useDataServices();
  const qc = useQueryClient();
  return useQuery<Booking[], AppError, Booking[], readonly unknown[]>({
    queryKey: scope ? queryKeys.bookingsDay(generation, scope) : [...queryKeys.bookingsDayAll(generation), 'none'],
    queryFn: ({ signal }) => fetchBookingsDay(http, qc, generation, scope!, signal, onInvalidItem),
    enabled: ready && scope !== null,
  });
}
