import type { QueryClient } from '@tanstack/react-query';
import type { AppConfig } from '@/config';
import { createEventBus, createScheduler, type Clock, type Kernel } from '@/kernel';
import { getLanguage } from '@/i18n';
import { createBrowserStorage, type KeyValueStorage } from '@/platform/storage';
import { createHttpClient, type DataServices, type HttpClient } from '@/data/http';
import { createActivationApi, createQueryClient, queryKeys, startBookingsJobs } from '@/data/queries';
import { connectSessionEvents, createSessionStore, type SessionStore } from '@/state/session';
import { createConnectivity, type Connectivity } from '@/platform/connectivity';
import { createLedDetector, type LedDetector } from '@/platform/led';
import { noopHostBridge, type HostBridge } from '@/platform/host-bridge';
import { bindApiCachePurge, purgeApiCache } from '@/platform/service-worker';
import type { Telemetry } from '@/platform/telemetry';
import { createEventSourceTransport, type RealtimeTransport } from '@/realtime/mercure-client';
import { createRecovery, createRuntimeHealth, type RuntimeHealth } from '@/features/kiosk-runtime';
import { startSessionServices } from './session-services';

export const OP_DEVICE_PING = 'OP-DEVICE-PING';
/** TMR-WD-PING-TIMEOUT is 3 min (connectivity aborts then); the http timeout must not cut the ping earlier. */
const PING_TIMEOUT_MS = 180_000;

export type ReloadFn = (reason: string) => void;

export interface ContainerDeps {
  config: AppConfig;
  clock: Clock;
  telemetry: Telemetry;
  /** The ONE reload of app/bootstrap. */
  reload: ReloadFn;
  pageLoadedAt?: number;
  /** BOOT-10 first ready screen → boot-recovery marks cleared (app/bootstrap). */
  onFirstReady?: () => void;
  // Adapter seams (tests); defaults are the browser adapters.
  storage?: KeyValueStorage;
  fetchFn?: typeof fetch;
  transport?: () => RealtimeTransport;
  ledDetector?: LedDetector;
  hostBridge?: HostBridge;
  pageUrl?: () => string;
  isOnline?: () => boolean;
  connectivityTarget?: Pick<Window, 'addEventListener' | 'removeEventListener'>;
  purgeCache?: () => Promise<unknown>;
}

export interface AppContainer {
  config: AppConfig;
  kernel: Kernel;
  storage: KeyValueStorage;
  session: SessionStore;
  http: HttpClient;
  dataServices: DataServices;
  queryClient: QueryClient;
  connectivity: Connectivity;
  ledDetector: LedDetector;
  hostBridge: HostBridge;
  telemetry: Telemetry;
  health: RuntimeHealth;
  reload: ReloadFn;
  /** Starts the page-lifetime services (watchdog, real time per session, bookings jobs, wiring). Returns stop(). */
  start(): () => void;
}

/** ARCHITECTURE §2 T02: the only place that picks adapters and wires ports (READMEs of each module, "Wiring"). */
export function createContainer(d: ContainerDeps): AppContainer {
  const clock = d.clock;
  const kernel: Kernel = { clock, scheduler: createScheduler(clock), events: createEventBus() };
  const storage = d.storage ?? createBrowserStorage((key) => d.telemetry.captureEvent('storage_decode_error', { level: 'warning', extras: { key } }));
  const queryClient = createQueryClient();
  const health = createRuntimeHealth({ clock, pageLoadedAt: d.pageLoadedAt, onFirstReady: d.onFirstReady });
  const hostBridge = d.hostBridge ?? noopHostBridge;
  const purge = d.purgeCache ?? (() => purgeApiCache());

  // http needs the session getter, the session needs http (activation api): late binding through `session`.
  // eslint-disable-next-line prefer-const -- assigned right below, read lazily by the http getter
  let session: SessionStore;
  const http = createHttpClient({
    authOrigin: () => d.config.authOrigin,
    session: () => session.getState(),
    events: kernel.events,
    scheduler: kernel.scheduler,
    language: () => getLanguage(),
    fetchFn: d.fetchFn,
    isOnline: d.isOnline ?? (() => navigator.onLine),
  });
  session = createSessionStore({
    storage,
    api: createActivationApi(http),
    config: () => d.config,
    pageUrl: d.pageUrl ?? (() => window.location.href),
    // RLD-LOGOUT: cache cleared, telemetry told, API cache purged (DEV-D-30), then the full reload to activation.
    onLoggedOut: (reason) => {
      queryClient.clear();
      d.telemetry.captureEvent('forced_logout', { level: 'warning', extras: { reason } });
      void purge()
        .catch(() => undefined)
        .then(() => d.reload('logout'));
    },
  });

  const recovery = createRecovery({ health, clock, scheduler: kernel.scheduler, events: kernel.events, reload: d.reload });
  const connectivity = createConnectivity({
    scheduler: kernel.scheduler,
    events: kernel.events,
    ping: (form, signal) =>
      http
        .get('/api/devices/ping', { op: OP_DEVICE_PING, query: form === 'connectivity' ? { skipLogAndEvent: 'true' } : undefined, signal, timeoutMs: PING_TIMEOUT_MS })
        .then((r) => (r.ok ? 'ok' : 'fail')),
    isAuthenticated: () => session.getState().status === 'ready',
    recover: () => recovery.recover(),
    target: d.connectivityTarget,
  });
  const ledDetector = d.ledDetector ?? createLedDetector({ scheduler: kernel.scheduler, onError: (e) => d.telemetry.captureError(e, { rateLimitKey: 'led' }) });
  const dataServices: DataServices = {
    http,
    onInvalidItem: (info) =>
      d.telemetry.captureEvent('invalid_item', { level: 'warning', extras: { op: info.op, issues: info.issues.join(',') }, rateLimitKey: `invalid:${info.op}` }),
  };

  const start = (): (() => void) => {
    const g = (): number => session.getState().generation;
    const offs: Array<() => void> = [
      connectSessionEvents(session, kernel.events),
      bindApiCachePurge(kernel.events),
      startBookingsJobs(kernel.scheduler, { queryClient, events: kernel.events, generation: g }),
      startSessionServices({
        kernel, session, http, queryClient, telemetry: d.telemetry, hostBridge,
        hubUrl: d.config.mercureHubUrl,
        transport: d.transport ?? (() => createEventSourceTransport()),
      }),
      // RLD-WD-SOFT (T01 consumer of app.reinitRequested): re-run the boot bundle, not the bookings reads.
      kernel.events.on('app.reinitRequested', () =>
        void queryClient.refetchQueries({ queryKey: queryKeys.all(g()), predicate: (q) => q.queryKey[2] !== 'bookingsDay' }),
      ),
      // RLD-SCREEN-REBUILD (DEV-D-6): the rebuilt screen reads its day afresh.
      kernel.events.on('connectivity.changed', (e) => {
        if (e.state === 'online') void queryClient.invalidateQueries({ queryKey: queryKeys.bookingsDayAll(g()) });
      }),
      // BOOT-10: the first successful bookings read marks the screen ready (heartbeat then comes from the status tick).
      queryClient.getQueryCache().subscribe((ev) => {
        if (ev.type === 'updated' && ev.action.type === 'success' && ev.query.queryKey[2] === 'bookingsDay') health.markReady();
      }),
    ];
    connectivity.start();
    return () => {
      connectivity.stop();
      offs.forEach((off) => off());
    };
  };

  return { config: d.config, kernel, storage, session, http, dataServices, queryClient, connectivity, ledDetector, hostBridge, telemetry: d.telemetry, health, reload: d.reload, start };
}
