import { useQuery, type UseQueryResult } from '@tanstack/react-query';
import type { AppError, Result } from '@/kernel';
import {
  OPS,
  parseCheckInDefaults,
  parseCompanyCard,
  parseCompanySettings,
  parseMe,
  parseRoomDetail,
  refineRefusal,
  type CheckInDefaults,
  type CompanyCard,
  type CompanySettings,
  type Me,
  type RoomDetail,
} from '@/contract';
import { useDataServices, type HttpClient, type RequestOptions } from '@/data/http';
import { useSession, useSessionStore } from '@/state/session';
import { queryKeys } from './query-keys';

/** GET + parse; throws an AppError (refusal card code when the text matches) so TanStack keeps it as `error`. */
export async function readParsed<T>(
  http: HttpClient,
  path: string,
  opts: RequestOptions,
  parse: (body: unknown) => Result<T, AppError>,
): Promise<T> {
  const r = await http.get(path, opts);
  if (!r.ok) throw refineRefusal(opts.op, r.error);
  const p = parse(r.value.body);
  if (!p.ok) throw p.error;
  return p.value;
}

function useBase(): { generation: number; ready: boolean; http: HttpClient } {
  const generation = useSession((s) => s.generation);
  const ready = useSession((s) => s.status === 'ready');
  return { generation, ready, http: useDataServices().http };
}

/** OP-PROFILE-ME; on success writes `me.device.id` to the session (same generation only). Re-read after reload only. */
export function useMeQuery(): UseQueryResult<Me, AppError> {
  const { generation, ready, http } = useBase();
  const store = useSessionStore();
  return useQuery<Me, AppError, Me, readonly unknown[]>({
    queryKey: queryKeys.me(generation),
    queryFn: async ({ signal }) => {
      const me = await readParsed(http, '/api/me', { op: OPS.me, signal }, parseMe);
      if (store.getState().generation === generation) store.getState().setDeviceId(me.device?.id ?? null);
      return me;
    },
    enabled: ready,
    gcTime: Infinity,
  });
}

/** OP-ROOMS-DETAIL of `me.device.space.id`; disabled without a room. */
export function useRoomDetailQuery(roomId: string | null): UseQueryResult<RoomDetail, AppError> {
  const { generation, ready, http } = useBase();
  return useQuery<RoomDetail, AppError, RoomDetail, readonly unknown[]>({
    queryKey: queryKeys.roomDetail(generation, roomId ?? ''),
    queryFn: ({ signal }) =>
      readParsed(http, `/api/spaces/meeting-room-detail/${encodeURIComponent(roomId!)}`, { op: OPS.roomDetail, signal }, parseRoomDetail),
    enabled: ready && !!roomId,
    gcTime: Infinity,
  });
}

/** OP-SETTINGS-COMMON (working hours, default zone, formats). */
