/** OP-AUTH-COMPANY-CARD on the auth host, no token (DEV-D-89); sub-domain defaults to the session's. */
export function useCompanyCardQuery(subDomain?: string | null): UseQueryResult<CompanyCard, AppError> {
  const { generation, http } = useBase();
  const sessionSub = useSession((s) => s.subDomain);
  const sub = subDomain ?? sessionSub;
  return useQuery<CompanyCard, AppError, CompanyCard, readonly unknown[]>({
    queryKey: queryKeys.companyCard(generation, sub ?? ''),
    queryFn: ({ signal }) =>
      readParsed(http, '/api/resolve-company-by-domain', { op: OPS.companyCard, host: 'auth', query: { subDomain: sub }, signal }, parseCompanyCard),
    enabled: !!sub,
    gcTime: Infinity,
  });
}
