import { z } from 'zod';
import type { Organizer } from '@/domain/booking-model';
import { appError, err, ok, type AppError, type Result } from '@/kernel';
import { OPS, issuesOf } from './ops';
import { textPattern } from './refusals';

/** Body of OP-BOOKINGS-CREATE-ROOM exactly as the legacy display sends it. */
export interface CreateBookingDto {
  title: string;
  timeRanges: [{ startDate: number; endDate: number }];
  rooms: [string];
  isVisible: true;
}

/** start / end epoch ms → unix seconds (floored), one range, the one room, isVisible always true. */
export function toCreateBookingDto(input: { title: string; start: number; end: number; roomId: string }): CreateBookingDto {
  return {
    title: input.title,
    timeRanges: [{ startDate: Math.floor(input.start / 1000), endDate: Math.floor(input.end / 1000) }],
    rooms: [input.roomId],
    isVisible: true,
  };
}

const createAnswerSchema = z.object({
  bookings: z
    .array(
      z.object({
        id: z.string().min(1),
        start: z.string().refine((s) => !Number.isNaN(Date.parse(s))),
        end: z.string().refine((s) => !Number.isNaN(Date.parse(s))),
        organizer: z
          .object({ id: z.string().nullish(), fullName: z.string().nullish(), email: z.string().nullish(), role: z.string().nullish() })
          .nullish(),
      }),
    )
    .min(1),
});

export interface CreateAnswer {
  id: string;
  start: number;
  end: number;
  organizer: Organizer;
}

/** `body.bookings[0]` of a successful create (the answer has no title). */
export function parseCreateAnswer(body: unknown): Result<CreateAnswer, AppError> {
  const r = createAnswerSchema.safeParse(body);
  if (!r.success) return err(appError('invalid-response', 'invalid-response', { op: OPS.createRoom, fieldErrors: { issues: issuesOf(r.error).join(', ') } }));
  const b = r.data.bookings[0]!;
  const o = b.organizer;
  return ok({
    id: b.id,
    start: Date.parse(b.start),
    end: Date.parse(b.end),
    organizer: { id: o?.id ?? '', fullName: o?.fullName?.trim() ?? '', email: o?.email ?? null, role: o?.role ?? null },
  });
}

const DELETED = ['The booking has been deleted successfully.', 'Бронирование успешно удалено.', 'Die Buchung wurde erfolgreich gelöscht.'].map(textPattern);
const STOPPED = [' Booking has been stopped', 'Бронирование остановлено', 'Die Buchung wurde gestoppt'].map(textPattern);

export type CancelOutcome = 'deleted' | 'stopped' | 'unknown';

/** DEV-D-135: the answer message key of OP-BOOKINGS-CANCEL-ROOM (booking.deleted vs booking.stopped) tells the outcome. */
export function cancelOutcomeFromMessage(message: string | null | undefined): CancelOutcome {
  const m = (message ?? '').trim();
  if (DELETED.some((p) => p.test(m))) return 'deleted';
  if (STOPPED.some((p) => p.test(m))) return 'stopped';
  return 'unknown';
}
