import { create } from 'zustand';
import type { DateRange } from '@/domain/booking-model';
import type { RoomStatusView } from '@/domain/room-status';

/** Client UI state of the room screen (ARCHITECTURE §2 T22). Server data never lives here (it is in the query cache). */
export interface UiState {
  /** Tapped booking, kept by id (DEV-D-118: the booking is re-read from the list on every evaluation). */
  selectedBookingId: string | null;
  /** Range of the open booking form; null = form closed (SCR-ROOM/ST-FORM-OPEN). */
  selectedRange: DateRange | null;
  /** A quick booking request is in flight (SCR-ROOM/ST-QUICK-BOOKING, DT-QUICK-08). */
  quickBookingInFlight: boolean;
  /** Last evaluation published by the room screen; null = no room screen shown (LED not driven, DEV-D-93). */
  roomStatus: RoomStatusView | null;
  /** +1 on every publish (status-5s tick or change): LedStatus re-asserts on it (DEV-D-92). */
  statusSeq: number;
  /** +1 when the timeline should scroll to now (idle deselect, quick booking). */
  scrollToNowSeq: number;
}

export interface UiActions {
  /** Select a booking (closes the form) or clear the selection with null. */
  selectBooking(id: string | null): void;
  /** Open the form with a range (clears the booking selection). */
  openForm(range: DateRange): void;
  /** Move the form range (time picker); ignored while the form is closed. */
  setRange(range: DateRange): void;
  closeForm(): void;
  setQuickBookingInFlight(inFlight: boolean): void;
  publishRoomStatus(view: RoomStatusView | null): void;
  requestScrollToNow(): void;
  /** Clear selection and form (day change, idle home). */
  resetSelection(): void;
}

export type UiStore = UiState & UiActions;

const INITIAL: UiState = {
  selectedBookingId: null,
  selectedRange: null,
  quickBookingInFlight: false,
  roomStatus: null,
  statusSeq: 0,
  scrollToNowSeq: 0,
};

/** The app-wide UI store (module singleton; tests call `resetUiStore()`). */
export const useUiStore = create<UiStore>()((set) => ({
  ...INITIAL,
  selectBooking: (id) => set(id === null ? { selectedBookingId: null } : { selectedBookingId: id, selectedRange: null }),
  openForm: (range) => set({ selectedRange: range, selectedBookingId: null }),
  setRange: (range) => set((s) => (s.selectedRange ? { selectedRange: range } : {})),
  closeForm: () => set({ selectedRange: null }),
  setQuickBookingInFlight: (inFlight) => set({ quickBookingInFlight: inFlight }),
  publishRoomStatus: (view) => set((s) => ({ roomStatus: view, statusSeq: s.statusSeq + 1 })),
  requestScrollToNow: () => set((s) => ({ scrollToNowSeq: s.scrollToNowSeq + 1 })),
  resetSelection: () => set({ selectedBookingId: null, selectedRange: null }),
}));

/** Test helper: back to the initial state. */
export function resetUiStore(): void {
  useUiStore.setState(INITIAL);
}
