import { err, ok } from '@/kernel';
import { OPS, parseCompanyCard, refineRefusal } from '@/contract';
import type { HttpClient } from '@/data/http';
import type { ActivationApi } from '@/state/session';

/**
 * The two activation calls for `createSessionStore` (state/session cannot reach data/http itself):
 * OP-AUTH-COMPANY-CARD on the auth host (no token, DEV-D-89) and OP-AUTH-PIN-LOGIN on the derived tenant origin
 * (no token; a 401 never logs out, DEV-D-11). Refusals carry the card key (`auth.invalid_credentials`, …).
 */
export function createActivationApi(http: HttpClient): ActivationApi {
  return {
    async companyCard(subDomain) {
      const r = await http.get('/api/resolve-company-by-domain', { op: OPS.companyCard, host: 'auth', query: { subDomain }, expireSession: false });
      if (!r.ok) return err(refineRefusal(OPS.companyCard, r.error));
      const card = parseCompanyCard(r.value.body);
      return card.ok ? ok({ blocked: card.value.blocked, subDomain: card.value.subDomain }) : card;
    },
    async pinLogin(apiOrigin, pin) {
      const r = await http.post('/api/auth/login-unspot-space', { pin }, { op: OPS.pinLogin, host: { origin: apiOrigin }, expireSession: false });
      if (!r.ok) return err(refineRefusal(OPS.pinLogin, r.error));
      const body = r.value.body as { token?: unknown; refresh_token?: unknown } | null;
      if (typeof body?.token !== 'string' || !body.token) return err({ kind: 'invalid-response', code: 'invalid-response', op: OPS.pinLogin });
      return ok({ token: body.token, refreshToken: typeof body.refresh_token === 'string' ? body.refresh_token : null });
    },
  };
}
