import { useState, type FormEvent } from 'react';
import { useT, type I18nKey, type TFn } from '@/i18n';
import { extractCompanyLabel, useSessionStore, type ActivationError } from '@/state/session';
import { ASSETS } from '@/ui/theme';
import { PIN_LENGTH, PinInput } from './pin-input';
import styles from './activation.module.css';

const ASCII = /^[\u0000-\u007F]*$/;
/** DEV-D-13: the raw input may be up to 255 ASCII characters; the 2..25 rule applies to the extracted label. */
export const COMPANY_MAX_LENGTH = 255;

/** Live company rule (SCR-ACTIVATION company-messages, only once the field is dirty). */
export function companyFieldError(value: string): I18nKey | null {
  if (!value) return 'LOGIN.EMPTY_DOMAIN_ERROR';
  if (value.length < 2 || value.length > COMPANY_MAX_LENGTH || !ASCII.test(value)) return 'LOGIN.INCORRECT_DATA_INPUT';
  return null;
}

/** Text of an activation error (session error table): LOGIN.* keys, DEV-D-14 connection text, DEV-D-15 server text. */
function errorText(e: ActivationError, t: TFn): string {
  if (e.code.startsWith('LOGIN.')) return t(e.code as I18nKey);
  if (e.code === 'network') return t('APP.SERVER_CONNECTION_LOST');
  if (e.serverText) return e.serverText;
  return t('APP.REQUEST_FAILED');
}

interface CompanyFieldProps {
  value: string;
  message: string | null;
  label: string;
  placeholder: string;
  onChange(value: string): void;
}

/** SCR-ACTIVATION company-field + company-messages: red border and the message under the field. */
function CompanyField({ value, message, label, placeholder, onChange }: CompanyFieldProps): JSX.Element {
  return (
    <div className={styles.field}>
      <label className={styles.label} htmlFor="subDomainField">
        {label}
      </label>
      <input
        id="subDomainField"
        className={`${styles.input} ${message ? styles.invalid : ''}`}
        type="text"
        autoComplete="off"
        placeholder={placeholder}
        value={value}
        maxLength={COMPANY_MAX_LENGTH}
        aria-invalid={message ? true : undefined}
        aria-describedby={message ? 'subDomainError' : undefined}
        onChange={(e) => onChange(e.target.value)}
      />
      {message && (
        <p id="subDomainError" className={styles.error}>
          {message}
        </p>
      )}
    </div>
  );
}

export interface ActivationScreenProps {
  /** RLD-LOGIN (DEV-D-17 KEEP): called after the tokens are stored; app/router passes the full page reload. */
  onActivated(): void;
}

/** SCR-ACTIVATION (FLOW-DISP-ACTIVATE): company + 6-digit activation code → Connect. */
export function ActivationScreen({ onActivated }: ActivationScreenProps): JSX.Element {
  const t = useT();
  const session = useSessionStore();
  const [company, setCompany] = useState('');
  const [dirty, setDirty] = useState(false);
  const [digits, setDigits] = useState<string[]>(() => Array<string>(PIN_LENGTH).fill(''));
  const [companyError, setCompanyError] = useState<string | null>(null);
  const [pinError, setPinError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [done, setDone] = useState(false);

  const fieldError = dirty ? companyFieldError(company) : null;
  const pin = digits.join('');
  const canSubmit = !busy && !done && companyFieldError(company) === null && /^\d{6}$/.test(pin);

  const submit = async (e: FormEvent): Promise<void> => {
    e.preventDefault();
    if (!canSubmit) return;
    const label = extractCompanyLabel(company);
    if (!label) {
      setCompanyError(t('LOGIN.INCORRECT_DATA_INPUT')); // ST-BAD-LABEL: no request, PIN kept
      return;
    }
    setCompany(label); // the field shows the reduced label (FLOW-DISP-ACTIVATE step 3)
    setBusy(true);
    const r = await session.getState().activate({ company: label, pin });
    setBusy(false);
    if (r.ok) {
      setDone(true);
      onActivated();
      return;
    }
    // DEV-D-11: a PIN refusal shows the text and keeps both values (no logout, no reload).
    if (r.error.field === 'company') setCompanyError(errorText(r.error, t));
    else setPinError(errorText(r.error, t));
  };

  const companyMessage = companyError ?? (fieldError ? t(fieldError) : null);
  return (
    <main className={styles.page}>
      <div className={styles.card}>
        <img className={styles.logo} src={ASSETS.inverseLogo} alt="Unspot logo" />
        <p className={styles.subtitle}>{t('LOGIN.SUBTITLE')}</p>
        <form className={styles.form} noValidate onSubmit={(e) => void submit(e)}>
          <CompanyField
            value={company}
            message={companyMessage}
            label={t('LOGIN.COMPANY_SUBDOMAIN_LABEL')}
            placeholder={t('LOGIN.DOMAIN')}
            onChange={(v) => {
              setCompany(v);
              setDirty(true);
              setCompanyError(null);
            }}
          />
          <div className={`${styles.field} ${styles.codeField}`}>
            <span className={styles.label}>{t('LOGIN.ACTIVATION_CODE_LABEL')}</span>
            <PinInput
              digits={digits}
              invalid={pinError !== null}
              label={t('LOGIN.ACTIVATION_CODE_LABEL')}
              onChange={(d) => {
                setDigits(d);
                setPinError(null);
              }}
            />
            {pinError && <p className={styles.error}>{pinError}</p>}
          </div>
          <button className={styles.connect} type="submit" disabled={!canSubmit}>
            {t('LOGIN.CONNECT')}
          </button>
        </form>
      </div>
    </main>
  );
}
