import { useCallback, useEffect, useSyncExternalStore, type ReactNode } from 'react';
import { useAppEvent } from '@/kernel';
import { useT } from '@/i18n';
import { dialogs, type DialogEntry } from './dialogs';
import { CloseIcon } from './icons';
import styles from './dialog.module.css';

export interface DialogProps {
  children: ReactNode;
  /** Close (X) handler; the X button is shown when set. */
  onClose?: () => void;
  /** id of the element naming the dialog (e.g. the question heading), else `ariaLabel`. */
  labelledBy?: string;
  ariaLabel?: string;
  className?: string;
}

/** Modal panel (role="dialog", aria-modal) with the legacy dark card look; place it inside dialogs.open(). */
export function Dialog({ children, onClose, labelledBy, ariaLabel, className }: DialogProps): JSX.Element {
  const t = useT();
  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-labelledby={labelledBy}
      aria-label={labelledBy ? undefined : ariaLabel}
      className={[styles.panel, className].filter(Boolean).join(' ')}
      onClick={(e) => e.stopPropagation()}
    >
      {onClose ? (
        <button type="button" className={styles.close} aria-label={t('APP.CLOSE')} onClick={onClose}>
          <CloseIcon size={32} />
        </button>
      ) : null}
      {children}
    </div>
  );
}

function HostEntry({ entry }: { entry: DialogEntry }): JSX.Element {
  const close = useCallback((result?: unknown) => dialogs.close(entry.id, result), [entry.id]);
  const onOverlay = (): void => {
    if (entry.options.closeOnOverlay !== false) close(undefined);
  };
  return (
    <div className={styles.overlay} data-testid="dialog.overlay" onClick={onOverlay}>
      <div className={styles.tint} />
      {entry.render({ close })}
    </div>
  );
}

/**
 * Renders the dialog stack once (app shell). Closes every dialog on `idle.timeout` (TMR-APP-IDLE-HOME, ARCHITECTURE §3)
 * and the top one on Escape. Needs KernelProvider (event bus) and the i18n instance.
 */
export function DialogHost(): JSX.Element | null {
  const entries = useSyncExternalStore(dialogs.subscribe, dialogs.snapshot, dialogs.snapshot);
  useAppEvent('idle.timeout', useCallback(() => dialogs.closeAll(), []));
  const top = entries[entries.length - 1];
  useEffect(() => {
    if (!top) return undefined;
    const onKey = (e: KeyboardEvent): void => {
      if (e.key === 'Escape') dialogs.close(top.id, undefined);
    };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [top]);
  if (entries.length === 0) return null;
  return (
    <>
      {entries.map((entry) => (
        <HostEntry key={entry.id} entry={entry} />
      ))}
    </>
  );
}
