import type { QueryClient } from '@tanstack/react-query';
import type { Booking } from '@/domain/booking-model';
import type { CheckInDefaults, Me, RoomCheckInSettings } from '@/contract';
import { applyPatch, recordPatch, type BookingPatch } from './journal';
import { bookingMatchesScope, queryKeys, scopeOfKey, type BookingsDayScope } from './query-keys';

/** Applies a booking patch to every cached bookingsDay key of `generation` (immutable setQueryData) and journals it. */
function patchDays(qc: QueryClient, generation: number, patch: BookingPatch): void {
  recordPatch(qc, generation, patch);
  for (const [key, data] of qc.getQueriesData<Booking[]>({ queryKey: queryKeys.bookingsDayAll(generation) })) {
    const scope = scopeOfKey(key);
    if (!scope || !data) continue;
    const next = applyPatch(data, patch, scope);
    if (next !== data) qc.setQueryData<Booking[]>(key, [...next]);
  }
}

/**
 * Cache patches for the real-time bridge and the commands (ADR-0004 §3). All are immutable, generation-scoped and
 * journaled so a day read in flight re-applies them over its answer (deletes win).
 */
export const cachePatches = {
  /** booking_created / create answer: add where `filter` matches and the id is unknown (dedup of the echo). */
  insertBooking(
    qc: QueryClient,
    generation: number,
    booking: Booking,
    filter: (b: Booking, s: BookingsDayScope) => boolean = bookingMatchesScope,
  ): void {
    patchDays(qc, generation, { kind: 'insert', booking, filter });
  },
  /** booking_updated: replace by id where the id is known; never inserts. */
  replaceBooking(qc: QueryClient, generation: number, booking: Booking): void {
    patchDays(qc, generation, { kind: 'replace', booking });
  },
  /** Local change of one known booking (check-in mark, stop end). */
  patchBooking(qc: QueryClient, generation: number, id: string, fn: (b: Booking) => Booking): void {
    patchDays(qc, generation, { kind: 'map', id, fn });
  },
  /** booking_deleted / delete outcome: remove by id everywhere. */
  removeBooking(qc: QueryClient, generation: number, id: string): void {
    patchDays(qc, generation, { kind: 'remove', id });
  },
  /** room_settings_updated: replace me.device.space.checkInSettings when `roomId` is the own room. Returns whether it applied. */
  setRoomCheckInSettings(qc: QueryClient, generation: number, roomId: string, settings: RoomCheckInSettings): boolean {
    const me = qc.getQueryData<Me>(queryKeys.me(generation));
    const space = me?.device?.space;
    if (!me || !me.device || !space || space.id !== roomId) return false;
    qc.setQueryData<Me>(queryKeys.me(generation), { ...me, device: { ...me.device, space: { ...space, checkInSettings: settings } } });
    return true;
  },
  /** checkin_settings_updated: replace the company default room check-in settings. */
  setCheckInDefaults(qc: QueryClient, generation: number, defaults: CheckInDefaults): void {
    qc.setQueryData<CheckInDefaults>(queryKeys.checkInDefaults(generation), defaults);
  },
};
