import type { Booking, DateRange } from '@/domain/booking-model';
import { MINUTE, cutTo, defaultLength, freeSlots, type RoomBookingLimits } from './free-time';

export interface SlotTapInput {
  /** Instant the tap points at (the timeline converts its offset to a time, see timeline-layout `timeAt`). */
  tapAt: number;
  now: number;
  bookings: readonly Booking[];
  workingRanges: readonly DateRange[];
  limits: RoomBookingLimits;
}

export interface FormLimits {
  /** 15-min marks inside each free range up to its end - 1 min (the current start may be off-grid and is not listed). */
  startOptions: number[];
  /** 15-min marks after the start up to min(free range end, start + maxBookingDuration); the bound itself when off-grid. */
  endOptions: number[];
}

export type TitleResult = { ok: true; title: string } | { ok: false; error: 'required' | 'maxlength' };

const GRID = 15 * MINUTE;
export const DEFAULT_BOOKING_TITLE = 'Room Display';
export const TITLE_MAX_LENGTH = 255;

const floorGrid = (ms: number) => Math.floor(ms / GRID) * GRID;
const ceilGrid = (ms: number) => Math.ceil(ms / GRID) * GRID;

/** The slot the tap proposes before the free-window check (fe vertical-timeline-root getSlotFromClick). */
function tappedSlot(input: SlotTapInput): DateRange | null {
  const { tapAt, now, bookings, limits } = input;
  if (bookings.some((b) => b.start <= tapAt && tapAt < b.end)) return null; // DT-SLOT-02, DEV-D-56
  let start = Math.max(floorGrid(tapAt), now);
  let end = floorGrid(tapAt) + defaultLength(limits) * MINUTE;
  for (const b of bookings) {
    if (b.end <= tapAt) start = Math.max(start, b.end);
    else end = Math.min(end, b.start);
  }
  return end > start ? { start, end } : null; // DT-SLOT-03, DEV-D-56
}

/**
 * DT-SLOT-01..07 (read-only DT-SLOT-01 is `can('slot-tap')`, checked by the caller): the range a tap on an empty
 * place selects, or null (nothing happens). A slot that does not fit the first free window from its start selects
 * that window capped at maxBookingDuration (DEV-D-57 CHANGE).
 */
export function slotFromTap(input: SlotTapInput): DateRange | null {
  const slot = tappedSlot(input);
  if (!slot) return null;
  const window = freeSlots(input.bookings, input.workingRanges, slot.start)[0];
  if (!window) return null; // DT-SLOT-07
  if (window.start <= slot.start && slot.end <= window.end) return slot; // DT-SLOT-04
  return cutTo(window, input.limits.maxBookingDuration); // DT-SLOT-05, DT-SLOT-06 (a)
}

function marks(from: number, to: number): number[] {
  const out: number[] = [];
  for (let m = from; m <= to; m += GRID) out.push(m);
  return out;
}

/** Latest allowed end for `start`: end of its free range, capped at start + maxBookingDuration; null when start is not free. */
function endLimit(start: number, freeRanges: readonly DateRange[], limits: RoomBookingLimits): number | null {
  const range = freeRanges.find((r) => r.start <= start && start < r.end);
  if (!range) return null;
  return limits.maxBookingDuration ? Math.min(range.end, start + limits.maxBookingDuration * MINUTE) : range.end;
}

/** RULE-SLOT-GRID: start and end options of the booking form for the current start. */
export function formLimits(start: number, freeRanges: readonly DateRange[], limits: RoomBookingLimits): FormLimits {
  const sorted = [...freeRanges].sort((a, b) => a.start - b.start);
  const startOptions = sorted.flatMap((r) => marks(ceilGrid(r.start), r.end - MINUTE));
  const limit = endLimit(start, sorted, limits);
  if (limit === null) return { startOptions, endOptions: [] };
  const endOptions = marks(floorGrid(start) + GRID, limit);
  if (endOptions[endOptions.length - 1] !== limit) endOptions.push(limit);
  return { startOptions, endOptions };
}

/** RULE-SLOT-START-CHANGE: keep a valid end; else the next 15-min mark after start + 1 min, or the allowed end if that is beyond it. */
export function endAfterStartChange(start: number, end: number, freeRanges: readonly DateRange[], limits: RoomBookingLimits): number {
  const limit = endLimit(start, freeRanges, limits);
  if (limit === null) return end;
  if (end > start && end <= limit) return end;
  const next = ceilGrid(start + MINUTE);
  return next <= limit ? next : limit;
}

/** RULE-SLOT-TITLE: max 255; required -> non-space, sent trimmed; not required -> empty becomes 'Room Display', else as typed. */
export function formTitle(text: string, required: boolean): TitleResult {
  if (text.length > TITLE_MAX_LENGTH) return { ok: false, error: 'maxlength' };
  if (required) return text.trim() ? { ok: true, title: text.trim() } : { ok: false, error: 'required' };
  return { ok: true, title: text === '' ? DEFAULT_BOOKING_TITLE : text };
}
