/**
 * Pure service-worker rules (T38), shared by `sw.ts` (worker) and the page side; unit-tested here.
 * SW-PING / SW-API / SW-NAV / SW-SCRIPT / SW-ASSET / SW-OTHER (product/reference/kiosk-runtime.yaml), ADR-0005 §3.
 */
export type SwRoute = 'ping' | 'api' | 'nav' | 'script' | 'asset' | 'other';

export interface SwRequestInfo {
  url: string;
  method: string;
  mode: string;
  destination: string;
}

/** SW-SCOPE: GET only; routing looks at the path only (also cross-origin: API host, hub, LED). `null` = not handled. */
export function routeFor(req: SwRequestInfo): SwRoute | null {
  if (req.method !== 'GET') return null;
  const path = new URL(req.url).pathname;
  if (path.includes('/ping')) return 'ping';
  if (path.startsWith('/api/')) return 'api';
  if (req.mode === 'navigate') return 'nav';
  if (req.destination === 'script' || path.endsWith('.js')) return 'script';
  if (['style', 'image', 'font'].includes(req.destination) || req.url.includes('/img/') || req.url.includes('assets-cdn')) return 'asset';
  return 'other';
}

export interface SwCacheNames {
  static: string;
  assets: string;
  api: string;
}

/** DEV-D-29: names carry the build (`display-<area>-<build>`). */
export function swCacheNames(build: string): SwCacheNames {
  return { static: `display-static-${build}`, assets: `display-assets-${build}`, api: `display-api-${build}` };
}

/** STO-SW-CACHES of the legacy worker (frozen version; hold authorised API answers, DEV-D-30). */
export const LEGACY_CACHE_NAMES: readonly string[] = ['static-3.17.16', 'assets-3.17.16', 'api-3.17.16'];

/** ADR-0005 §3 activate: delete the legacy names and every `display-*` cache of another build; leave the rest. */
export function cachesToDelete(existing: readonly string[], build: string): string[] {
  const own = new Set(Object.values(swCacheNames(build)));
  return existing.filter((n) => LEGACY_CACHE_NAMES.includes(n) || (n.startsWith('display-') && !own.has(n)));
}

/** DEV-D-30: API caches to drop on logout (every build's, plus the legacy one). */
export function isApiCacheName(name: string): boolean {
  return name.startsWith('display-api-') || name === 'api-3.17.16';
}

/** SW-API: network failure with nothing cached. */
export function offlineApiResponse(): Response {
  return new Response(JSON.stringify({ error: 'offline' }), {
    status: 503,
    statusText: 'Service Unavailable',
    headers: { 'Content-Type': 'application/json' },
  });
}

/** SW-UPDATE message; a plain string, as the legacy page and worker use it (both directions of the migration). */
export const SKIP_WAITING = 'SKIP_WAITING';

export function isSkipWaitingMessage(data: unknown): boolean {
  return data === SKIP_WAITING || (typeof data === 'object' && data !== null && (data as { type?: unknown }).type === SKIP_WAITING);
}
