/**
 * API origin rule (FLAG-API-HOST, DEV-D-24, ADR-0004 §6) and the company field reduction (SCR-ACTIVATION field rules,
 * fe:src/js/controllers/pages/login.js:242-324, DEV-D-13).
 */
export interface ApiOriginInput {
  company: string;
  /** Runtime config `apiOriginTemplate`, e.g. `https://{company}.unspot.ru`; null → legacy derivation. */
  template: string | null;
  /** Page URL (window.location.href). */
  pageUrl: string;
  env?: string;
}

/** Origin of the tenant API at activation. At boot the stored STO-API-BASE-DOMAIN wins (session store). */
export function resolveApiOrigin({ company, template, pageUrl, env }: ApiOriginInput): string {
  if (template) return template.replace('{company}', company).replace(/\/+$/, '');
  const url = new URL(pageUrl);
  if (env === 'local' && url.port === '8888') url.port = ''; // DT-HOST-3
  const parts = url.hostname.split('.');
  if (parts.length >= 3) {
    parts[0] = company; // DT-HOST-1
    url.hostname = parts.join('.');
  } // DT-HOST-2: fewer than 3 labels → page origin kept
  return url.origin;
}

/** FLAG-COMPANY-SUBDOMAIN: API host minus its last two labels; null when not a URL. */
export function companyFromOrigin(origin: string): string | null {
  let host: string;
  try {
    host = new URL(origin).host;
  } catch {
    return null;
  }
  const parts = host.split('.');
  return parts.length >= 3 ? parts.slice(0, -2).join('.') : host;
}

const LABEL = /^[a-zA-Z0-9-]+$/;
const ASCII = /^[\x20-\x7E]*$/;

/** DEV-D-13: the 2..25 length rule applies to the extracted label, the raw text may be up to 255 ASCII characters. */
const checked = (label: string | undefined): string | null =>
  label !== undefined && LABEL.test(label) && label.length >= 2 && label.length <= 25 ? label : null;

const skipWww = (parts: string[]): string | undefined => (parts[0] === 'www' && parts.length > 1 ? parts[1] : parts[0]);

/** Company field → one DNS label (e-mail, URL, `*.unspot.ru|com`, plain domain), or null (SCR-ACTIVATION/ST-BAD-LABEL). */
export function extractCompanyLabel(raw: string): string | null {
  const input = raw.trim();
  if (!input || input.length > 255 || !ASCII.test(input)) return null;
  if (input.includes('@')) {
    const parts = input.split('@');
    return parts.length === 2 ? checked(parts[1]!.split('.')[0]) : null;
  }
  if (input.startsWith('http://') || input.startsWith('https://')) {
    let hostname: string;
    try {
      hostname = new URL(input).hostname;
    } catch {
      return null;
    }
    const parts = hostname.split('.');
    const unspot = hostname.endsWith('.unspot.ru') || hostname.endsWith('.unspot.com');
    return checked(unspot ? skipWww(parts) : parts[0]);
  }
  if (input.includes('.unspot.ru') || input.includes('.unspot.com')) return checked(skipWww(input.split('.')));
  if (/^[a-zA-Z0-9.-]+$/.test(input)) return checked(skipWww(input.split('.')));
  return null;
}
