import type { Clock, EventBus, Scheduler } from '@/kernel';

/** Page-lifetime health record (kiosk-runtime.yaml boot.health_model). Times are epoch ms, null = not yet. */
export interface HealthRecord {
  pageLoadedAt: number;
  bootstrappedAt: number | null;
  initStartedAt: number | null;
  initCompletedAt: number | null;
  initFailedAt: number | null;
  readyAt: number | null;
  lastHealthyAt: number | null;
}

export interface RuntimeHealth {
  snapshot(): HealthRecord;
  /** BOOT-5: the app rendered. */
  markBootstrapped(): void;
  /** BOOT-7 init (boot bundle) started / re-run: clears completed + failed marks. */
  initStarted(): void;
  initCompleted(): void;
  initFailed(): void;
  /** BOOT-10: first successful screen data load. The first call runs `onFirstReady` (boot-recovery marks cleared). */
  markReady(): void;
  /** DEV-D-5: written by the shown screen's own status evaluation (5 s tick), not by a bare timer. */
  heartbeat(): void;
}

export function createRuntimeHealth(deps: { clock: Clock; pageLoadedAt?: number; onFirstReady?: () => void }): RuntimeHealth {
  const { clock } = deps;
  const h: HealthRecord = {
    pageLoadedAt: deps.pageLoadedAt ?? clock.now(),
    bootstrappedAt: null,
    initStartedAt: null,
    initCompletedAt: null,
    initFailedAt: null,
    readyAt: null,
    lastHealthyAt: null,
  };
  return {
    snapshot: () => ({ ...h }),
    markBootstrapped: () => void (h.bootstrappedAt ??= clock.now()),
    initStarted: () => {
      h.initStartedAt = clock.now();
      h.initCompletedAt = null;
      h.initFailedAt = null;
    },
    initCompleted: () => {
      h.initCompletedAt = clock.now();
      h.initFailedAt = null;
    },
    initFailed: () => void (h.initFailedAt = clock.now()),
    markReady: () => {
      const first = h.readyAt === null;
      h.readyAt ??= clock.now();
      h.lastHealthyAt = clock.now();
      if (first) deps.onFirstReady?.();
    },
    heartbeat: () => void (h.lastHealthyAt = clock.now()),
  };
}

export const RECOVERY_TIMINGS = {
  bootMs: 60_000,
  readyMs: 60_000,
  heartbeatStaleMs: 10 * 60_000,
  lockMs: 5_000,
} as const;

export type RecoveryDecision = 'none' | 'soft' | 'hard';

/** CONN-RECOVERY DT-RECOVER-1…6 + DT-RECOVER-KIND-1…3 (pure). DT-RECOVER-4 (fatalErrorAt) never happens: not modelled. */
export function decideRecovery(h: HealthRecord, now: number): RecoveryDecision {
  const t = RECOVERY_TIMINGS;
  const recover =
    (h.bootstrappedAt === null && now - h.pageLoadedAt >= t.bootMs) || // DT-RECOVER-1
    h.initFailedAt !== null || // DT-RECOVER-2
    (h.readyAt === null && now - (h.initCompletedAt ?? h.bootstrappedAt ?? h.pageLoadedAt) >= t.readyMs) || // DT-RECOVER-3
    (h.readyAt !== null && (h.lastHealthyAt === null || now - h.lastHealthyAt >= t.heartbeatStaleMs)); // DT-RECOVER-5
  if (!recover) return 'none'; // DT-RECOVER-6
  if (h.initFailedAt !== null && h.readyAt === null) return 'soft'; // DT-RECOVER-KIND-1
  if (h.initCompletedAt === null) return 'soft'; // DT-RECOVER-KIND-2
  return 'hard'; // DT-RECOVER-KIND-3
}

export interface RecoveryDeps {
  health: RuntimeHealth;
  clock: Clock;
  scheduler: Scheduler;
  events: EventBus;
  /** The ONE page reload of app/bootstrap (RLD-WD-HARD). */
  reload: (reason: string) => void;
}

/**
 * `recover()` is the `ConnectivityDeps.recover` hook (called after a successful connectivity ping). Soft = emit
 * `app.reinitRequested` (RLD-WD-SOFT: app re-runs the boot bundle) + 5 s lock (`recovery-lock-5s`, TMR-WD-RECOVERY-LOCK);
 * hard = page reload (RLD-WD-HARD). Returns true when a recovery was started (the healthy ping is then skipped).
 */
export function createRecovery(deps: RecoveryDeps): { recover(): boolean } {
  return {
    recover() {
      if (deps.scheduler.has('recovery-lock-5s')) return false;
      const decision = decideRecovery(deps.health.snapshot(), deps.clock.now());
      if (decision === 'none') return false;
      if (decision === 'hard') {
        deps.reload('watchdog_hard');
        return true;
      }
      deps.scheduler.after('recovery-lock-5s', RECOVERY_TIMINGS.lockMs, () => undefined);
      deps.health.initStarted();
      deps.events.emit({ type: 'app.reinitRequested' });
      return true;
    },
  };
}
