import type { AppError, Clock, EventBus, Result, Scheduler } from '@/kernel';
import type { RealtimeConnection, RealtimeTransport } from './transport';
import { createTokenCache, type RealtimeToken } from './token-cache';

/** events.yaml message envelope after JSON.parse: `{action, data}`. */
export interface RealtimeMessage {
  action: string;
  data: unknown;
}


export interface RealtimeClientDeps {
  /** config `mercureHubUrl` (legacy PRIVATE_MERCURE_URL). Unparsable → no stream, reported once (DEV-D-84). */
  hubUrl: string;
  /** `companyTopic(subDomain)` = `tenant-<sub-domain lower-cased>` (DEV-D-85). */
  topic: string;
  /** OP-RT-TOKEN through data/http; a 401 must come back as `status: 401` or `kind: 'unauthorized'` and must NOT log out. */
  getToken: () => Promise<Result<RealtimeToken, AppError>>;
  transport: RealtimeTransport;
  clock: Clock;
  scheduler: Scheduler;
  events: EventBus;
  /** Error sink (telemetry). Never receives payloads or URLs with the token. */
  report?: (error: unknown, where: string) => void;
  /** Jitter source (default Math.random). */
  random?: () => number;
  /** visibilitychange source (default document). */
  doc?: Pick<Document, 'addEventListener' | 'removeEventListener' | 'visibilityState'>;
}

export type RealtimeStatus = 'stopped' | 'connecting' | 'open' | 'waiting';

export interface RealtimeClient {
  /** Opens the stream (session ready). The first successful open never emits `realtime.reconnected`. */
  start(): void;
  /** Closes the stream, cancels timers, clears the token cache (logout / session.expired). */
  stop(): void;
  /** Handler of every message; handlers run isolated (DEV-D-84). Returns unsubscribe. */
  subscribe(handler: (message: RealtimeMessage) => void): () => void;
  /** TMR-MERCURE-VISIBLE: open now when started and neither open nor connecting. */
  reconnectIfNeeded(): void;
  status(): RealtimeStatus;
}

export const REALTIME_TIMINGS = {
  reconnectMs: 2000,
  jitterMs: 500,
  unauthorizedFirstMs: 30_000,
  unauthorizedMaxMs: 5 * 60_000,
  tokenEarlyRefreshMs: 5 * 60_000,
  tokenFallbackMs: 30_000,
} as const;

export const REALTIME_JOB = 'realtime-reconnect';

export function companyTopic(subDomain: string): string {
  return `tenant-${subDomain.toLowerCase()}`;
}

function hubUrlWith(hubUrl: string, topic: string, token: string): string | null {
  try {
    const url = new URL(hubUrl);
    url.searchParams.set('topic', topic);
    url.searchParams.set('authorization', token);
    return url.toString();
  } catch {
    return null;
  }
}

const isUnauthorized = (e: AppError): boolean => e.status === 401 || e.kind === 'unauthorized';

function parseMessage(raw: string): RealtimeMessage | null {
  try {
    const parsed = JSON.parse(raw) as { action?: unknown; data?: unknown } | null;
    if (!parsed || typeof parsed.action !== 'string' || !parsed.action) return null;
    return { action: parsed.action, data: parsed.data };
  } catch {
    return null;
  }
}

/** Mutable state of one client; the helpers below take it explicitly (keeps each function short). */
interface Ctx {
  deps: RealtimeClientDeps;
  tokens: ReturnType<typeof createTokenCache>;
  handlers: Set<(m: RealtimeMessage) => void>;
  started: boolean;
  state: RealtimeStatus;
  conn: RealtimeConnection | null;
  /** Bumped by every connect and by stop(): callbacks of an older attempt are ignored. */
  attempt: number;
  hasConnected: boolean;
  unauthorizedDelay: number;
  badUrlReported: boolean;
}

function closeConn(ctx: Ctx): void {
  ctx.conn?.close();
  ctx.conn = null;
}

function scheduleReconnect(ctx: Ctx, delayMs?: number): void {
  const random = ctx.deps.random ?? Math.random;
  ctx.state = 'waiting';
  const delay = delayMs ?? REALTIME_TIMINGS.reconnectMs + Math.floor(random() * REALTIME_TIMINGS.jitterMs);
  ctx.deps.scheduler.after(REALTIME_JOB, delay, () => connect(ctx));
}

/** DEV-D-81: close, clear the token cache, retry after 30 s doubling to a 5 min cap. */
function onUnauthorized(ctx: Ctx): void {
  closeConn(ctx);
  ctx.tokens.clear();
  ctx.unauthorizedDelay = ctx.unauthorizedDelay
    ? Math.min(ctx.unauthorizedDelay * 2, REALTIME_TIMINGS.unauthorizedMaxMs)
    : REALTIME_TIMINGS.unauthorizedFirstMs;
  scheduleReconnect(ctx, ctx.unauthorizedDelay);
}

/** events.yaml transport.routing + DEV-D-84: each handler isolated; errors reported without the payload. */
function dispatch(ctx: Ctx, raw: string): void {
  const msg = parseMessage(raw);
  if (!msg) return;
  for (const h of [...ctx.handlers]) {
    try {
      h(msg);
    } catch (e) {
      ctx.deps.report?.(e, `realtime handler ${msg.action}`);
    }
  }
}

function openStream(ctx: Ctx, url: string, mine: number): void {
  ctx.conn = ctx.deps.transport.open(url, {
    onOpen: () => {
      if (mine !== ctx.attempt) return;
      ctx.state = 'open';
      ctx.unauthorizedDelay = 0;
      if (ctx.hasConnected) ctx.deps.events.emit({ type: 'realtime.reconnected' });
      ctx.hasConnected = true;
    },
    onMessage: (data) => {
      if (mine === ctx.attempt) dispatch(ctx, data);
    },
    onError: () => {
      if (mine !== ctx.attempt) return;
      closeConn(ctx);
      scheduleReconnect(ctx);
    },
  });
}

/** (Re)open now: closes the current stream, takes a token (cache first), opens a new stream. */
function connect(ctx: Ctx): void {
  const { deps } = ctx;
  if (!ctx.started) return;
  deps.scheduler.cancel(REALTIME_JOB);
  closeConn(ctx);
  const mine = ++ctx.attempt;
  if (hubUrlWith(deps.hubUrl, deps.topic, 'x') === null) {
    if (!ctx.badUrlReported) deps.report?.(new Error('Real-time hub URL is invalid'), 'realtime hub url');
    ctx.badUrlReported = true;
    ctx.state = 'waiting';
    return;
  }
  ctx.state = 'connecting';
  void ctx.tokens.get().then((r) => {
    if (mine !== ctx.attempt || !ctx.started) return;
    if (!r.ok) return isUnauthorized(r.error) ? onUnauthorized(ctx) : scheduleReconnect(ctx);
    openStream(ctx, hubUrlWith(deps.hubUrl, deps.topic, r.value) ?? '', mine);
  });
}

/**
 * Mercure client (T30, ADR-0004 §4): one stream for the session; TMR-MERCURE-RECONNECT (2 s + 0–500 ms, unlimited,
 * DEV-D-82); token 401 → 30 s doubling to 5 min (DEV-D-81); TMR-MERCURE-VISIBLE; reopen after connectivity returns
 * (DEV-D-119); `realtime.reconnected` after every successful open except the first (DEV-D-83).
 */
export function createRealtimeClient(deps: RealtimeClientDeps): RealtimeClient {
  const ctx: Ctx = {
    deps,
    tokens: createTokenCache(deps.getToken, deps.clock),
    handlers: new Set(),
    started: false,
    state: 'stopped',
    conn: null,
    attempt: 0,
    hasConnected: false,
    unauthorizedDelay: 0,
    badUrlReported: false,
  };
  const unsubs: Array<() => void> = [];
  let network: 'online' | 'offline' | 'reconnecting' = 'online';
  const reconnectIfNeeded = (): void => {
    if (ctx.started && ctx.state !== 'open' && ctx.state !== 'connecting') connect(ctx);
  };
  const doc = deps.doc ?? document;
  const onVisibility = (): void => {
    if (doc.visibilityState === 'visible') reconnectIfNeeded();
  };

  return {
    start() {
      if (ctx.started) return;
      ctx.started = true;
      ctx.hasConnected = false;
      doc.addEventListener('visibilitychange', onVisibility);
      unsubs.push(() => doc.removeEventListener('visibilitychange', onVisibility));
      unsubs.push(
        deps.events.on('connectivity.changed', (e) => {
          const was = network;
          network = e.state;
          if (e.state === 'online' && was !== 'online') connect(ctx);
        }),
      );
      connect(ctx);
    },
    stop() {
      ctx.started = false;
      ctx.attempt += 1;
      deps.scheduler.cancel(REALTIME_JOB);
      closeConn(ctx);
      ctx.tokens.clear();
      ctx.state = 'stopped';
      ctx.unauthorizedDelay = 0;
      unsubs.splice(0).forEach((u) => u());
    },
    subscribe(handler) {
      ctx.handlers.add(handler);
      return () => ctx.handlers.delete(handler);
    },
    reconnectIfNeeded,
    status: () => ctx.state,
  };
}
