import type { EventBus, Scheduler } from '@/kernel';

/** CONN-STATES. */
export type ConnectivityState = 'online' | 'offline' | 'reconnecting';
/** OP-DEVICE-PING forms: `connectivity` (?skipLogAndEvent=true) and `healthy` (no parameter). */
export type PingForm = 'connectivity' | 'healthy';
export type PingOutcome = 'ok' | 'fail';

export interface ConnectivityDeps {
  scheduler: Scheduler;
  events: EventBus;
  /** OP-DEVICE-PING through data/http (wired in app/providers). Must resolve, never reject; abort → 'fail'. */
  ping: (form: PingForm, signal: AbortSignal) => Promise<PingOutcome>;
  /** STO-TOKEN + STO-API-BASE-DOMAIN present. A check while not authenticated does nothing and stops the retry loop. */
  isAuthenticated: () => boolean;
  /** CONN-RECOVERY (owned by features/kiosk-runtime): called after a successful connectivity ping; return true when a
   *  recovery was started — the healthy ping is then skipped for this check. */
  recover?: () => boolean;
  /** Browser `online` / `offline` events source (default window). */
  target?: Pick<Window, 'addEventListener' | 'removeEventListener'>;
}

export interface Connectivity {
  /** First check now, then `ping-5m`; listens to browser online/offline. Idempotent. */
  start(): void;
  stop(): void;
  /** One health check (CONN-WATCHDOG); a call while a check runs is skipped. */
  check(): Promise<void>;
  state(): ConnectivityState;
  /** Listener for state changes (also emitted on the bus as `connectivity.changed`). */
  subscribe(listener: (state: ConnectivityState) => void): () => void;
}

/** Timings: TMR-WD-NORMAL 5 min, TMR-WD-RETRY 60 s, DEV-D-120 10 s, TMR-WD-PING-TIMEOUT 3 min. */
export const CONNECTIVITY_TIMINGS = {
  normalMs: 5 * 60_000,
  retryMs: 60_000,
  retryOnceMs: 10_000,
  pingTimeoutMs: 3 * 60_000,
} as const;

/** Scheduler job names (ARCHITECTURE §3). */
export const CONNECTIVITY_JOBS = {
  normal: 'ping-5m',
  retry: 'ping-retry-60s',
  retryOnce: 'ping-retry-10s',
  timeout: 'ping-timeout-3m',
} as const;

interface CheckLoop {
  check(): Promise<void>;
  stopRetries(): void;
  abort(): void;
}

/** CONN-WATCHDOG check, DEV-D-120 retry-once, TMR-WD-RETRY loop and TMR-WD-PING-TIMEOUT. */
function createCheckLoop(deps: ConnectivityDeps, getState: () => ConnectivityState, setState: (s: ConnectivityState) => void): CheckLoop {
  const { scheduler } = deps;
  let running = false;
  let failures = 0;
  let controller: AbortController | null = null;

  const stopRetries = (): void => {
    scheduler.cancel(CONNECTIVITY_JOBS.retry);
    scheduler.cancel(CONNECTIVITY_JOBS.retryOnce);
  };

  const pingOnce = async (form: PingForm): Promise<PingOutcome> => {
    const c = new AbortController();
    controller = c;
    scheduler.after(CONNECTIVITY_JOBS.timeout, CONNECTIVITY_TIMINGS.pingTimeoutMs, () => c.abort());
    try {
      return await deps.ping(form, c.signal);
    } catch {
      return 'fail';
    } finally {
      scheduler.cancel(CONNECTIVITY_JOBS.timeout);
      if (controller === c) controller = null;
    }
  };

  const onFailure = (): void => {
    failures += 1;
    if (getState() === 'online' && failures === 1) {
      scheduler.after(CONNECTIVITY_JOBS.retryOnce, CONNECTIVITY_TIMINGS.retryOnceMs, () => void check());
      return;
    }
    scheduler.cancel(CONNECTIVITY_JOBS.retryOnce);
    setState('offline');
    if (!scheduler.has(CONNECTIVITY_JOBS.retry)) {
      scheduler.every(CONNECTIVITY_JOBS.retry, CONNECTIVITY_TIMINGS.retryMs, () => {
        setState('reconnecting');
        void check();
      });
    }
  };

  const runCheck = async (): Promise<void> => {
    if ((await pingOnce('connectivity')) === 'fail') return onFailure();
    stopRetries();
    setState('online');
    // A failure counts as consecutive until a whole check passes (healthy ping, or a recovery took over).
    if (deps.recover?.() || (await pingOnce('healthy')) === 'ok') failures = 0;
    else onFailure();
  };

  async function check(): Promise<void> {
    if (running) return;
    if (!deps.isAuthenticated()) {
      stopRetries();
      return;
    }
    running = true;
    try {
      await runCheck();
    } finally {
      running = false;
    }
  }

  return { check, stopRetries, abort: () => controller?.abort() };
}

/**
 * Watchdog connectivity part (T29): CONN-WATCHDOG, CONN-STATES, TMR-WD-NORMAL / -RETRY / -PING-TIMEOUT / -ONLINE-EVENT,
 * DEV-D-120 (retry once after 10 s before going offline), DEV-D-121 (browser offline event → immediate check).
 */
export function createConnectivity(deps: ConnectivityDeps): Connectivity {
  const listeners = new Set<(s: ConnectivityState) => void>();
  let current: ConnectivityState = 'online';
  let started = false;
  const setState = (next: ConnectivityState): void => {
    if (next === current) return;
    current = next;
    deps.events.emit({ type: 'connectivity.changed', state: next });
    listeners.forEach((l) => l(next));
  };
  const loop = createCheckLoop(deps, () => current, setState);
  const onBrowserEvent = (): void => void loop.check();
  const target = deps.target ?? window;

  return {
    start() {
      if (started) return;
      started = true;
      target.addEventListener('online', onBrowserEvent);
      target.addEventListener('offline', onBrowserEvent);
      deps.scheduler.every(CONNECTIVITY_JOBS.normal, CONNECTIVITY_TIMINGS.normalMs, () => void loop.check());
      void loop.check();
    },
    stop() {
      started = false;
      target.removeEventListener('online', onBrowserEvent);
      target.removeEventListener('offline', onBrowserEvent);
      deps.scheduler.cancel(CONNECTIVITY_JOBS.normal);
      loop.stopRetries();
      loop.abort();
    },
    check: () => loop.check(),
    state: () => current,
    subscribe(listener) {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}
