import { useT } from '@/i18n';
import styles from './spinner.module.css';

export interface SpinnerProps {
  /** Centre in the nearest positioned ancestor (screen loaders: SCR-ROOM/ST-LOADING, SCR-BOOT-SPINNER). */
  centered?: boolean;
  /** Accessible name; default t('APP.LOADING'). */
  label?: string;
  className?: string;
}

/** Legacy blue ring spinner (TOK-SPINNER), role="status". */
export function Spinner({ centered = false, label, className }: SpinnerProps): JSX.Element {
  const t = useT();
  return (
    <div role="status" aria-label={label ?? t('APP.LOADING')} className={[styles.spinner, centered && styles.centered, className].filter(Boolean).join(' ')}>
      <span className={styles.ring} />
      <span className={styles.ring} />
      <span className={styles.ring} />
      <span className={styles.track} />
    </div>
  );
}
