import type { ReloadOptions } from './reload';

/** TMR-BOOT-GUARD: the app must be bootstrapped (rendered) 45 s after the entry script ran. */
export const BOOT_GUARD_MS = 45_000;
/** DEV-D-2 CHANGE: after the one-shot recovery, further stalls reload after 1, 2, 5 min, then every 5 min. */
export const BOOT_BACKOFF_MS = [60_000, 120_000, 300_000] as const;
/** STO-BOOT-RECOVERY-DONE / -REASON (raw sessionStorage, legacy names) + the DEV-D-2 attempt counter (port key). */
export const BOOT_KEYS = {
  done: 'unspot-space-bootstrap-recovery-done',
  reason: 'unspot-space-bootstrap-recovery-reason',
  attempts: 'unspot-space-bootstrap-backoff-attempts',
} as const;
export const RECOVERY_PARAM = '__bootstrap_recovery';

export type BootFailure = 'bootstrap_timeout' | 'bootstrap_failed';

export interface BootGuardDeps {
  /** sessionStorage (raw values, never through platform/storage); null when unavailable. */
  session: Pick<Storage, 'getItem' | 'setItem' | 'removeItem'> | null;
  timers: { set(fn: () => void, ms: number): unknown; clear(handle: unknown): void };
  /** Unregister every service worker and delete every Cache Storage entry. */
  wipe(): Promise<void>;
  reload(reason: string, options?: ReloadOptions): void;
  now(): number;
  href(): string;
}

export interface BootGuard {
  /** BOOT-3: start the 45 s guard. */
  arm(): void;
  /** BOOT-5 done (DT-BOOT-1): the guard does nothing any more. */
  bootstrapped(): void;
  /** BOOT-4/5 threw. */
  fail(reason: BootFailure): void;
  /** BOOT-10 first ready screen (DT-BOOT-4): marks and the back-off counter removed. */
  clearMarks(): void;
}

function safe<T>(fn: () => T, fallback: T): T {
  try {
    return fn();
  } catch {
    return fallback;
  }
}

/**
 * guard_45s (kiosk-runtime.yaml): DT-BOOT-1 bootstrapped in time → nothing; DT-BOOT-2 first stall in the tab session →
 * mark + reason, wipe workers and caches, reload with `?__bootstrap_recovery=<ms>` (DEV-D-1 KEEP); DT-BOOT-3 already
 * recovered → reason stored and, instead of the legacy endless spinner, a plain reload after a growing delay (DEV-D-2).
 */
export function createBootGuard(d: BootGuardDeps): BootGuard {
  let handle: unknown = null;
  let settled = false;
  const get = (k: string): string | null => safe(() => d.session?.getItem(k) ?? null, null);
  const set = (k: string, v: string): void => safe(() => d.session?.setItem(k, v), undefined);

  const stall = (reason: BootFailure): void => {
    if (settled) return;
    settled = true;
    if (handle !== null) d.timers.clear(handle);
    if (get(BOOT_KEYS.done) !== '1') {
      set(BOOT_KEYS.done, '1');
      set(BOOT_KEYS.reason, reason);
      const url = safe(() => {
        const u = new URL(d.href());
        u.searchParams.set(RECOVERY_PARAM, String(d.now()));
        return u.toString();
      }, d.href());
      void d
        .wipe()
        .catch(() => undefined)
        .then(() => d.reload('boot_recovery', { replaceUrl: url }));
      return;
    }
    set(BOOT_KEYS.reason, reason);
    const attempts = Number(get(BOOT_KEYS.attempts) ?? '0') || 0;
    set(BOOT_KEYS.attempts, String(attempts + 1));
    const delay = BOOT_BACKOFF_MS[Math.min(attempts, BOOT_BACKOFF_MS.length - 1)]!;
    d.timers.set(() => d.reload('boot_backoff'), delay);
  };

  return {
    arm() {
      if (handle === null && !settled) handle = d.timers.set(() => stall('bootstrap_timeout'), BOOT_GUARD_MS);
    },
    bootstrapped() {
      settled = true;
      if (handle !== null) d.timers.clear(handle);
      handle = null;
    },
    fail: (reason) => stall(reason),
    clearMarks() {
      Object.values(BOOT_KEYS).forEach((k) => safe(() => d.session?.removeItem(k), undefined));
    },
  };
}

/** Browser implementation of the guard dependencies (raw timers are allowed in app/bootstrap only). */
export function browserBootGuardDeps(reload: BootGuardDeps['reload']): BootGuardDeps {
  return {
    session: safe(() => window.sessionStorage, null),
    timers: { set: (fn, ms) => setTimeout(fn, ms), clear: (h) => clearTimeout(h as ReturnType<typeof setTimeout>) },
    wipe: async () => {
      const regs = (await navigator.serviceWorker?.getRegistrations?.()) ?? [];
      await Promise.all(regs.map((r) => r.unregister()));
      const names = (await globalThis.caches?.keys()) ?? [];
      await Promise.all(names.map((n) => globalThis.caches.delete(n)));
    },
    reload,
    now: () => Date.now(),
    href: () => window.location.href,
  };
}
