import type { LedColour, RoomStatus, StatusAccent } from './types';

/** room-status.yaml outputs.status_map -> accent token (TOK-STATUS-*). */
const ACCENT: Record<RoomStatus, StatusAccent> = {
  FREE: 'free',
  OCCUPIED: 'occupied',
  CHECKIN: 'checkin',
  BOOKING_SELECTED: 'booking-selected',
};

/** product/contract/led.yaml colours.map (Qbic hex + Crestron signals). */
const LED: Record<RoomStatus, Omit<LedColour, 'status'>> = {
  FREE: { hex: '#008000', rgb: { red: 0, green: 128, blue: 0 }, crestron: { red: false, green: true, blue: false } },
  OCCUPIED: { hex: '#FF0000', rgb: { red: 255, green: 0, blue: 0 }, crestron: { red: true, green: false, blue: false } },
  CHECKIN: { hex: '#ffff00', rgb: { red: 255, green: 255, blue: 0 }, crestron: { red: true, green: true, blue: false } },
  BOOKING_SELECTED: { hex: '#0000FF', rgb: { red: 0, green: 0, blue: 255 }, crestron: { red: false, green: false, blue: true } },
};

export function statusAccent(status: RoomStatus | null): StatusAccent {
  return status ? ACCENT[status] : 'free';
}

export function ledColour(status: RoomStatus): LedColour {
  return { status, ...LED[status] };
}
