import type { QueryClient } from '@tanstack/react-query';
import { appError, err, ok, type Kernel, type Result, type AppError } from '@/kernel';
import type { HttpClient } from '@/data/http';
import type { HostBridge } from '@/platform/host-bridge';
import type { Telemetry } from '@/platform/telemetry';
import type { SessionStore } from '@/state/session';
import { companyTopic, createRealtimeClient, type RealtimeClient, type RealtimeToken, type RealtimeTransport } from '@/realtime/mercure-client';
import { knownRoomsFromCache, startRealtimeBridge } from '@/realtime/bridge';

export const OP_RT_TOKEN = 'OP-RT-TOKEN';

/** OP-RT-TOKEN through data/http; a 401 here never logs out (expireSession: false, events.yaml transport.token). */
export async function fetchRealtimeToken(http: HttpClient): Promise<Result<RealtimeToken, AppError>> {
  const r = await http.get('/api/auth/mercure-token', { op: OP_RT_TOKEN, expireSession: false });
  if (!r.ok) return r;
  const body = r.value.body as { token?: unknown } | null;
  if (!body || typeof body.token !== 'string' || !body.token) return err(appError('invalid-response', 'invalid-response', { op: OP_RT_TOKEN }));
  return ok({ token: body.token });
}

export interface SessionServicesDeps {
  kernel: Kernel;
  session: SessionStore;
  http: HttpClient;
  queryClient: QueryClient;
  telemetry: Telemetry;
  hostBridge: HostBridge;
  hubUrl: string | null;
  transport: () => RealtimeTransport;
}

/**
 * Session status `ready` → Mercure client (topic from the session sub-domain) + bridge, and `hostBridge.sessionStarted`
 * once the device id is known; a new generation or sub-domain makes a new client; `anonymous` → everything stopped and
 * `hostBridge.sessionEnded` (ADR-0004 §4, ARCHITECTURE §3 "Session start is a state change"). Returns stop().
 */
export function startSessionServices(d: SessionServicesDeps): () => void {
  const { kernel, session, queryClient } = d;
  const report = (e: unknown, where: string): void => d.telemetry.captureError(e, { extras: { where }, rateLimitKey: where });
  let client: RealtimeClient | null = null;
  let stopBridge: (() => void) | null = null;
  let key = '';
  let hostFor: number | null = null;

  const stopRealtime = (): void => {
    stopBridge?.();
    client?.stop();
    stopBridge = null;
    client = null;
  };

  const startRealtime = (subDomain: string, hubUrl: string): void => {
    const generation = (): number => session.getState().generation;
    client = createRealtimeClient({
      hubUrl,
      topic: companyTopic(subDomain),
      getToken: () => fetchRealtimeToken(d.http),
      transport: d.transport(),
      clock: kernel.clock,
      scheduler: kernel.scheduler,
      events: kernel.events,
      report,
    });
    stopBridge = startRealtimeBridge({
      client,
      queryClient,
      events: kernel.events,
      generation,
      deviceId: () => session.getState().deviceId,
      knownRooms: () => knownRoomsFromCache(queryClient, generation()),
      report,
      onInvalid: (info) => d.telemetry.captureEvent('invalid_event', { level: 'warning', extras: { op: info.op, issues: info.issues.join(',') }, rateLimitKey: `invalid:${info.op}` }),
    });
    client.start();
  };

  const sync = (): void => {
    const s = session.getState();
    const ready = s.status === 'ready';
    const want = ready && s.subDomain && d.hubUrl ? `${s.generation}|${s.subDomain}` : '';
    if (want !== key) {
      stopRealtime();
      key = want;
      if (want) startRealtime(s.subDomain!, d.hubUrl!);
    }
    if (ready && s.deviceId && s.apiOrigin && hostFor !== s.generation) {
      hostFor = s.generation;
      d.hostBridge.sessionStarted({ deviceId: s.deviceId, apiOrigin: s.apiOrigin });
    }
    if (!ready && hostFor !== null) {
      hostFor = null;
      d.hostBridge.sessionEnded();
    }
  };

  const unsubscribe = session.subscribe(sync);
  sync();
  return () => {
    unsubscribe();
    stopRealtime();
  };
}
