import { useRef, type ClipboardEvent, type KeyboardEvent } from 'react';
import styles from './activation.module.css';

export const PIN_LENGTH = 6;

/**
 * SCR-ACTIVATION code-boxes rules (fe:src/js/controllers/pages/login.js:43-116): non-digits dropped; several digits in
 * one box (autofill / paste) spread from that box onward. Returns the new digits and the box to focus next.
 */
export function spreadDigits(digits: readonly string[], index: number, text: string): { digits: string[]; focus: number } {
  const next = [...digits];
  const incoming = text.replace(/\D/g, '');
  if (!incoming) {
    next[index] = '';
    return { digits: next, focus: index };
  }
  let i = index;
  for (const ch of incoming) {
    if (i >= PIN_LENGTH) break;
    next[i] = ch;
    i += 1;
  }
  return { digits: next, focus: Math.min(i, PIN_LENGTH - 1) };
}

export interface PinInputProps {
  digits: readonly string[];
  invalid: boolean;
  disabled?: boolean;
  label: string;
  onChange(digits: string[]): void;
}

/** 6 one-character boxes (inputmode numeric, autocomplete one-time-code); red border while a PIN error is set. */
export function PinInput({ digits, invalid, disabled, label, onChange }: PinInputProps): JSX.Element {
  const refs = useRef<Array<HTMLInputElement | null>>([]);
  const focus = (i: number): void => refs.current[Math.max(0, Math.min(PIN_LENGTH - 1, i))]?.focus();

  const apply = (index: number, text: string): void => {
    const r = spreadDigits(digits, index, text);
    onChange(r.digits);
    if (text.replace(/\D/g, '')) focus(r.focus);
  };

  const onKeyDown = (e: KeyboardEvent<HTMLInputElement>, i: number): void => {
    if (e.key === 'Backspace' && !digits[i]) {
      e.preventDefault();
      focus(i - 1);
    } else if (e.key === 'ArrowLeft') {
      e.preventDefault();
      focus(i - 1);
    } else if (e.key === 'ArrowRight') {
      e.preventDefault();
      focus(i + 1);
    }
  };

  const onPaste = (e: ClipboardEvent<HTMLInputElement>, i: number): void => {
    e.preventDefault();
    apply(i, e.clipboardData.getData('text'));
  };

  return (
    <div className={styles.otpGroup} role="group" aria-label={label}>
      {Array.from({ length: PIN_LENGTH }, (_, i) => (
        <input
          key={i}
          ref={(el) => void (refs.current[i] = el)}
          className={`${styles.otp} ${invalid ? styles.invalid : ''}`}
          type="text"
          inputMode="numeric"
          autoComplete="one-time-code"
          aria-label={`${label} ${i + 1}`}
          aria-invalid={invalid || undefined}
          disabled={disabled}
          value={digits[i] ?? ''}
          onChange={(e) => apply(i, e.target.value.replace(digits[i] ?? '', '') || e.target.value)}
          onKeyDown={(e) => onKeyDown(e, i)}
          onPaste={(e) => onPaste(e, i)}
        />
      ))}
    </div>
  );
}
