import { useCallback, type ReactNode } from 'react';
import { I18nextProvider, useTranslation } from 'react-i18next';
import { getI18n, type TranslateParams } from './i18n';
import type { I18nKey } from './keys';

/** Wraps the app once (app/providers); re-renders consumers on a language change. */
export function I18nProvider({ children }: { children: ReactNode }): JSX.Element {
  return <I18nextProvider i18n={getI18n()}>{children}</I18nextProvider>;
}

export type TFn = (key: I18nKey, params?: TranslateParams) => string;
export type PrefixedTFn = (key: string, params?: TranslateParams) => string;

/**
 * Translate hook. `useT()` takes full legacy keys (typed): t('SPACE.FREE_UNTIL', { FOR, UNTIL }).
 * `useT('SPACE.BOOKING_INFO')` takes keys relative to that prefix: t('STOP'). Prefer full keys: the missing-key
 * test (i18n.test.ts) only sees full key literals.
 */
export function useT(): TFn;
export function useT(prefix: string): PrefixedTFn;
export function useT(prefix?: string): TFn | PrefixedTFn {
  const { t } = useTranslation(undefined, { i18n: getI18n(), ...(prefix ? { keyPrefix: prefix } : {}) });
  return useCallback((key: string, params?: TranslateParams) => String(t(key, params ?? {})), [t]);
}
