import { useMemo, useId } from 'react';
import { qrMatrix } from './qr-matrix';
import styles from './qr.module.css';

export interface QrCodeProps {
  /** Encoded text (deep link built by the feature, product/contract/deep-links.yaml). */
  value: string;
  /** Rendered side in px: 100 in the QR card (TOK-QR-CARD), 300 in the modal (TOK-QR-MODAL). */
  size?: number;
  /** Accessible name (role="img"); omit for a decorative QR inside a named button. */
  label?: string;
  className?: string;
}

/** QR code as inline SVG (qrcode-svg matrix, ecl M, 4-module white border); no innerHTML. */
export function QrCode({ value, size = 100, label, className }: QrCodeProps): JSX.Element {
  const { size: n, path } = useMemo(() => qrMatrix(value), [value]);
  const titleId = useId();
  const side = n + 8;
  return (
    <svg
      className={[styles.qr, className].filter(Boolean).join(' ')}
      width={size}
      height={size}
      viewBox={`0 0 ${side} ${side}`}
      shapeRendering="crispEdges"
      role={label ? 'img' : undefined}
      aria-labelledby={label ? titleId : undefined}
      aria-hidden={label ? undefined : true}
      data-qr-value={value}
    >
      {label ? <title id={titleId}>{label}</title> : null}
      <rect className={styles.light} width={side} height={side} />
      <path className={styles.dark} d={path} />
    </svg>
  );
}
