import type { Booking } from '@/domain/booking-model';
import { DEFAULT_BOOKING_TITLE } from '@/domain/booking-slots';
import { can, type DeviceAbilities, type PermissionRoom } from '@/domain/permissions';

/** A title line: literal text, or the i18n key shown for a default display booking. */
export type TitleText = { text: string } | { key: 'APP.BOOKED_FROM_DISPLAY' };

export interface BlockTitles {
  main: TitleText | null;
  secondary: TitleText | null;
}

export interface BlockTitlesContext {
  /** This room's name: the secondary line of a display-made booking. */
  roomName: string;
  room: PermissionRoom;
  abilities: DeviceAbilities;
  now: number;
}

function organizerName(b: Booking): string {
  return b.organizer.fullName.trim() || b.organizer.email || b.organizer.fullName;
}

/**
 * SCR-ROOM timeline.booking-block titles (RULE-SLOT-TITLE-DISPLAY, PERM-19, PERM-20). User booking: main = organizer,
 * secondary = title. Display booking: main = title ('Room Display' -> APP.BOOKED_FROM_DISPLAY), secondary = room name.
 * Main only when can('see-organizer'), secondary only when can('see-title'). Combine with the length flags of
 * timeline-layout (`mainTitle` >= 30 min, `secondaryTitle` >= 60 min).
 */
export function blockTitles(b: Booking, ctx: BlockTitlesContext): BlockTitles {
  const pc = { abilities: ctx.abilities, room: ctx.room, booking: b, now: ctx.now };
  let main: TitleText = { text: organizerName(b) };
  let secondary: TitleText = { text: b.title };
  if (b.madeByDisplay) {
    main = b.title === DEFAULT_BOOKING_TITLE ? { key: 'APP.BOOKED_FROM_DISPLAY' } : { text: b.title };
    secondary = { text: ctx.roomName };
  }
  return { main: can('see-organizer', pc) ? main : null, secondary: can('see-title', pc) ? secondary : null };
}

/** DT-BOARD-01..03: a board room is busy when the selected day is today and one of its bookings contains now. */
export function isBusyNow(bookings: readonly Booking[], now: number, selectedDayIsToday: boolean): boolean {
  return selectedDayIsToday && bookings.some((b) => b.start <= now && now < b.end);
}
