import type { Clock } from './clock';
import { dayKey, addDaysInZone } from './clock';

/**
 * Port: every periodic or delayed piece of work is a named job (ARCHITECTURE §3 job table, TMR-*).
 * Re-registering a name replaces the previous job. Raw timers live only here and in platform/.
 */
export interface Scheduler {
  every(name: string, periodMs: number, fn: () => void): void;
  after(name: string, delayMs: number, fn: () => void): void;
  at(name: string, epochMs: number, fn: () => void): void;
  cancel(name: string): void;
  has(name: string): boolean;
  cancelAll(): void;
}

interface TimerHost {
  set(fn: () => void, ms: number): unknown;
  clear(handle: unknown): void;
}

const browserTimers: TimerHost = {
  set: (fn, ms) => setTimeout(fn, ms),
  clear: (h) => clearTimeout(h as ReturnType<typeof setTimeout>),
};

export function createScheduler(clock: Clock, host: TimerHost = browserTimers): Scheduler {
  const jobs = new Map<string, unknown>();
  const cancel = (name: string): void => {
    const h = jobs.get(name);
    if (h !== undefined) host.clear(h);
    jobs.delete(name);
  };
  const run = (name: string, fn: () => void): void => {
    try {
      fn();
    } catch (e) {
      // A failing job never stops the scheduler (kiosk runs for weeks).
      console.error(`[scheduler] job ${name} failed`, e);
    }
  };
  const after = (name: string, delayMs: number, fn: () => void): void => {
    cancel(name);
    jobs.set(
      name,
      host.set(() => {
        jobs.delete(name);
        run(name, fn);
      }, Math.max(0, delayMs)),
    );
  };
  const every = (name: string, periodMs: number, fn: () => void): void => {
    cancel(name);
    const tick = (): void => {
      jobs.set(name, host.set(tick, periodMs));
      run(name, fn);
    };
    jobs.set(name, host.set(tick, periodMs));
  };
  return {
    every,
    after,
    at: (name, epochMs, fn) => after(name, epochMs - clock.now(), fn),
    cancel,
    has: (name) => jobs.has(name),
    cancelAll: () => [...jobs.keys()].forEach(cancel),
  };
}

/**
 * Midnight job (TMR-ROOM-DAY-ROLLOVER, RLD-MIDNIGHT, DEV-D-43): fires once per day change in clock.zone().
 * Also checks the day key every `checkMs` so a sleeping kiosk or a clock jump still yields exactly one call.
 */
export function startMidnightJob(clock: Clock, scheduler: Scheduler, onDayChanged: (day: string) => void, checkMs = 10_000): () => void {
  let current = dayKey(clock.now(), clock.zone());
  const check = (): void => {
    const d = dayKey(clock.now(), clock.zone());
    if (d !== current) {
      current = d;
      onDayChanged(d);
    }
    armMidnight();
  };
  const armMidnight = (): void => {
    scheduler.at('midnight', addDaysInZone(clock.now(), 1, clock.zone()) + 50, check);
  };
  armMidnight();
  scheduler.every('now-10s', checkMs, check);
  return () => {
    scheduler.cancel('midnight');
    scheduler.cancel('now-10s');
  };
}
