import { createStore, type StoreApi } from 'zustand/vanilla';
import type { AppConfig } from '@/config';
import { err, ok, type AppError, type EventBus, type Result } from '@/kernel';
import { STORAGE_KEYS, type KeyValueStorage } from '@/platform/storage';
import { companyFromOrigin, extractCompanyLabel, resolveApiOrigin } from './api-origin';

export type SessionStatus = 'anonymous' | 'ready';

export interface SessionData {
  status: SessionStatus;
  /** Tenant API origin (STO-API-BASE-DOMAIN). */
  apiOrigin: string | null;
  /** Company sub-domain (tenant label); real-time topic `tenant-<lower-cased>`. */
  subDomain: string | null;
  /** `me.device.id`, set after OP-PROFILE-ME answered (data/queries). */
  deviceId: string | null;
  /** Device access token (STO-TOKEN). Never render or log it. */
  token: string | null;
  /** Incremented on activate / logout (ADR-0004 addendum); every query key starts with ['s', generation]. */
  generation: number;
}

/** Field the activation screen marks; `code` is an i18n key `LOGIN.*`, or `network` / `company-lookup-failed`. */
export interface ActivationError extends AppError {
  field: 'company' | 'pin';
  /** Refusal card key behind a PIN failure (`auth.invalid_credentials`, …, `not-a-device`). */
  refusal?: string;
}

export interface ActivationSuccess {
  apiOrigin: string;
  subDomain: string;
}

export interface SessionActions {
  activate(input: { company: string; pin: string }): Promise<Result<ActivationSuccess, ActivationError>>;
  logout(reason: string): void;
  setDeviceId(deviceId: string | null): void;
  setSubDomain(subDomain: string): void;
}

export type SessionState = SessionData & SessionActions;
export type SessionStore = StoreApi<SessionState>;

/** Port implemented by data/http (`createActivationApi`): the two activation calls. */
export interface ActivationApi {
  companyCard(subDomain: string): Promise<Result<{ blocked: boolean; subDomain: string }, AppError>>;
  pinLogin(apiOrigin: string, pin: string): Promise<Result<{ token: string; refreshToken: string | null }, AppError>>;
}

export interface SessionDeps {
  storage: KeyValueStorage;
  api: ActivationApi;
  config: () => Pick<AppConfig, 'apiOriginTemplate' | 'env'>;
  pageUrl: () => string;
  /** After logout: the app clears the query cache, closes real time and reloads (RLD-LOGOUT). */
  onLoggedOut?: (reason: string) => void;
}

const fail = (field: ActivationError['field'], e: Partial<AppError> & Pick<AppError, 'kind' | 'code'>, refusal?: string): Result<never, ActivationError> =>
  err({ ...e, field, ...(refusal ? { refusal } : {}) });

const NO_ANSWER = new Set<AppError['kind']>(['unreachable', 'timeout', 'outcome-unknown', 'aborted']);

/** JWT payload roles contain ROLE_DEVICE (fe:src/js/services/auth.js:211-214). */
export function isDeviceToken(token: string): boolean {
  try {
    const part = token.split('.')[1] ?? '';
    const json = atob(part.replace(/-/g, '+').replace(/_/g, '/').padEnd(Math.ceil(part.length / 4) * 4, '='));
    const roles = (JSON.parse(json) as { roles?: unknown }).roles;
    return Array.isArray(roles) && roles.includes('ROLE_DEVICE');
  } catch {
    return false;
  }
}

function companyError(e: AppError): Result<never, ActivationError> {
  if (NO_ANSWER.has(e.kind)) return fail('company', { kind: e.kind, code: 'network' }); // DEV-D-14
  if (e.status === 404 || !e.serverText) return fail('company', { kind: 'refused', code: 'LOGIN.TENANT_NOT_FOUND', status: e.status });
  return fail('company', { kind: 'refused', code: 'company-lookup-failed', status: e.status, serverText: e.serverText }); // DEV-D-15
}

function readBoot(storage: KeyValueStorage): SessionData {
  const token = storage.getString(STORAGE_KEYS.token);
  const apiOrigin = storage.getString(STORAGE_KEYS.apiBaseDomain);
  const ready = token !== null && apiOrigin !== null;
  return {
    status: ready ? 'ready' : 'anonymous',
    token: ready ? token : null,
    apiOrigin: ready ? apiOrigin : null,
    subDomain: ready ? companyFromOrigin(apiOrigin) : null,
    deviceId: null,
    generation: 0,
  };
}

export function createSessionStore(deps: SessionDeps): SessionStore {
  const { storage, api } = deps;
  return createStore<SessionState>()((set, get) => ({
    ...readBoot(storage),

    async activate({ company, pin }) {
      const label = extractCompanyLabel(company);
      if (!label) return fail('company', { kind: 'refused', code: 'LOGIN.INCORRECT_DATA_INPUT' });
      const card = await api.companyCard(label);
      if (!card.ok) return companyError(card.error);
      if (card.value.blocked) return fail('company', { kind: 'refused', code: 'LOGIN.COMPANY_BLOCKED' });
      const cfg = deps.config();
      const apiOrigin = resolveApiOrigin({ company: label, template: cfg.apiOriginTemplate, pageUrl: deps.pageUrl(), env: cfg.env });
      const login = await api.pinLogin(apiOrigin, pin);
      if (!login.ok) {
        const e = login.error;
        if (NO_ANSWER.has(e.kind)) return fail('pin', { kind: e.kind, code: 'network' });
        // DEV-D-11, DEV-D-12: every PIN refusal shows one text and never logs out
        return fail('pin', { kind: 'refused', code: 'LOGIN.ACTIVATION_CODE_INVALID', status: e.status, serverText: e.serverText }, e.code);
      }
      if (!isDeviceToken(login.value.token)) {
        return fail('pin', { kind: 'refused', code: 'LOGIN.ACTIVATION_CODE_INVALID' }, 'not-a-device'); // DEV-D-16
      }
      storage.set(STORAGE_KEYS.token, login.value.token);
      storage.set(STORAGE_KEYS.refreshToken, login.value.refreshToken); // DEV-D-19: stored, never used
      storage.set(STORAGE_KEYS.apiBaseDomain, apiOrigin);
      set({ status: 'ready', token: login.value.token, apiOrigin, subDomain: label, deviceId: null, generation: get().generation + 1 });
      return ok({ apiOrigin, subDomain: label });
    },

    logout(reason) {
      if (get().status === 'anonymous' && !storage.has(STORAGE_KEYS.token)) return;
      storage.remove(STORAGE_KEYS.token);
      storage.remove(STORAGE_KEYS.refreshToken);
      storage.remove(STORAGE_KEYS.apiBaseDomain);
      set({ status: 'anonymous', token: null, apiOrigin: null, subDomain: null, deviceId: null, generation: get().generation + 1 });
      deps.onLoggedOut?.(reason);
    },

    setDeviceId(deviceId) {
      if (get().deviceId !== deviceId) set({ deviceId });
    },

    setSubDomain(subDomain) {
      if (get().subDomain !== subDomain) set({ subDomain });
    },
  }));
}

/** session.expired → logout(reason) (DEV-D-21); device.deleted with the own id → logout (DEV-D-22). Returns unsubscribe. */
export function connectSessionEvents(store: SessionStore, events: EventBus): () => void {
  const offs = [
    events.on('session.expired', (e) => store.getState().logout(e.reason)),
    events.on('device.deleted', (e) => {
      const own = store.getState().deviceId;
      if (own !== null && e.deviceId === own) store.getState().logout('device_deleted');
    }),
  ];
  return () => offs.forEach((off) => off());
}
