import { formatInTimeZone, fromZonedTime } from 'date-fns-tz';

/** Port: the only source of "now" (ADR-0004 §5). Zone = room timezone → company default. */
export interface Clock {
  now(): number;
  zone(): string;
  setZone(zone: string): void;
}

export const DEFAULT_ZONE = 'Europe/Moscow';

export function createSystemClock(zone: string = DEFAULT_ZONE): Clock {
  let z = zone;
  return {
    now: () => Date.now(),
    zone: () => z,
    setZone: (next) => {
      z = next;
    },
  };
}

/** Fake clock for tests: time only moves when the test says so. */
export interface FakeClock extends Clock {
  set(ms: number): void;
  advance(ms: number): void;
}

export function createFakeClock(startMs: number, zone: string = DEFAULT_ZONE): FakeClock {
  let t = startMs;
  let z = zone;
  return {
    now: () => t,
    zone: () => z,
    setZone: (next) => {
      z = next;
    },
    set: (ms) => {
      t = ms;
    },
    advance: (ms) => {
      t += ms;
    },
  };
}

/** 'yyyy-MM-dd' of an instant in a zone. */
export function dayKey(ms: number, zone: string): string {
  return formatInTimeZone(ms, zone, 'yyyy-MM-dd');
}

/** Epoch ms of local midnight (start of day) of the day containing `ms` in `zone`. DST-safe. */
export function startOfDayInZone(ms: number, zone: string): number {
  return fromZonedTime(`${dayKey(ms, zone)}T00:00:00`, zone).getTime();
}

/** Epoch ms of local midnight of the day `days` after the day containing `ms` (zone math, not +24 h). */
export function addDaysInZone(ms: number, days: number, zone: string): number {
  // Step the calendar date itself (independent of the host zone), then take local midnight of that date in `zone`.
  const [y, m, d] = dayKey(ms, zone).split('-').map(Number);
  const next = new Date(Date.UTC(y ?? 1970, (m ?? 1) - 1, (d ?? 1) + days)).toISOString().slice(0, 10);
  return fromZonedTime(`${next}T00:00:00`, zone).getTime();
}

/** Epoch ms of a local wall time (hh:mm) on the day of `dayMs` in `zone`. */
export function atLocalTime(dayMs: number, hhmm: string, zone: string): number {
  return fromZonedTime(`${dayKey(dayMs, zone)}T${hhmm.length === 5 ? `${hhmm}:00` : hhmm}`, zone).getTime();
}

export function formatInZone(ms: number, zone: string, pattern: string): string {
  return formatInTimeZone(ms, zone, pattern);
}

/** Minutes since local midnight of `ms` in `zone`. */
export function minutesOfDay(ms: number, zone: string): number {
  const [h, m] = formatInTimeZone(ms, zone, 'HH:mm').split(':').map(Number);
  return (h ?? 0) * 60 + (m ?? 0);
}
