import { useId, useMemo } from 'react';
import { formatTime, getLanguage, useT } from '@/i18n';
import { TimeSelect } from './time-select';
import { endOptions, isSelectorDisabled, rangeAfterStartChange, startOptions, type TimeRange } from './time-options';
import styles from './time-picker.module.css';

export interface TimeRangePickerProps {
  /** Selected range (epoch ms). The start may be off-grid (initial value); it is shown as is. */
  value: TimeRange;
  /** Free windows of today from now (working ranges minus bookings, minute precision) — computed by the caller. */
  freeRanges: readonly TimeRange[];
  /** Every change (start or end); the caller moves the timeline selection with it. */
  onChange: (range: TimeRange) => void;
  /** Display zone (Clock.zone()). */
  zone: string;
  /** Option step, default 15 min (legacy DEFAULT_STEP). */
  stepMinutes?: number;
  /** Room maxBookingDuration in minutes; null/undefined = no cap. */
  maxDurationMinutes?: number | null;
  /** Company timeFormat "12 hour". */
  hour12?: boolean;
  /** Visible label; default t('SPACE.BOOKING_FORM.CHOOSE_TIME'). */
  label?: string;
}

/**
 * Start / end time selection of the room booking form (SCR-ROOM part booking-form, row "time range selector"):
 * two dropdowns separated by ":"; option rules in time-options.ts (legacy un-time-range-selector).
 */
export function TimeRangePicker({ value, freeRanges, onChange, zone, stepMinutes = 15, maxDurationMinutes, hour12 = false, label }: TimeRangePickerProps): JSX.Element {
  const t = useT();
  const labelId = useId();
  const starts = useMemo(() => startOptions(freeRanges, stepMinutes, zone), [freeRanges, stepMinutes, zone]);
  const ends = useMemo(() => endOptions(value.start, freeRanges, stepMinutes, zone, maxDurationMinutes), [value.start, freeRanges, stepMinutes, zone, maxDurationMinutes]);
  const lang = getLanguage();
  const format = (ms: number): string => formatTime(ms, zone, lang, { hour12 });
  return (
    <div role="group" aria-labelledby={labelId} className={styles.group}>
      <span id={labelId} className={styles.label}>
        {label ?? t('SPACE.BOOKING_FORM.CHOOSE_TIME')}
      </span>
      <div className={styles.selectors}>
        <TimeSelect
          value={value.start}
          options={starts}
          format={format}
          ariaLabel={t('APP.TIME_START')}
          disabled={isSelectorDisabled(starts, value.start)}
          onSelect={(start) => onChange(rangeAfterStartChange(start, value.end, freeRanges, stepMinutes, zone, maxDurationMinutes))}
        />
        <span className={styles.separator} aria-hidden="true">
          :
        </span>
        <TimeSelect
          value={value.end}
          options={ends}
          format={format}
          ariaLabel={t('APP.TIME_END')}
          disabled={isSelectorDisabled(ends, value.end)}
          onSelect={(end) => onChange({ start: value.start, end })}
        />
      </div>
    </div>
  );
}
