import { useMemo } from 'react';
import { getConfig, type AppConfig } from '@/config';
import { useCheckInDefaultsQuery, useCompanyCardQuery, useCompanySettingsQuery, useMeQuery, useRoomDetailQuery } from '@/data/queries';
import { effectiveCheckinSettings, type CheckinSettings } from '@/domain/checkin-windows';
import type { DeviceAbilities } from '@/domain/permissions';
import type { StatusRoom } from '@/domain/room-status';
import { resolveWorkingHours, type WorkingHours } from '@/domain/working-hours';
import { useSession } from '@/state/session';
import { qrLinks, type QrLinks } from './qr-links';
import type { BookingPanelRoom } from './types';

/** Everything the room screen reads besides the day's bookings (boot queries, already cached by the boot). */
export interface RoomData {
  room: BookingPanelRoom & { capacity: number | null; privateByDefault: boolean };
  statusRoom: StatusRoom;
  abilities: DeviceAbilities;
  checkin: CheckinSettings;
  hours: WorkingHours;
  hour12: boolean;
  american: boolean;
  logo: string | null;
  backgroundImage: string | null;
  qr: QrLinks | null;
}

function config(): Pick<AppConfig, 'serverHost' | 'mobileRouterSubDomain'> {
  try {
    return getConfig();
  } catch {
    return { serverHost: null, mobileRouterSubDomain: null };
  }
}

/** Assembles RoomData from the queries; null while any required query has no data yet. */
export function useRoomData(zone: string): RoomData | null {
  const me = useMeQuery().data;
  const space = me?.device?.space ?? null;
  const detail = useRoomDetailQuery(space?.id ?? null).data;
  const settings = useCompanySettingsQuery().data;
  const defaults = useCheckInDefaultsQuery().data;
  const card = useCompanyCardQuery().data;
  const sessionSub = useSession((s) => s.subDomain);
  return useMemo(() => {
    if (!me?.device || !space || !detail || !settings || !defaults) return null;
    const room = {
      id: space.id,
      name: space.name || detail.name,
      capacity: space.capacity,
      meetingTitleRequired: detail.meetingTitleRequired,
      defaultBookingDuration: detail.defaultBookingDuration,
      maxBookingDuration: detail.maxBookingDuration,
      privateByDefault: detail.privateByDefault,
    };
    const cfg = config();
    return {
      room,
      statusRoom: { ...room, isShared: detail.isSharedRoom, privacyLevel: detail.privacyLevel },
      abilities: me.device.abilities,
      checkin: effectiveCheckinSettings(space.checkInSettings, defaults),
      hours: resolveWorkingHours(space, settings, zone),
      hour12: settings.timeFormat === '12 hour',
      american: settings.dateFormat === 'american',
      logo: card?.whiteLogo ?? null,
      backgroundImage: me.device.backgroundImage,
      qr: qrLinks({ ...cfg, subDomain: card?.subDomain ?? sessionSub, officeId: space.officeId, roomId: space.id }),
    };
  }, [me, space, detail, settings, defaults, card, sessionSub, zone]);
}
