import { bookAfterRange } from '@/domain/booking-slots';
import { useCancelRoomBookingCommand, useCheckInCommand } from '@/data/commands';
import { useT } from '@/i18n';
import { useClock } from '@/kernel';
import { useUiStore } from '@/state/ui';
import { Button, PlusCircleIcon, TrashIcon } from '@/ui/primitives';
import { toastError } from './errors';
import { confirmCancel, type CancelKind } from './stop-delete-dialog';
import type { PanelProps } from './types';
import styles from './booking-actions.module.css';

/**
 * Body C buttons (SCR-ROOM part booking-info): Confirm (FLOW-DISP-CHECKIN-TAP), Stop / Delete booking with confirmation
 * (FLOW-DISP-STOP, FLOW-DISP-DELETE), Book after (FLOW-DISP-BOOK-AFTER). Gates come from the evaluation, which asks
 * `can()` (PERM-08..16, DEV-D-105, -115, -134). Results are the server outcome applied by the commands (DEV-D-135).
 */
export function BookingButtons({ view, room, bookings, workingRanges }: PanelProps): JSX.Element | null {
  const t = useT();
  const clock = useClock();
  const checkIn = useCheckInCommand();
  const cancel = useCancelRoomBookingCommand();
  const info = view.booking;
  if (!info || (!info.confirm && !info.stop && !info.delete && !info.bookAfter)) return null;
  const b = info.booking;
  const ui = useUiStore.getState;

  const confirm = async (byQr: boolean): Promise<void> => {
    const r = await checkIn.run({ bookingId: b.id, byQr }); // success marks the booking: awaiting ends at once (DEV-D-114)
    if (!r.ok) toastError(r.error, t); // check-in refusals are silent (errorMessages table)
  };
  const stopOrDelete = async (pressed: CancelKind): Promise<void> => {
    if (!(await confirmCancel(b.id, pressed))) return;
    const r = await cancel.run({ bookingId: b.id });
    if (r.ok) {
      if (ui().selectedBookingId === b.id) ui().selectBooking(null);
    } else toastError(r.error, t);
  };
  const bookAfter = (): void => {
    const range = bookAfterRange(b, bookings, workingRanges, clock.now(), room);
    if (range) ui().openForm(range);
  };

  return (
    <div className={styles.row}>
      {info.confirm ? (
        <Button variant="yellow" onClick={() => void confirm(info.confirm!.byQr)}>
          {t('SPACE.BEGIN_MEET')}
        </Button>
      ) : null}
      {info.stop ? (
        <Button variant="warning" blur onClick={() => void stopOrDelete('stop')}>
          {t('SPACE.BOOKING_INFO.STOP')}
        </Button>
      ) : info.delete ? (
        <Button variant="warning" blur icon={<TrashIcon />} onClick={() => void stopOrDelete('delete')}>
          {t('SPACE.BOOKING_INFO.REMOVE')}
        </Button>
      ) : null}
      {info.bookAfter ? (
        <Button variant="success-outline" blur icon={<PlusCircleIcon />} onClick={bookAfter}>
          {t('SPACE.BOOKING_INFO.BOOK_AFTER')}
        </Button>
      ) : null}
    </div>
  );
}
