import type { Booking, DateRange } from '@/domain/booking-model';
import { byStart } from '@/domain/booking-model';

export type Orientation = 'vertical' | 'horizontal';

/** CSS-ready position along the time axis: vertical -> top/height, horizontal -> left/width (percent of the range). */
export type AxisStyle = { top: string; height: string } | { left: string; width: string };

/** A positioned piece of the range (minutes and percent from the range start). */
export interface Positioned {
  start: number;
  end: number;
  offsetMin: number;
  sizeMin: number;
  offsetPct: number;
  sizePct: number;
  style: AxisStyle;
}

export interface TimelineBlock extends Positioned {
  id: string;
  /** The input booking, untouched (DEV-D-53): status and free time use its real end. */
  booking: Booking;
  /** Square leading / trailing edge: the booking starts before / ends after the range (TOK-TIMELINE-BLOCK). */
  startsBefore: boolean;
  endsAfter: boolean;
  /** Title lines that fit: main when the visible block is >= 30 min, secondary when >= 60 min. */
  mainTitle: boolean;
  secondaryTitle: boolean;
  isSelected: boolean;
}

export interface BlockedArea extends Positioned {
  /** White 2 px edge where the shaded area starts / ends inside the view (TOK-OVERLAY-BLOCKED). */
  startEdge: boolean;
  endEdge: boolean;
}

const MIN = 60_000;
const round = (n: number) => Math.round(n * 1e6) / 1e6;

function axisStyle(offsetPct: number, sizePct: number, orientation: Orientation): AxisStyle {
  return orientation === 'vertical'
    ? { top: `${offsetPct}%`, height: `${sizePct}%` }
    : { left: `${offsetPct}%`, width: `${sizePct}%` };
}

/** Clip `piece` to `range` and position it; null when nothing of it is inside. Never mutates the input. */
export function layoutRange(piece: DateRange, range: DateRange, orientation: Orientation): Positioned | null {
  const start = Math.max(piece.start, range.start);
  const end = Math.min(piece.end, range.end);
  if (end <= start) return null;
  const total = range.end - range.start;
  const offsetPct = round(((start - range.start) / total) * 100);
  const sizePct = round(((end - start) / total) * 100);
  return {
    start,
    end,
    offsetMin: round((start - range.start) / MIN),
    sizeMin: round((end - start) / MIN),
    offsetPct,
    sizePct,
    style: axisStyle(offsetPct, sizePct, orientation),
  };
}

/**
 * SCR-ROOM timeline.booking-block (fe timeline-booking.component.ts:44-130): one block per booking overlapping the
 * range, clipped to it (DEV-D-53 CHANGE: the booking is never changed), ordered by start. Overlapping bookings are not
 * split into lanes: as in legacy, later blocks paint over earlier ones.
 */
export function layoutBlocks(
  bookings: readonly Booking[],
  range: DateRange,
  orientation: Orientation,
  selectedId: string | null = null,
): TimelineBlock[] {
  return [...bookings].sort(byStart).flatMap((booking) => {
    const pos = layoutRange(booking, range, orientation);
    if (!pos) return [];
    return [
      {
        ...pos,
        id: booking.id,
        booking,
        startsBefore: booking.start < range.start,
        endsAfter: booking.end > range.end,
        mainTitle: pos.sizeMin >= 30,
        secondaryTitle: pos.sizeMin >= 60,
        isSelected: booking.id === selectedId,
      },
    ];
  });
}

/**
 * SCR-ROOM timeline.blocked-area (fe timeline-blocked-area.component.ts:46-65): the range minus the working ranges
 * that end after `now`, each with its start moved to `now` — i.e. past time and non-working time are shaded.
 */
export function blockedAreas(range: DateRange, workingRanges: readonly DateRange[], now: number, orientation: Orientation): BlockedArea[] {
  const open = workingRanges
    .filter((r) => r.end > now)
    .map((r) => ({ start: Math.max(r.start, now), end: r.end }))
    .sort((a, b) => a.start - b.start);
  const areas: DateRange[] = [];
  let cursor = range.start;
  for (const r of open) {
    if (r.start > cursor) areas.push({ start: cursor, end: Math.min(r.start, range.end) });
    cursor = Math.max(cursor, r.end);
  }
  if (cursor < range.end) areas.push({ start: cursor, end: range.end });
  return areas.flatMap((a) => {
    const pos = layoutRange(a, range, orientation);
    return pos ? [{ ...pos, startEdge: pos.start > now && pos.start > range.start, endEdge: pos.end < range.end }] : [];
  });
}

/** Instant at `fraction` (0..1) of the range — converts a tap offset to a time for booking-slots `slotFromTap`. */
export function timeAt(range: DateRange, fraction: number): number {
  return Math.round(range.start + Math.min(Math.max(fraction, 0), 1) * (range.end - range.start));
}

/** Position of `now` in percent of the range, clamped to 0..100 (scroll to now). */
export function nowOffsetPct(range: DateRange, now: number): number {
  const pct = ((now - range.start) / (range.end - range.start)) * 100;
  return round(Math.min(Math.max(pct, 0), 100));
}
