/**
 * Legacy `{value, type}` wrapper (STO-* value_format, DT-STO-1…5, DEV-D-18). Writing the same bytes as the legacy
 * storage service keeps rollback to the legacy build possible (ADR-0005).
 */
export type StoredValue = string | number | boolean | null | object;

export function encodeLegacy(value: StoredValue | undefined): string {
  if (value === undefined || value === null) return JSON.stringify({ value: 'null', type: 'null' });
  if (typeof value === 'boolean') return JSON.stringify({ value: value.toString(), type: 'boolean' });
  if (typeof value === 'string') return JSON.stringify({ value, type: 'string' });
  if (typeof value === 'number') return JSON.stringify({ value: value.toString(), type: 'number' });
  return JSON.stringify({ value: JSON.stringify(value), type: 'object' });
}

export type Decoded = { ok: true; value: StoredValue } | { ok: false };

const DECODERS: Record<string, (v: unknown) => StoredValue> = {
  null: () => null,
  boolean: (v) => String(v).toLowerCase() === 'true',
  string: (v) => v as string,
  number: (v) => {
    const n = Number(v);
    return Number.isNaN(n) ? 0 : n;
  },
  object: (v) => JSON.parse(String(v)) as object,
};

/** Reads one raw item as legacy does; `ok: false` where legacy throws (DT-STO-4). */
export function decodeLegacy(raw: string): Decoded {
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return { ok: true, value: raw }; // DT-STO-3: written by an older version, use as is
  }
  if (typeof parsed === 'boolean') return { ok: true, value: parsed }; // DT-STO-2
  if (parsed === null || typeof parsed !== 'object') return { ok: false };
  const { type, value } = parsed as { type?: unknown; value?: unknown };
  const decode = typeof type === 'string' ? DECODERS[type] : undefined;
  if (!decode) return { ok: false };
  try {
    return { ok: true, value: decode(value) };
  } catch {
    return { ok: false };
  }
}
