import QRCode from 'qrcode-svg';

/** White border in modules (qrcode-svg default padding 4, as legacy). */
export const QR_PADDING = 4;

export interface QrMatrix {
  /** Modules per side, without padding. */
  size: number;
  /** SVG path data of the dark modules in module units, offset by the padding (one subpath per module). */
  path: string;
}

/**
 * Same generator as legacy (`new QRCode({content, width: 360, height: 360, join: true, …})`, ecl M default,
 * fe:…/space-view.component.ts:595); returns the module matrix as path data so React renders it without HTML injection.
 */
export function qrMatrix(value: string): QrMatrix {
  const qr = new QRCode({ content: value, padding: QR_PADDING, join: true, ecl: 'M' });
  const modules = (qr.qrcode as unknown as { modules: boolean[][] }).modules;
  const parts: string[] = [];
  // Legacy draws modules[x][y] at (x, y) (qrcode-svg svg(): first index = horizontal), i.e. the transposed matrix;
  // kept for pixel parity with the legacy QR (readers accept both).
  modules.forEach((column, x) => {
    column.forEach((dark, y) => {
      if (dark) parts.push(`M${x + QR_PADDING},${y + QR_PADDING}h1v1h-1z`);
    });
  });
  return { size: modules.length, path: parts.join('') };
}
