import { forwardRef, type ButtonHTMLAttributes, type ReactNode } from 'react';
import styles from './button.module.css';

/**
 * Legacy room-screen button variants (fe:src/scss/global/_buttons.scss):
 * success-outline (Book after, quick buttons on a fixed green), success (Book now), accent-outline (quick buttons
 * 15/30/60 in the status accent), secondary-outline (Cancel, Close), white-outline (Another), warning (Stop/Delete),
 * yellow (check-in Confirm).
 */
export type ButtonVariant = 'success-outline' | 'success' | 'accent-outline' | 'secondary-outline' | 'white-outline' | 'warning' | 'yellow';

export interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: ButtonVariant;
  /** Icon before the label (24×24, 24 px gap); decorative — the label names the button. */
  icon?: ReactNode;
  /** backdrop-filter blur(8px) (TOK-BLUR: quick buttons, info-panel buttons). */
  blur?: boolean;
  fullWidth?: boolean;
}

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(function Button(
  { variant = 'secondary-outline', icon, blur = false, fullWidth = false, className, type = 'button', children, ...rest },
  ref,
) {
  const cls = [styles.button, styles[variant], blur && styles.blur, fullWidth && styles.fullWidth, className].filter(Boolean).join(' ');
  return (
    <button ref={ref} type={type} className={cls} data-variant={variant} {...rest}>
      {icon ? (
        <span className={styles.icon} aria-hidden="true">
          {icon}
        </span>
      ) : null}
      {children}
    </button>
  );
});
