/**
 * The ONE place that reloads the page (RLD-LOGIN, RLD-LOGOUT, RLD-DEVICE-RELOAD, RLD-WD-HARD, RLD-BOOT-RECOVERY,
 * RLD-SW-UPDATE, DEV-D-2 back-off). Everything else receives `reloadPage` as a dependency; tests swap the
 * implementation with `setReloadForTests`.
 */
export type ReloadReason =
  | 'login'
  | 'logout'
  | 'device_reload'
  | 'watchdog_hard'
  | 'sw_update'
  | 'boot_recovery'
  | 'boot_backoff'
  | (string & Record<never, never>);

export interface ReloadOptions {
  /** location.replace(url) instead of location.reload() (boot recovery adds `?__bootstrap_recovery=<ms>`). */
  replaceUrl?: string;
}

type ReloadImpl = (reason: ReloadReason, options?: ReloadOptions) => void;

const browserReload: ReloadImpl = (_reason, options) => {
  if (options?.replaceUrl) window.location.replace(options.replaceUrl);
  else window.location.reload();
};

let impl: ReloadImpl = browserReload;

export function reloadPage(reason: ReloadReason, options?: ReloadOptions): void {
  impl(reason, options);
}

/** Test seam: replace the browser reload; returns restore(). */
export function setReloadForTests(fake: ReloadImpl): () => void {
  impl = fake;
  return () => {
    impl = browserReload;
  };
}
