import { useT } from '@/i18n';
import { Spinner } from '@/ui/primitives';
import styles from './offline-overlay.module.css';

/**
 * SCR-OFFLINE-OVERLAY (CONN-OVERLAY, DEV-D-6): replaces the working screen while the connection state is offline or
 * reconnecting. ST-OFFLINE: title + APP.OFFLINE_SUBTITLE; ST-RECONNECTING: title + APP.OFFLINE_RECONNECTING + spinner.
 */
export function OfflineOverlay({ state }: { state: 'offline' | 'reconnecting' }): JSX.Element {
  const t = useT();
  return (
    <div className={styles.overlay} role="alert" data-testid="offline-overlay" data-state={state}>
      <div className={styles.content}>
        <h2 className={styles.title}>{t('APP.OFFLINE_TITLE')}</h2>
        {state === 'reconnecting' ? (
          <>
            <p className={styles.subtitle}>{t('APP.OFFLINE_RECONNECTING')}</p>
            <Spinner />
          </>
        ) : (
          <p className={styles.subtitle}>{t('APP.OFFLINE_SUBTITLE')}</p>
        )}
      </div>
    </div>
  );
}
