import type { Booking, CheckInMarks, DateRange } from '@/domain/booking-model';
import { byStart } from '@/domain/booking-model';

export type CheckinMode = 'remote' | 'strict';

/** Effective check-in settings of the room (RULE-CHECKIN-FIELDS); minutes, nullable. */
export interface CheckinSettings {
  remoteBefore: number | null;
  remoteAfter: number | null;
  remoteEnabled: boolean;
  strictBefore: number | null;
  strictAfter: number | null;
  strictEnabled: boolean;
}

/** Room-level settings (`me.device.space.checkInSettings`). */
export interface RoomCheckinSettings extends CheckinSettings {
  isUseDefaultCheckInSettings: boolean;
}

/** A booking the display offers to confirm (RULE-CHECKIN-ELIGIBLE). `until` = window end; `byQr` = strict (DEV-D-55). */
export interface AwaitingCheckin {
  booking: Booking;
  mode: CheckinMode;
  until: number;
  byQr: boolean;
}

export interface AwaitingCheckinInput {
  bookings: readonly Booking[];
  /** The selected booking read from the current list by id (DEV-D-118), or null. */
  selected: Booking | null;
  /** The booking with start <= now < end, or null. */
  current: Booking | null;
  settings: CheckinSettings;
  now: number;
}

/** Mark codes (Booking.checkIn.*By): 10 = user/display confirm, 20 = automatic. */
export const USER_CHECKIN = '10';
export const AUTO_CHECKIN = '20';
export const CHECKIN_MODES: readonly CheckinMode[] = ['remote', 'strict'];

export const CHECKIN_OFF: CheckinSettings = {
  remoteBefore: null,
  remoteAfter: null,
  remoteEnabled: false,
  strictBefore: null,
  strictAfter: null,
  strictEnabled: false,
};

const MIN = 60_000;

/** RULE-CHECKIN-SOURCE: room settings unless isUseDefaultCheckInSettings, then the company default ROOM settings. */
export function effectiveCheckinSettings(room: RoomCheckinSettings | null, companyDefaults: CheckinSettings | null): CheckinSettings {
  if (room && !room.isUseDefaultCheckInSettings) return pick(room);
  return companyDefaults ? pick(companyDefaults) : CHECKIN_OFF;
}

function pick(s: CheckinSettings): CheckinSettings {
  const { remoteBefore, remoteAfter, remoteEnabled, strictBefore, strictAfter, strictEnabled } = s;
  return { remoteBefore, remoteAfter, remoteEnabled, strictBefore, strictAfter, strictEnabled };
}

export function isModeEnabled(settings: CheckinSettings, mode: CheckinMode): boolean {
  return mode === 'remote' ? settings.remoteEnabled : settings.strictEnabled;
}

/** RULE-CHECKIN-WINDOW-CLIENT: [start - before, min(start + after, end)); null before/after count as 0; null when the mode is off. */
export function checkinWindow(booking: DateRange, mode: CheckinMode, settings: CheckinSettings): DateRange | null {
  if (!isModeEnabled(settings, mode)) return null;
  const before = (mode === 'remote' ? settings.remoteBefore : settings.strictBefore) ?? 0;
  const after = (mode === 'remote' ? settings.remoteAfter : settings.strictAfter) ?? 0;
  return { start: booking.start - before * MIN, end: Math.min(booking.start + after * MIN, booking.end) };
}

/** RULE-CHECKIN-MARK-SEMANTICS: the booking carries the mark of `mode` (code or timestamp). */
export function hasMark(booking: Booking, mode: CheckinMode): boolean {
  const c = booking.checkIn;
  return mode === 'remote' ? c.remoteBy !== null || c.remoteAt !== null : c.strictBy !== null || c.strictAt !== null;
}

/** Open window of an unmarked, enabled mode, or null (RULE-CHECKIN-ELIGIBLE without the blocking rules). */
function openWindow(booking: Booking, mode: CheckinMode, settings: CheckinSettings, now: number): DateRange | null {
  if (hasMark(booking, mode)) return null;
  const w = checkinWindow(booking, mode, settings);
  return w && w.start <= now && now < w.end ? w : null;
}

function awaiting(booking: Booking, mode: CheckinMode, window: DateRange): AwaitingCheckin {
  return { booking, mode, until: window.end, byQr: mode === 'strict' };
}

/**
 * The booking awaiting check-in and its mode (RULE-STATUS-NEAREST, RULE-CHECKIN-ELIGIBLE, -BLOCKED-BY-CURRENT,
 * -NEAREST-ONLY (DEV-D-113 KEEP), -TWO-STEP). With a selection only the selected booking is tested, each mode against
 * its own mark (DEV-D-111). Remote is tested before strict.
 */
export function awaitingCheckin(input: AwaitingCheckinInput): AwaitingCheckin | null {
  const { bookings, selected, current, settings, now } = input;
  for (const mode of CHECKIN_MODES) {
    if (!isModeEnabled(settings, mode)) continue;
    if (selected) {
      const w = openWindow(selected, mode, settings, now);
      if (w) return awaiting(selected, mode, w);
      continue;
    }
    if (current && hasMark(current, mode)) continue;
    const nearest = bookings.filter((b) => b.end > now && !hasMark(b, mode)).sort(byStart)[0];
    const w = nearest ? openWindow(nearest, mode, settings, now) : null;
    if (nearest && w) return awaiting(nearest, mode, w);
  }
  return null;
}

/**
 * Mode a Confirm of `booking` confirms at `now` (DEV-D-55): remote when its remote window is open and unmarked,
 * else strict when the strict one is; null when neither. `byQr = mode === 'strict'`.
 */
export function checkinMode(booking: Booking, settings: CheckinSettings, now: number): CheckinMode | null {
  return CHECKIN_MODES.find((m) => openWindow(booking, m, settings, now) !== null) ?? null;
}

/**
 * Local marks of a booking just created by the display (RULE-CHECKIN-AUTO-LOCAL, DEV-D-116 CHANGE = server rule
 * RULE-CHECKIN-AUTO-SERVER): remote 20 when enabled and now >= start - remoteBefore; else strict 20 likewise.
 */
export function autoCheckinMarks(start: number, now: number, settings: CheckinSettings): CheckInMarks {
  const marks: CheckInMarks = { remoteBy: null, remoteAt: null, strictBy: null, strictAt: null };
  const opened = (before: number | null) => now >= start - (before ?? 0) * MIN;
  if (settings.remoteEnabled && opened(settings.remoteBefore)) return { ...marks, remoteBy: AUTO_CHECKIN, remoteAt: now };
  if (settings.strictEnabled && opened(settings.strictBefore)) return { ...marks, strictBy: AUTO_CHECKIN, strictAt: now };
  return marks;
}

/** Marks after a successful Confirm of `mode` (RULE-CHECKIN-REQUEST, DEV-D-114: awaiting ends at once). */
export function confirmedMarks(marks: CheckInMarks, mode: CheckinMode, now: number): CheckInMarks {
  return mode === 'remote' ? { ...marks, remoteBy: USER_CHECKIN, remoteAt: now } : { ...marks, strictBy: USER_CHECKIN, strictAt: now };
}
