import { useEffect, useState, type ReactNode } from 'react';
import { useClock, useScheduler } from '@/kernel';
import { formatDate, formatTime, getLanguage } from '@/i18n';
import { ASSETS } from '@/ui/theme';
import styles from './room-display.module.css';

/** A named periodic job of this screen (ARCHITECTURE §3: `clock-1s`, `status-5s`), released on unmount (DEV-D-44). */
export function useJobTick(name: string, periodMs: number): number {
  const scheduler = useScheduler();
  const [n, setN] = useState(0);
  useEffect(() => {
    scheduler.every(name, periodMs, () => setN((x) => x + 1));
    return () => scheduler.cancel(name);
  }, [scheduler, name, periodMs]);
  return n;
}

/** SCR-ROOM header.clock: current time on first paint (DEV-D-45), then every second (TMR-ROOM-CLOCK, job `clock-1s`). */
function HeaderClock({ zone, hour12 }: { zone: string; hour12: boolean }): JSX.Element {
  const clock = useClock();
  useJobTick('clock-1s', 1000);
  return (
    <div className={styles.time} data-testid="room.clock">
      {formatTime(clock.now(), zone, getLanguage(), { hour12 })}
    </div>
  );
}

export interface HeaderProps {
  logo: string | null;
  /** Evaluation instant (date of the shown day). */
  now: number;
  zone: string;
  hour12: boolean;
  american: boolean;
  /** Router-supplied menu control; shown only when `showMenu` (PERM-21, not a shared room). */
  menuSlot?: ReactNode;
  showMenu: boolean;
}

/** SCR-ROOM header: logo, clock, date, menu slot. */
export function Header({ logo, now, zone, hour12, american, menuSlot, showMenu }: HeaderProps): JSX.Element {
  return (
    <div className={styles.header}>
      <img className={styles.logo} src={logo ?? ASSETS.logo} alt="" />
      <HeaderClock zone={zone} hour12={hour12} />
      <div className={styles.date}>{formatDate(now, zone, getLanguage(), { american })}</div>
      {showMenu ? menuSlot : null}
    </div>
  );
}
