import type { Booking, DateRange } from '@/domain/booking-model';
import type { AwaitingCheckin } from '@/domain/checkin-windows';
import { bookAfterAvailable, formLimits, freeSlots, freeTime, quickOptions } from '@/domain/booking-slots';
import { can, type PermissionContext } from '@/domain/permissions';
import type { BookingBodyView, BookingLine, FormBodyView, FreeBodyView, QrCaption, RoomStatusInput } from './types';

export interface BodyContext {
  input: RoomStatusInput;
  bookings: readonly Booking[];
  current: Booking | null;
  awaiting: AwaitingCheckin | null;
  isWorkingTime: boolean;
}

function permissionContext(ctx: BodyContext, booking: Booking | null): PermissionContext {
  const { abilities, room, now } = ctx.input;
  return { abilities, room: { isShared: room.isShared, privacyLevel: room.privacyLevel }, booking, now };
}

function qrCaption(c: PermissionContext): QrCaption {
  return `BOOK_${c.abilities.abilityToBook ? 'ON' : 'OFF'}_CHECKIN_${c.abilities.abilityToCheckin ? 'ON' : 'OFF'}`;
}

/**
 * Body A (DT-STATUS-06, 26-32). Outside working hours there is no free text and no quick block (DT-STATUS-06; the
 * stale values of DT-STATUS-07 are not reproduced, DEV-D-46).
 */
export function freeBody(ctx: BodyContext): FreeBodyView {
  const { input, bookings, isWorkingTime } = ctx;
  const pc = permissionContext(ctx, null);
  const freeFor = isWorkingTime ? freeTime(bookings, input.workingRanges, input.now) : null;
  const quick = isWorkingTime
    ? quickOptions({
        freeMinutes: freeFor?.minutes ?? 0,
        limits: input.room,
        canQuickBook: can('quick-book', pc),
        titleRequired: input.room.meetingTitleRequired,
        inFlight: input.quickBookingInFlight ?? false,
      })
    : null;
  return { freeFor, quick, roomQr: can('room-qr', pc) ? { caption: qrCaption(pc) } : null };
}

function bookingLine(b: Booking, isCurrent: boolean, awaiting: AwaitingCheckin | null): BookingLine {
  if (awaiting) return { kind: 'confirm-until', until: awaiting.until };
  if (isCurrent) return { kind: 'locked-until', end: b.end };
  return { kind: 'booked-from-to', start: b.start, end: b.end };
}

/** Body C (SCR-ROOM part booking-info) for the shown booking; buttons per permissions PERM-08..17 and DEV-D-105, -115, -134. */
export function bookingBody(ctx: BodyContext, b: Booking): BookingBodyView {
  const { input, bookings } = ctx;
  const pc = permissionContext(ctx, b);
  const isCurrent = b.start <= input.now && input.now < b.end;
  const awaiting = ctx.awaiting?.booking.id === b.id ? ctx.awaiting : null;
  return {
    booking: b,
    isCurrent,
    isAwaitingCheckin: awaiting !== null,
    nameInAccent: isCurrent || awaiting !== null,
    line: bookingLine(b, isCurrent, awaiting),
    showTitle: can('see-title', pc),
    showOrganizer: can('see-organizer', pc),
    confirm: awaiting && can('check-in', pc) ? { mode: awaiting.mode, byQr: awaiting.byQr } : null,
    stop: can('stop', pc),
    delete: can('delete', pc),
    bookAfter: can('book-after', pc) && !awaiting && bookAfterAvailable(b, bookings, input.workingRanges, input.now),
    checkinQr: can('checkin-qr', pc),
  };
}

/** Body B: the form's range with the free ranges and selector options. */
export function formBody(ctx: BodyContext, range: DateRange): FormBodyView {
  const freeRanges = freeSlots(ctx.bookings, ctx.input.workingRanges, ctx.input.now);
  return { range, freeRanges, limits: formLimits(range.start, freeRanges, ctx.input.room) };
}
