import type { Scheduler } from '@/kernel';

/** Room status as the LED sees it (product/contract/led.yaml `colours.map`; same values as the room screen status). */
export type LedStatus = 'FREE' | 'OCCUPIED' | 'CHECKIN' | 'BOOKING_SELECTED';
export type LedDriverKind = 'qbic' | 'crestron' | 'none';

/** Port (T28). `setStatus` never throws and never rejects: LED errors are swallowed (OP-LED-QBIC failures, DEV-D-92). */
export interface LedDriver {
  readonly kind: LedDriverKind;
  setStatus(status: LedStatus): Promise<void>;
}

export interface Rgba {
  red: number;
  green: number;
  blue: number;
  alpha: 1;
}

/** led.yaml colours.map: Qbic body per status (hex #008000, #FF0000, #ffff00, #0000FF). */
export const QBIC_COLOURS: Readonly<Record<LedStatus, Rgba>> = {
  FREE: { red: 0, green: 128, blue: 0, alpha: 1 },
  OCCUPIED: { red: 255, green: 0, blue: 0, alpha: 1 },
  CHECKIN: { red: 255, green: 255, blue: 0, alpha: 1 },
  BOOKING_SELECTED: { red: 0, green: 0, blue: 255, alpha: 1 },
};

export type CrestronSignal = 'USB_RED_LED_CONTROL' | 'USB_GREEN_LED_CONTROL' | 'USB_BLUE_LED_CONTROL';

/** led.yaml colours.map: Crestron R/G/B booleans per status. */
export const CRESTRON_SIGNALS: Readonly<Record<LedStatus, readonly [boolean, boolean, boolean]>> = {
  FREE: [false, true, false],
  OCCUPIED: [true, false, false],
  CHECKIN: [true, true, false],
  BOOKING_SELECTED: [false, false, true],
};

export const QBIC_ORIGIN = 'http://localhost:8080';
/** DEV-D-108: probe timeout (port default 2 s), then the no-op driver. */
export const QBIC_PROBE_TIMEOUT_MS = 2000;

export type LedFetch = (url: string, init: { method: 'GET' | 'POST'; headers?: Record<string, string>; body?: string; signal?: AbortSignal }) => Promise<{ ok: boolean }>;

export interface CrestronGlobal {
  sendBooleanSignal(signal: CrestronSignal, value: boolean): void;
}

export interface LedDeps {
  scheduler: Scheduler;
  /** Plain fetch, never data/http: the LED calls carry no token (DEV-D-89). Default: global fetch. */
  fetchFn?: LedFetch;
  /** Where the panel injects `Crestron` (default globalThis). */
  host?: { Crestron?: unknown };
  /** Optional error sink (telemetry); errors are swallowed either way. */
  onError?: (error: unknown) => void;
  probeTimeoutMs?: number;
}

export const noopLedDriver: LedDriver = { kind: 'none', setStatus: () => Promise.resolve() };
