import { useEffect } from 'react';
import { useKernel, type EventBus, type Scheduler } from '@/kernel';
import { useUiStore } from './ui-store';

/** TMR-ROOM-IDLE-DESELECT, TMR-ROOM-FORM-IDLE, TMR-APP-IDLE-HOME (DEV-D-7). */
export const IDLE_DESELECT_MS = 30_000;
export const FORM_IDLE_MS = 60_000;
export const IDLE_HOME_MS = 90_000;

/** Input that counts as user activity (DEV-D-7: real input only; programmatic scrolls never re-arm). */
const ACTIVITY_EVENTS = ['pointerdown', 'keydown', 'wheel'] as const;

export interface IdleJobsDeps {
  scheduler: Scheduler;
  events: EventBus;
  /** Where input is listened for; default `window`. */
  target?: Pick<EventTarget, 'addEventListener' | 'removeEventListener'>;
}

let arm: (() => void) | null = null;

/** Re-arm the idle jobs (real input). No-op until `startIdleJobs` ran. */
export function markUserActivity(): void {
  arm?.();
}

/**
 * Starts the three idle jobs and listens for input (capture phase, anywhere). Returns stop().
 * - `idle-30s`: deselect the booking and ask the timeline to scroll to now; repeats every 30 s while idle (legacy
 *   repeats on every tick while idle).
 * - `form-idle-60s`: close the booking form.
 * - `idle-90s`: emit AppEvent `idle.timeout` once per idle period (router → room screen, DialogHost → closeAll) and
 *   clear selection and form.
 */
export function startIdleJobs(deps: IdleJobsDeps): () => void {
  const { scheduler, events } = deps;
  const target = deps.target ?? window;
  const deselect = (): void => {
    const s = useUiStore.getState();
    s.selectBooking(null);
    s.requestScrollToNow();
    scheduler.after('idle-30s', IDLE_DESELECT_MS, deselect);
  };
  const rearm = (): void => {
    scheduler.after('idle-30s', IDLE_DESELECT_MS, deselect);
    scheduler.after('form-idle-60s', FORM_IDLE_MS, () => useUiStore.getState().closeForm());
    scheduler.after('idle-90s', IDLE_HOME_MS, () => {
      useUiStore.getState().resetSelection();
      events.emit({ type: 'idle.timeout' });
    });
  };
  const onInput = (): void => rearm();
  ACTIVITY_EVENTS.forEach((e) => target.addEventListener(e, onInput, true));
  arm = rearm;
  rearm();
  return () => {
    ACTIVITY_EVENTS.forEach((e) => target.removeEventListener(e, onInput, true));
    ['idle-30s', 'form-idle-60s', 'idle-90s'].forEach((n) => scheduler.cancel(n));
    if (arm === rearm) arm = null;
  };
}

/** Headless: mount ONCE in the app shell inside KernelProvider (all screens, DEV-D-7). */
export function UiIdleWatcher(): null {
  const { scheduler, events } = useKernel();
  useEffect(() => startIdleJobs({ scheduler, events }), [scheduler, events]);
  return null;
}
