import { forwardRef, useImperativeHandle, useMemo, useRef, type MouseEvent } from 'react';
import type { Booking, DateRange } from '@/domain/booking-model';
import { blockedAreas, layoutBlocks, layoutRange, type TimelineBlock } from '@/domain/timeline-layout';
import { formatTime } from '@/i18n';
import { hourLabels, instantAt, px, rangeMinutes } from './hours';
import { BlockedOverlay, BookingBlock, HourRows, SelectedRange, cx, type BlockTitleTexts } from './timeline-parts';
import styles from './timeline.module.css';

export interface TimelineProps {
  /** The shown day [local midnight, next midnight) (working-hours `dayRange`). */
  range: DateRange;
  /** Evaluation instant: shading of past time (recompute at least every 10 s). */
  now: number;
  zone: string;
  bookings: readonly Booking[];
  /** Today's working ranges: time outside them is shaded. */
  workingRanges: readonly DateRange[];
  selectedBookingId?: string | null;
  /** Range of the open form: white outline. */
  selectedRange?: DateRange | null;
  /** Company "12 hour" format: labels "hh am", wider label column. */
  hour12?: boolean;
  /** Title texts per booking (privacy already applied); visibility by block length is decided here. */
  titlesOf?: (booking: Booking) => BlockTitleTexts;
  /** Tap on a free hour row → the tapped instant (minute). Omit for read-only (taps ignored). */
  onSlotTap?: (at: number) => void;
  /** Tap on a booking block. Omit when blocks cannot be selected (shared room). */
  onBookingTap?: (booking: Booking) => void;
  orientation?: 'vertical';
  className?: string;
}

export interface TimelineHandle {
  /** Scroll so that now is at the top of the visible area (legacy scrollToCurrentTime). */
  scrollToNow(): void;
}

const NO_TITLES = (): BlockTitleTexts => ({ main: null, secondary: null });
const MIN = 60_000;

/**
 * Vertical day timeline of the room screen (SCR-ROOM region timeline, TOK-TIMELINE): hour rows, booking blocks,
 * shaded past / non-working time (its edge at now is the now line), the form range outline. Positions come from
 * domain/timeline-layout; 100 px per hour.
 */
export const Timeline = forwardRef<TimelineHandle, TimelineProps>(function Timeline(props, ref) {
  const { range, now, zone, bookings, workingRanges, selectedBookingId = null, selectedRange = null, hour12 = false } = props;
  const { titlesOf = NO_TITLES, onSlotTap, onBookingTap, className } = props;
  const rootRef = useRef<HTMLDivElement>(null);
  const innerRef = useRef<HTMLDivElement>(null);
  const labels = useMemo(() => hourLabels(range, zone, hour12), [range, zone, hour12]);
  const blocks = useMemo(() => layoutBlocks(bookings, range, 'vertical', selectedBookingId), [bookings, range, selectedBookingId]);
  const minuteNow = Math.floor(now / MIN) * MIN;
  const shaded = useMemo(() => blockedAreas(range, workingRanges, minuteNow, 'vertical'), [range, workingRanges, minuteNow]);
  const outline = selectedRange ? layoutRange(selectedRange, range, 'vertical') : null;

  useImperativeHandle(
    ref,
    () => ({
      scrollToNow: () => {
        const el = rootRef.current;
        if (el) el.scrollTop = px(Math.max(0, Math.min(now, range.end) - range.start) / MIN);
      },
    }),
    [now, range],
  );

  const onRowsClick = (e: MouseEvent<HTMLDivElement>): void => {
    if (!onSlotTap || !innerRef.current) return;
    const y = e.clientY - innerRef.current.getBoundingClientRect().top;
    if (y < 0 || y >= px(rangeMinutes(range))) return; // the last label row is not a slot
    onSlotTap(instantAt(range, y));
  };
  const time = (b: TimelineBlock): string => `${formatTime(b.booking.start, zone, undefined, { hour12 })} – ${formatTime(b.booking.end, zone, undefined, { hour12 })}`;

  return (
    <div ref={rootRef} className={cx(styles.root, className)} data-testid="timeline">
      <div ref={innerRef} className={cx(styles.inner, hour12 && styles.hour12)} style={{ height: `${px(rangeMinutes(range))}px` }} onClick={onRowsClick}>
        <HourRows labels={labels} />
        <div className={styles.bookings}>
          {blocks.map((b) => (
            <BookingBlock key={b.id} block={b} titles={titlesOf(b.booking)} timeLabel={time(b)} onTap={onBookingTap ? () => onBookingTap(b.booking) : undefined} />
          ))}
          {outline ? <SelectedRange piece={outline} /> : null}
        </div>
        {shaded.map((a) => (
          <BlockedOverlay key={`${a.start}-${a.end}`} area={a} />
        ))}
      </div>
    </div>
  );
});
