import { minutesOfDay } from '@/kernel';

/** Epoch-ms range [start, end). */
export interface TimeRange {
  start: number;
  end: number;
}

const MIN = 60_000;
const floorMinute = (ms: number): number => Math.floor(ms / MIN) * MIN;

/** Next `step` mark at or after `ms` in `zone` (legacy ceilMoment on minutes; seconds dropped — minute precision). */
export function ceilToStep(ms: number, stepMinutes: number, zone: string): number {
  const t = floorMinute(ms);
  const m = minutesOfDay(t, zone);
  return t + (Math.ceil(m / stepMinutes) * stepMinutes - m) * MIN;
}

function grid(from: number, to: number, stepMinutes: number, zone: string): number[] {
  const out: number[] = [];
  for (let t = ceilToStep(from, stepMinutes, zone); t <= to; t += stepMinutes * MIN) out.push(t);
  return out;
}

/**
 * Start options: step marks inside every free range from its start up to its end − 1 min, ranges sorted
 * (un-time-range-selector generateStartRanges + un-time-selector generateDropdownValues).
 */
export function startOptions(freeRanges: readonly TimeRange[], stepMinutes: number, zone: string): number[] {
  return [...freeRanges].sort((a, b) => a.start - b.start).flatMap((r) => grid(r.start, r.end - MIN, stepMinutes, zone));
}

/**
 * Allowed end window for a start (legacy generateEndRange): the free range containing `start` ([start, end) by
 * minute); its first end = next step mark strictly after `start`; with a max duration the window ends at
 * first end + max − 1 min. Null when `start` is in no free range.
 */
export function endWindow(
  start: number,
  freeRanges: readonly TimeRange[],
  stepMinutes: number,
  zone: string,
  maxDurationMinutes?: number | null,
): TimeRange | null {
  const s = floorMinute(start);
  const range = freeRanges.find((r) => s >= floorMinute(r.start) && s < floorMinute(r.end));
  if (!range) return null;
  let first = floorMinute(range.start) < s ? ceilToStep(s, stepMinutes, zone) : floorMinute(range.start);
  if (first <= s) first = s + stepMinutes * MIN;
  let end = floorMinute(range.end);
  if (maxDurationMinutes && (end - first) / MIN > maxDurationMinutes) end = first + (maxDurationMinutes - 1) * MIN;
  return { start: first, end };
}

/** End options: step marks inside endWindow(start). */
export function endOptions(
  start: number,
  freeRanges: readonly TimeRange[],
  stepMinutes: number,
  zone: string,
  maxDurationMinutes?: number | null,
): number[] {
  const w = endWindow(start, freeRanges, stepMinutes, zone, maxDurationMinutes);
  return w ? grid(w.start, w.end, stepMinutes, zone) : [];
}

/**
 * New range after the start changed (legacy onStartModelChange): an end outside the new end window, or not after the
 * start, moves to the next step mark after the start, or to the window end when that mark is outside the window.
 */
export function rangeAfterStartChange(
  start: number,
  currentEnd: number,
  freeRanges: readonly TimeRange[],
  stepMinutes: number,
  zone: string,
  maxDurationMinutes?: number | null,
): TimeRange {
  const w = endWindow(start, freeRanges, stepMinutes, zone, maxDurationMinutes);
  if (!w) return { start, end: currentEnd };
  let end = currentEnd;
  if (end < w.start || end > w.end || start >= end) {
    end = ceilToStep(start + MIN, stepMinutes, zone);
    if (end < w.start || end > w.end) end = w.end;
  }
  return { start, end };
}

/** A selector is disabled with no options, or with one option equal to its value (calculateDropdownAccessibility). */
export function isSelectorDisabled(options: readonly number[], value: number): boolean {
  return options.length === 0 || (options.length === 1 && floorMinute(options[0]!) === floorMinute(value));
}
