import type { MouseEvent } from 'react';
import type { BlockedArea, Positioned, TimelineBlock } from '@/domain/timeline-layout';
import { px } from './hours';
import styles from './timeline.module.css';

/** Texts of one block, already resolved by the screen (privacy rules: domain/room-status `blockTitles`). */
export interface BlockTitleTexts {
  main: string | null;
  secondary: string | null;
}

const cx = (...names: (string | false | null | undefined)[]): string => names.filter(Boolean).join(' ');
const stop = (e: MouseEvent): void => e.stopPropagation();
const axis = (p: Positioned): { top: string; height: string } => ({ top: `${px(p.offsetMin)}px`, height: `${px(p.sizeMin)}px` });

export function HourRows({ labels }: { labels: readonly string[] }): JSX.Element {
  return (
    <div>
      {labels.map((label, i) => {
        const last = i === labels.length - 1;
        return (
          <div className={styles.hour} key={i} data-hour={i}>
            <div className={styles.label}>
              <div className={styles.labelText}>{label}</div>
            </div>
            {last ? (
              <div className={styles.lastSlots} />
            ) : (
              <div className={styles.slots}>
                <div className={styles.slot} />
                <div className={styles.slot} />
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

export interface BlockProps {
  block: TimelineBlock;
  titles: BlockTitleTexts;
  /** Accessible name when no title is visible (e.g. "10:00 – 10:30"). */
  timeLabel: string;
  onTap?: (block: TimelineBlock) => void;
}

/** One booking block (SCR-ROOM timeline.booking-block, TOK-TIMELINE-BLOCK). A tap never reaches the hour rows. */
export function BookingBlock({ block, titles, timeLabel, onTap }: BlockProps): JSX.Element {
  const main = block.mainTitle ? titles.main : null;
  const secondary = block.secondaryTitle ? titles.secondary : null;
  const name = [main, secondary].filter(Boolean).join(', ') || timeLabel;
  return (
    <button
      type="button"
      className={cx(
        styles.block,
        block.isSelected && styles.selected,
        (main || secondary) && styles.titled,
        block.startsBefore && styles.squareStart,
        block.endsAfter && styles.squareEnd,
      )}
      style={axis(block)}
      aria-label={name}
      aria-pressed={block.isSelected}
      disabled={!onTap}
      data-booking-id={block.id}
      onClick={(e) => {
        stop(e);
        onTap?.(block);
      }}
    >
      {main ? <span className={styles.title}>{main}</span> : null}
      {secondary ? <span className={styles.title}>{secondary}</span> : null}
    </button>
  );
}

/** Shaded past / non-working time (TOK-OVERLAY-BLOCKED); taps there do nothing. */
export function BlockedOverlay({ area }: { area: BlockedArea }): JSX.Element {
  return (
    <div
      className={cx(styles.blocked, area.startEdge && styles.edgeStart, area.endEdge && styles.edgeEnd)}
      style={axis(area)}
      data-testid="timeline.blocked-area"
      onClick={stop}
    />
  );
}

/** White outline of the range being booked (TOK-TIMELINE-RANGE). */
export function SelectedRange({ piece }: { piece: Positioned }): JSX.Element {
  return <div className={styles.range} style={axis(piece)} data-testid="timeline.selected-range" />;
}

export { cx };
