import { BookingButtons } from './booking-buttons';
import { BookingForm } from './booking-form';
import { QuickButtons } from './quick-buttons';
import type { PanelProps } from './types';

/**
 * Booking actions of the room screen, rendered by `RoomScreen` in its `bookingPanel` slot: quick block (Body A),
 * booking form (Body B) or the booking buttons (Body C), by `part`.
 */
export function BookingPanel(props: PanelProps): JSX.Element | null {
  if (props.part === 'free') return <QuickButtons {...props} />;
  if (props.part === 'form') return <BookingForm {...props} />;
  return <BookingButtons {...props} />;
}
