import { useEffect } from 'react';
import { useT } from '@/i18n';
import { useScheduler } from '@/kernel';
import { useAppContainer } from '@/app/providers';
import { Menu } from './menu';
import styles from './shell.module.css';

/** TMR-HEALTH-HEARTBEAT period for a screen without its own status tick. */
const PLACEHOLDER_HEARTBEAT_MS = 60_000;

/**
 * /spaces/all until the rooms board lands (Plan 3 stage 3, T-3.1.2). It counts as a ready screen (BOOT-10) and keeps
 * the health heartbeat alive, so the watchdog never hard-reloads a board device for a missing tick.
 */
export function BoardPlaceholder({ hasRoom }: { hasRoom: boolean }): JSX.Element {
  const t = useT();
  const scheduler = useScheduler();
  const { health } = useAppContainer();
  useEffect(() => {
    health.markReady();
    scheduler.every('board-placeholder-heartbeat', PLACEHOLDER_HEARTBEAT_MS, () => health.heartbeat());
    return () => scheduler.cancel('board-placeholder-heartbeat');
  }, [health, scheduler]);
  return (
    <main className={styles.placeholder}>
      <div className={styles.placeholderMenu}>
        <Menu hasRoom={hasRoom} />
      </div>
      <h2>{t('SIDEBAR.ALL_SPACES')}</h2>
      <p className={styles.placeholderText}>The rooms board comes in stage 3.</p>
    </main>
  );
}
