import { useId } from 'react';
import { useT } from '@/i18n';
import { QrCode } from './qr-code';
import styles from './qr.module.css';

export interface QrModalProps {
  value: string;
  onClose: () => void;
  /** Heading; default t('SPACE.QR_TITLE'). */
  title?: string;
}

/**
 * Enlarged QR (SCR-ROOM/ST-QR-MODAL, part qr-modal): close X, SPACE.QR_TITLE, QR 300×300. A dialog panel meant to be
 * opened with `dialogs.open(({ close }) => <QrModal value={link} onClose={() => close()} />)` from @/ui/primitives,
 * so overlay tap, Escape, navigation and idle `closeAll` close it.
 */
export function QrModal({ value, onClose, title }: QrModalProps): JSX.Element {
  const t = useT();
  const headingId = useId();
  const heading = title ?? t('SPACE.QR_TITLE');
  return (
    <div role="dialog" aria-modal="true" aria-labelledby={headingId} className={styles.modal} onClick={(e) => e.stopPropagation()}>
      <div className={styles.modalHeader}>
        <button type="button" className={styles.modalClose} aria-label={t('APP.CLOSE')} onClick={onClose}>
          <svg width="32" height="32" viewBox="0 0 32 32" aria-hidden="true" focusable="false">
            <path
              fillRule="evenodd"
              clipRule="evenodd"
              d="M25.5858 4.99999C25.9763 4.60946 26.6095 4.60946 27 4.99999C27.3905 5.39051 27.3905 6.02367 27 6.4142L17.4142 16L27 25.5858C27.3905 25.9763 27.3905 26.6095 27 27C26.6095 27.3905 25.9763 27.3905 25.5858 27L16 17.4142L6.4142 27C6.02367 27.3905 5.39051 27.3905 4.99999 27C4.60946 26.6095 4.60946 25.9763 4.99999 25.5858L14.5858 16L4.99999 6.4142C4.60946 6.02368 4.60946 5.39051 4.99999 4.99999C5.39051 4.60946 6.02368 4.60946 6.4142 4.99999L16 14.5858L25.5858 4.99999Z"
            />
          </svg>
        </button>
      </div>
      <div className={styles.modalBody}>
        <h4 id={headingId} className={styles.modalTitle}>
          {heading}
        </h4>
        <QrCode value={value} size={300} label={heading} />
      </div>
    </div>
  );
}
