import { useEffect, useState } from 'react';
import { NavLink, useLocation } from 'react-router-dom';
import { useT } from '@/i18n';
import { CloseIcon } from '@/ui/primitives';
import { ROUTES } from './routes';
import styles from './menu.module.css';

export interface MenuProps {
  /** "Meeting room" is listed only for a device with a room (DEV-D-91). */
  hasRoom: boolean;
}

/**
 * SCR-MENU (DEV-D-91: one menu on both screens): burger toggle + side panel with "Meeting room" (device with a room)
 * and "All meeting rooms"; the current screen highlighted; closes on navigation, on X and on the overlay. No logout,
 * reload or language items (DEV-D-23). The caller omits it on a shared room.
 */
export function Menu({ hasRoom }: MenuProps): JSX.Element {
  const t = useT();
  const [open, setOpen] = useState(false);
  const { pathname } = useLocation();
  useEffect(() => setOpen(false), [pathname]);
  const link = ({ isActive }: { isActive: boolean }): string => `${styles.link} ${isActive ? styles.active : ''}`;
  return (
    <>
      <button type="button" className={styles.burger} aria-label="Menu" aria-expanded={open} onClick={() => setOpen(true)}>
        <span />
        <span />
        <span />
      </button>
      {open && (
        <div className={styles.root}>
          <div className={styles.overlay} data-testid="menu-overlay" onClick={() => setOpen(false)} />
          <nav className={styles.panel} aria-label="Menu">
            <div className={styles.header}>
              <button type="button" className={styles.close} aria-label={t('APP.CLOSE')} onClick={() => setOpen(false)}>
                <CloseIcon size={20} />
              </button>
            </div>
            <div className={styles.links}>
              {hasRoom && (
                <NavLink to={ROUTES.room} className={link}>
                  {t('SIDEBAR.SPACE')}
                </NavLink>
              )}
              <NavLink to={ROUTES.board} className={link}>
                {t('SIDEBAR.ALL_SPACES')}
              </NavLink>
            </div>
          </nav>
        </div>
      )}
    </>
  );
}
