/**
 * Redaction rules (ADR-0001 "Telemetry redaction", DEV-D-36): no tokens, Authorization headers, `authorization=` query
 * parameters, JWT-shaped strings, e-mails, PINs, organizer names, request/response bodies or real-time payloads.
 * Kept: device id, tenant tag, event names, status codes, error codes.
 */
export const REDACTED = '[redacted]';

/** Object keys whose value is dropped whatever it holds (compared case-insensitively, `-`/`_` ignored). */
const SECRET_KEYS = new Set(
  [
    'authorization', 'proxyauthorization', 'cookie', 'cookies', 'setcookie', 'token', 'accesstoken', 'refreshtoken',
    'idtoken', 'jwt', 'pin', 'password', 'secret', 'email', 'organizeremail', 'organizer', 'firstname', 'lastname',
    'fullname', 'username', 'ipaddress', 'body', 'requestbody', 'responsebody', 'response', 'payload', 'querystring',
    'servertext', 'title',
  ],
);

const normKey = (k: string): string => k.toLowerCase().replace(/[-_]/g, '');
export const isSecretKey = (key: string): boolean => SECRET_KEYS.has(normKey(key));

const STRING_RULES: Array<[RegExp, string]> = [
  [/eyJ[\w-]+\.[\w-]+\.[\w-]*/g, '[jwt]'],
  [/\b(Bearer)\s+[^\s"',;]+/gi, `$1 ${REDACTED}`],
  [/([?&#](?:authorization|token|access_token|refresh_token|pin|email)=)[^&#\s"']*/gi, `$1${REDACTED}`],
  [/("(?:pin|password|token|refresh_token|authorization|email)"\s*:\s*)"[^"]*"/gi, `$1"${REDACTED}"`],
  [/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, '[email]'],
];

export function redactString(s: string): string {
  return STRING_RULES.reduce((acc, [re, to]) => acc.replace(re, to), s);
}

/** Deep copy with secret keys dropped and every string passed through `redactString`. Cycles become '[cycle]'. */
export function redact(value: unknown, seen: WeakSet<object> = new WeakSet()): unknown {
  if (typeof value === 'string') return redactString(value);
  if (value === null || typeof value !== 'object') return value;
  if (seen.has(value)) return '[cycle]';
  seen.add(value);
  if (value instanceof Error) {
    const copy = new Error(redactString(value.message));
    copy.name = value.name;
    if (value.stack) copy.stack = redactString(value.stack);
    return copy;
  }
  if (Array.isArray(value)) return value.map((v) => redact(v, seen));
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(value)) out[k] = isSecretKey(k) ? REDACTED : redact(v, seen);
  return out;
}
