import { useCallback, useEffect, useRef, type ReactNode } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { startMidnightJob, useAppEvent, useKernel } from '@/kernel';
import { useConnectivity } from '@/platform/connectivity';
import type { Telemetry } from '@/platform/telemetry';
import { useUiStore } from '@/state/ui';
import { dialogs } from '@/ui/primitives';
import { OfflineOverlay } from './offline-overlay';
import type { RuntimeHealth } from './runtime-health';

/** TMR-TEL-FLUSH-BEFORE-RELOAD: wait at most 10 s for telemetry before a remote reload. */
export const RELOAD_FLUSH_MS = 10_000;

export interface KioskRuntimeProps {
  /** Telemetry port (the one instance of app/providers). */
  telemetry: Pick<Telemetry, 'captureEvent' | 'flush'>;
  /** The ONE page reload of app/bootstrap. */
  reload: (reason: string) => void;
  health: RuntimeHealth;
  /** Route of the room screen for a device with a room; null = no idle return (device without a room, DEV-D-7). */
  homePath: string | null;
  /** Display zone (room → company default): set on the Clock, and the midnight job restarts in it. */
  zone?: string;
  children: ReactNode;
}

/**
 * Mounted once around the screens (T08). Owns: SCR-OFFLINE-OVERLAY (the screen is unmounted while offline and rebuilt
 * on return, DEV-D-6, RLD-SCREEN-REBUILD), remote reload (RLD-DEVICE-RELOAD, DEV-D-10), midnight (`day.changed`,
 * RLD-MIDNIGHT, DEV-D-43), idle home (`idle.timeout`, TMR-APP-IDLE-HOME, DEV-D-7) and the screen heartbeat (DEV-D-5).
 */
export function KioskRuntime({ telemetry, reload, health, homePath, zone, children }: KioskRuntimeProps): JSX.Element {
  const connection = useConnectivity();
  const { clock, scheduler, events } = useKernel();
  const navigate = useNavigate();
  const location = useLocation();
  const reloading = useRef(false);

  useEffect(() => {
    if (zone) clock.setZone(zone);
    return startMidnightJob(clock, scheduler, (day) => events.emit({ type: 'day.changed', day }));
  }, [clock, scheduler, events, zone]);

  // DEV-D-5: every status publish of the shown screen (status-5s tick) is the heartbeat.
  useEffect(
    () =>
      useUiStore.subscribe((s, prev) => {
        if (s.statusSeq !== prev.statusSeq) health.heartbeat();
      }),
    [health],
  );

  const onReloadRequested = useCallback(() => {
    if (reloading.current) return;
    reloading.current = true;
    telemetry.captureEvent('scheduled_device_reload', { level: 'info' });
    void telemetry.flush(RELOAD_FLUSH_MS).then(() => reload('device_reload'));
  }, [telemetry, reload]);
  useAppEvent('device.reloadRequested', onReloadRequested);

  const onIdle = useCallback(() => {
    dialogs.closeAll();
    if (homePath && location.pathname !== homePath) navigate(homePath);
  }, [homePath, location.pathname, navigate]);
  useAppEvent('idle.timeout', onIdle);

  if (connection !== 'online') return <OfflineOverlay state={connection} />;
  return <>{children}</>;
}
