import { useState } from 'react';
import { dayKey } from '@/kernel';
import { formatDate, formatTime, getLanguage, useT } from '@/i18n';
import { ASSETS } from '@/ui/theme';
import styles from './room-display.module.css';

export interface FooterProps {
  /** Instant of the last successful bookings read; null = no text (SCR-ROOM footer.updated). */
  updatedAt: number | null;
  now: number;
  zone: string;
  hour12: boolean;
  onReload(): void;
}

/** SCR-ROOM footer: "updated at HH:mm" (or "updated on DD.MM.YYYY at HH:mm") + reload button (second tap ignored). */
export function Footer({ updatedAt, now, zone, hour12, onReload }: FooterProps): JSX.Element {
  const t = useT();
  const [reloading, setReloading] = useState(false);
  let text: string | null = null;
  if (updatedAt !== null) {
    const time = formatTime(updatedAt, zone, getLanguage(), { hour12 });
    text =
      dayKey(updatedAt, zone) === dayKey(now, zone)
        ? t('SPACE.LAST_UPDATED_TODAY', { TIME: time })
        : t('SPACE.LAST_UPDATED_WITH_DATE', { DATE: formatDate(updatedAt, zone, getLanguage(), { numeric: true }), TIME: time });
  }
  return (
    <div className={styles.footer}>
      {text ? <div className={styles.updated}>{text}</div> : null}
      <button
        type="button"
        className={styles.reload}
        aria-label="reload"
        disabled={reloading}
        onClick={() => {
          setReloading(true);
          onReload();
        }}
      >
        <img src={ASSETS.reloadIcon} alt="" />
      </button>
    </div>
  );
}
