/**
 * Port to the page's host app (T34). DL-13: the iOS host adaptation is out of scope, so the only adapter is a no-op
 * extension point called at the two legacy moments (DEV-D-25: after init/login, and on logout).
 */
export interface HostSessionInfo {
  deviceId: string;
  apiOrigin: string;
}

export interface HostBridge {
  /** Session became ready (legacy: window.UNSPOT_* globals + webkit jsHandler). */
  sessionStarted(info: HostSessionInfo): void;
  /** Session ended / logout (legacy: globals nulled + webkit logoutHandler). */
  sessionEnded(): void;
}

/** DEV-D-25 DROP: no window globals, no webkit messages. */
export const noopHostBridge: HostBridge = {
  sessionStarted: () => undefined,
  sessionEnded: () => undefined,
};
