import { useEffect } from 'react';
import type { Me, RoomDetail } from '@/contract';
import { useCheckInDefaultsQuery, useCompanyCardQuery, useCompanySettingsQuery, useMeQuery, useRoomDetailQuery } from '@/data/queries';
import { useClock } from '@/kernel';
import { useSession, useSessionStore } from '@/state/session';
import { useAppContainer } from '@/app/providers';

export type BootStatus = 'loading' | 'failed' | 'ready';

export interface BootInit {
  status: BootStatus;
  me: Me | undefined;
  room: RoomDetail | undefined;
}

/**
 * BOOT-7 init (boot bundle, all or nothing, DEV-D-3 KEEP): company card, me, room card (only with a room), company
 * settings, check-in defaults (OP-SETTINGS-POLICY is not called, DEV-D-72). Writes the health record (initStarted /
 * initCompleted / initFailed) for CONN-RECOVERY; on success sets the telemetry context (TEL-CONTEXT), the display zone
 * (room → company default) and the company sub-domain from the card (FLAG-COMPANY-SUBDOMAIN). A failure keeps the
 * spinner (SCR-BOOT-SPINNER/ST-INIT-FAILED, CP-17); the watchdog's soft recovery re-runs it.
 */
export function useBootInit(): BootInit {
  const { health, telemetry } = useAppContainer();
  const clock = useClock();
  const store = useSessionStore();
  const subDomain = useSession((s) => s.subDomain);
  const card = useCompanyCardQuery();
  const me = useMeQuery();
  const roomId = me.data?.device?.space?.id ?? null;
  const room = useRoomDetailQuery(roomId);
  const settings = useCompanySettingsQuery();
  const defaults = useCheckInDefaultsQuery();

  const reads = [card, me, settings, defaults, ...(roomId ? [room] : [])];
  const failed = reads.some((q) => q.isError);
  const ready = !failed && reads.every((q) => q.isSuccess);
  const status: BootStatus = failed ? 'failed' : ready ? 'ready' : 'loading';
  const errorStamp = reads.reduce((n, q) => Math.max(n, q.errorUpdatedAt), 0);

  useEffect(() => {
    if (status === 'loading') health.initStarted();
    else if (status === 'failed') health.initFailed();
    else health.initCompleted();
  }, [status, errorStamp, health]);

  // The room screen reads clock.zone() on its first render: set the display zone synchronously (idempotent).
  const zone = status === 'ready' ? me.data?.device?.space?.timezone || settings.data?.defaultTimezone : null;
  if (zone && clock.zone() !== zone) clock.setZone(zone);

  useEffect(() => {
    if (status !== 'ready' || !me.data) return;
    telemetry.setContext({ deviceId: me.data.id, tenant: subDomain ?? undefined, deviceName: me.data.device?.name });
  }, [status, me.data, subDomain, telemetry]);

  useEffect(() => {
    if (card.data?.subDomain) store.getState().setSubDomain(card.data.subDomain);
  }, [card.data, store]);

  return { status, me: me.data, room: room.data };
}
