import type { AppError } from '@/kernel';
import type { I18nKey } from './keys';
import { translate } from './i18n';

/**
 * AppError.code → i18n key: the ONE table (ARCHITECTURE §3 Errors). Codes are the `key` of the refusal cards in
 * product/contract/operations/display.yaml, verbatim. A code mapped to `null` is never shown (handled by a branch:
 * logout, re-read, silent check-in). A refused code that is NOT in the table shows the server text (cards with
 * `client: show-text` / legacy toast with the message, rendered as plain text — DEV-D-37).
 */
export const ERROR_MESSAGES: Readonly<Record<string, I18nKey | null>> = {
  // OP-AUTH-COMPANY-CARD
  'Tenant not found.': 'LOGIN.TENANT_NOT_FOUND',
  // OP-AUTH-PIN-LOGIN: one text for every PIN refusal (DEV-D-11, DEV-D-12)
  'auth.invalid_credentials': 'LOGIN.ACTIVATION_CODE_INVALID',
  'auth.space_pin_expired': 'LOGIN.ACTIVATION_CODE_INVALID',
  // common refusals with a branch, never a text
  CLIENT_NOT_FOUND: null,
  'meeting_room.id_not_found': null,
  // OP-BOOKINGS-CHECKIN: refusals are silent on the room display (legacy, RK-SA3-3)
  'booking.checkin.disabled_display': null,
  'booking.checkin.disabled': null,
  'booking.checkin.already': null,
  'booking.checkin.window_closed': null,
};

/** No answer from the server (status -1 / timeout): DEV-D-38 (room toast), DEV-D-14 (activation lookup). */
const CONNECTION_LOST: I18nKey = 'APP.SERVER_CONNECTION_LOST';
/** Error without a code in the table and without a server text (e.g. 500 HTML page). */
const GENERIC: I18nKey = 'APP.REQUEST_FAILED';

/**
 * Key to show for an error, or null when the UI shows no key:
 * - `aborted` (DEV-D-88), `outcome-unknown` (ADR-0004 addendum) and `unauthorized` (logout branch) → null;
 * - code in ERROR_MESSAGES → that entry (may be null = silent);
 * - `unreachable` / `timeout` → APP.SERVER_CONNECTION_LOST;
 * - error carrying `serverText` → null (show the server text, see `errorMessageText`);
 * - anything else → APP.REQUEST_FAILED.
 */
export function errorMessageKey(error: AppError): I18nKey | null {
  if (error.kind === 'aborted' || error.kind === 'outcome-unknown') return null;
  if (Object.prototype.hasOwnProperty.call(ERROR_MESSAGES, error.code)) return ERROR_MESSAGES[error.code] ?? null;
  if (error.kind === 'unauthorized') return null;
  if (error.kind === 'unreachable' || error.kind === 'timeout') return CONNECTION_LOST;
  if (error.serverText && error.serverText.trim() !== '') return null;
  return GENERIC;
}

/** True when nothing at all is shown for this error (silent). */
export function isSilentError(error: AppError): boolean {
  return errorMessageText(error) === null;
}

/**
 * Plain text to show (toast, popup, field error), or null when nothing is shown.
 * Key from `errorMessageKey` wins; otherwise the server text as plain text (DEV-D-37).
 */
export function errorMessageText(error: AppError, t: (key: I18nKey) => string = translate): string | null {
  const key = errorMessageKey(error);
  if (key) return t(key);
  if (error.kind === 'aborted' || error.kind === 'outcome-unknown' || error.kind === 'unauthorized') return null;
  if (Object.prototype.hasOwnProperty.call(ERROR_MESSAGES, error.code)) return null;
  const text = error.serverText?.trim();
  return text ? text : null;
}
