import { useT } from '@/i18n';
import { useUiStore } from '@/state/ui';
import { ConfirmDialog, dialogs, TrashIcon } from '@/ui/primitives';

export type CancelKind = 'stop' | 'delete';

interface Props {
  bookingId: string;
  /** Label of the pressed button (DEV-D-134). */
  pressed: CancelKind;
  onConfirm(): void;
  onCancel(): void;
}

/**
 * SCR-CONFIRM (room variant) for Stop / Delete. Wording follows the pressed button and re-labels on the next
 * evaluation when the booking crossed its start while the dialog is open (DEV-D-134, DEV-D-105).
 */
export function StopDeleteDialog({ bookingId, pressed, onConfirm, onCancel }: Props): JSX.Element {
  const t = useT();
  const body = useUiStore((s) => (s.roomStatus?.booking?.booking.id === bookingId ? s.roomStatus.booking : null));
  const kind: CancelKind = body?.stop ? 'stop' : body?.delete ? 'delete' : pressed;
  return (
    <ConfirmDialog
      question={t(kind === 'stop' ? 'SPACE.DO_YOU_WANT_TO_STOP_BOOKING' : 'SPACE.DO_YOU_WANT_TO_DELETE_BOOKING')}
      confirmLabel={t(kind === 'stop' ? 'SPACE.STOP' : 'SPACE.DELETE')}
      confirmIcon={kind === 'delete' ? <TrashIcon /> : undefined}
      cancelLabel={t('SPACE.CANCEL')}
      onConfirm={onConfirm}
      onCancel={onCancel}
    />
  );
}

/** Opens the dialog; resolves true only on confirm (the dialog is closed before the caller sends, ST-CONFIRM). */
export function confirmCancel(bookingId: string, pressed: CancelKind): Promise<boolean> {
  return new Promise((resolve) => {
    dialogs.open(
      ({ close }) => <StopDeleteDialog bookingId={bookingId} pressed={pressed} onConfirm={() => close(true)} onCancel={() => close(false)} />,
      { onClose: (r) => resolve(r === true) },
    );
  });
}
