import type { DateRange } from '@/domain/booking-model';
import { addDaysInZone, atLocalTime, minutesOfDay, startOfDayInZone } from '@/kernel';

/** Working hours as configured: wall times 'HH:mm' in `zone` (office zone, or the company default zone). */
export interface WorkingHours {
  start: string;
  end: string;
  zone: string;
}

/** `me.device.space` working-hours fields (parent office values, device.yaml DisplayedRoom). */
export interface OfficeHoursSource {
  useDefaultSettings: boolean;
  startWorking: string | null;
  endWorking: string | null;
  timezone: string | null;
}

/** Company settings working-hours fields (OP-SETTINGS-COMMON). */
export interface CompanyHoursSource {
  defaultCompanyWorkingStartTime: string | null;
  defaultCompanyWorkingEndTime: string | null;
  defaultTimezone: string | null;
}

const HALF_DAY_MS = 12 * 60 * 60 * 1000;

/** 'HH:mm', 'H:mm', 'HH:mm:ss' or 'h:mm a' -> normalized 'HH:mm'; null when not a time. */
export function parseHhmm(text: string): string | null {
  const m = /^\s*(\d{1,2}):(\d{2})(?::\d{2})?\s*([ap]m)?\s*$/i.exec(text);
  if (!m) return null;
  let h = Number(m[1]);
  const min = Number(m[2]);
  const ampm = m[3]?.toLowerCase();
  if (ampm) {
    if (h < 1 || h > 12) return null;
    h = (h % 12) + (ampm === 'pm' ? 12 : 0);
  }
  if (h > 23 || min > 59) return null;
  return `${String(h).padStart(2, '0')}:${String(min).padStart(2, '0')}`;
}

/**
 * Which hours apply (device.yaml DisplayedRoom startWorking/endWorking): the office's own hours unless
 * `useDefaultSettings`, else the company defaults. A missing value falls back to the next source; with nothing left
 * the whole day (start = end) in `displayZone` [assumed: no legacy path, REV-T-2.1.2-domain-rules].
 */
export function resolveWorkingHours(
  office: OfficeHoursSource | null,
  company: CompanyHoursSource | null,
  displayZone: string,
): WorkingHours {
  if (office && !office.useDefaultSettings) {
    const start = office.startWorking ? parseHhmm(office.startWorking) : null;
    const end = office.endWorking ? parseHhmm(office.endWorking) : null;
    if (start && end) return { start, end, zone: office.timezone ?? displayZone };
  }
  if (company) {
    const start = company.defaultCompanyWorkingStartTime ? parseHhmm(company.defaultCompanyWorkingStartTime) : null;
    const end = company.defaultCompanyWorkingEndTime ? parseHhmm(company.defaultCompanyWorkingEndTime) : null;
    if (start && end) return { start, end, zone: company.defaultTimezone ?? displayZone };
  }
  return { start: '00:00', end: '00:00', zone: displayZone };
}

/** [local midnight, next local midnight) of the day containing `dayMs` in `zone`. */
export function dayRange(dayMs: number, zone: string): DateRange {
  return { start: startOfDayInZone(dayMs, zone), end: addDaysInZone(dayMs, 1, zone) };
}

const toHhmm = (minutes: number) => `${String(Math.floor(minutes / 60)).padStart(2, '0')}:${String(minutes % 60).padStart(2, '0')}`;

/** Wall time `hhmm` of `fromZone` expressed as minutes of the day in `toZone` (on the given day). */
function convertedMinutes(dayStart: number, hhmm: string, fromZone: string, toZone: string): number {
  const instant = atLocalTime(dayStart + HALF_DAY_MS, hhmm, fromZone);
  return minutesOfDay(instant, toZone);
}

/**
 * Working ranges of the day containing `dayMs`, in the display `zone` (fe working-time-generator.ts:22-76,
 * DT-STATUS-40): start = end -> whole day; start > end -> [midnight, end) and [start, next midnight); else [start, end).
 * Empty ranges are dropped.
 */
export function workingRanges(dayMs: number, hours: WorkingHours, zone: string): DateRange[] {
  const day = dayRange(dayMs, zone);
  const s = convertedMinutes(day.start, hours.start, hours.zone, zone);
  const e = convertedMinutes(day.start, hours.end, hours.zone, zone);
  const atMin = (m: number) => atLocalTime(day.start, toHhmm(m), zone);
  let ranges: DateRange[];
  if (s === e) ranges = [day];
  else if (s > e) ranges = [{ start: day.start, end: atMin(e) }, { start: atMin(s), end: day.end }];
  else ranges = [{ start: atMin(s), end: atMin(e) }];
  return ranges.filter((r) => r.end > r.start);
}

/** The range that contains `at` ([start, end)), or null. */
export function rangeAt(ranges: readonly DateRange[], at: number): DateRange | null {
  return ranges.find((r) => r.start <= at && at < r.end) ?? null;
}

/** RULE-STATUS hours input: `at` lies inside one of the ranges. */
export function isWorkingAt(ranges: readonly DateRange[], at: number): boolean {
  return rangeAt(ranges, at) !== null;
}

/** Ranges that have not ended at `at` (legacy filter `end > now`, applied when the day's ranges are generated, DEV-D-52). */
export function openRangesAfter(ranges: readonly DateRange[], at: number): DateRange[] {
  return ranges.filter((r) => r.end > at);
}

/** Hull of the day's working ranges (earliest start .. latest end); the whole day when there is none. */
export function officeRange(dayMs: number, hours: WorkingHours, zone: string): DateRange {
  const ranges = workingRanges(dayMs, hours, zone);
  if (ranges.length === 0) return dayRange(dayMs, zone);
  return { start: Math.min(...ranges.map((r) => r.start)), end: Math.max(...ranges.map((r) => r.end)) };
}
