import { QrCode } from './qr-code';
import styles from './qr.module.css';

export interface QrCardProps {
  value: string;
  /** Already translated caption (SPACE.QR_SETTINGS.* for the room QR, SPACE.CHECKIN_QR_AVAILABLE_TEXT for check-in). */
  caption: string;
  /** Tap on the QR enlarges it (open QrModal through dialogs.open). Without it the QR is not interactive. */
  onOpen?: () => void;
  /** Accessible name of the enlarge button; default = caption. */
  openLabel?: string;
  /** Vertical separator between QR and caption (room QR: yes; check-in QR in booking info: no). */
  separator?: boolean;
  className?: string;
}

/** QR block of the room screen (body.free.qr, booking-info check-in QR): card with QR 100×100 and caption. */
export function QrCard({ value, caption, onOpen, openLabel, separator = true, className }: QrCardProps): JSX.Element {
  return (
    <div className={[styles.card, className].filter(Boolean).join(' ')}>
      {onOpen ? (
        <button type="button" className={styles.button} aria-label={openLabel ?? caption} onClick={onOpen}>
          <QrCode value={value} size={100} />
        </button>
      ) : (
        <QrCode value={value} size={100} label={caption} />
      )}
      {separator ? <hr className={styles.separator} /> : null}
      <div className={styles.caption}>{caption}</div>
    </div>
  );
}
