import { useEffect } from 'react';
import type { LedDriver } from '@/platform/led';
import { useUiStore } from '@/state/ui';

export interface LedStatusProps {
  /** Resolved driver (app/providers: `await ledDetector.detect()`; noopLedDriver until then). */
  driver: LedDriver;
}

/**
 * Headless (F10): sends the room status colour to the LED on every evaluation the room screen publishes — on a change
 * and again on every `status-5s` tick, even unchanged (RULE-STATUS-LED-EVERY-TICK, DEV-D-92 KEEP: panels may reset the
 * LED). Nothing is sent while loading (`led` null, DEV-D-42) or off the room screen (DEV-D-93 KEEP). Driver errors are
 * swallowed by the driver.
 */
export function LedStatus({ driver }: LedStatusProps): null {
  const seq = useUiStore((s) => s.statusSeq);
  useEffect(() => {
    const led = useUiStore.getState().roomStatus?.led ?? null;
    if (led) void driver.setStatus(led.status);
  }, [seq, driver]);
  return null;
}
