import type { Booking } from '@/domain/booking-model';
import { err, ok, type AppError, type Result } from '@/kernel';
import { OPS, parseCreateAnswer, refineRefusal, toCreateBookingDto, type Me } from '@/contract';
import { cachePatches, queryKeys } from '@/data/queries';
import { staleSession, useCommand, type Command, type CommandContext } from './command-runner';

/** Title of a quick booking (fe space-view.component.ts:416-421) and of a form booking with an empty optional title. */
export const QUICK_BOOK_TITLE = 'Room Display';
const AUTO_CHECKIN = '20';

/** Marks the server sets at once when the booking starts inside an open check-in window (server_auto_checkin). */
export interface AutoCheckIn {
  remote: boolean;
  strict: boolean;
}

export type CreateRoomBookingInput =
  /** start = clock now, end = start + minutes floored to the minute (quick book 15/30/60). */
  | { kind: 'quick'; roomId: string; minutes: number; autoCheckIn?: AutoCheckIn }
  /** Booking form: title already resolved by the form (meetingTitleRequired), start / end epoch ms. */
  | { kind: 'form'; roomId: string; title: string; start: number; end: number; autoCheckIn?: AutoCheckIn };

export interface CreateRoomBookingEffect {
  /** The booking as inserted into the cache (dedup with the real-time echo by id). */
  booking: Booking;
}

function request(input: CreateRoomBookingInput, now: number): { title: string; start: number; end: number; roomId: string } {
  if (input.kind === 'form') return { title: input.title, start: input.start, end: input.end, roomId: input.roomId };
  const end = Math.floor((now + input.minutes * 60_000) / 60_000) * 60_000;
  return { title: QUICK_BOOK_TITLE, start: now, end, roomId: input.roomId };
}

async function createRoomBooking(ctx: CommandContext, input: CreateRoomBookingInput): Promise<Result<CreateRoomBookingEffect, AppError>> {
  const req = request(input, ctx.clock.now());
  const r = await ctx.http.post('/api/bookings/mr/new', toCreateBookingDto(req), { op: OPS.createRoom });
  if (!ctx.isCurrent()) return staleSession(OPS.createRoom);
  if (!r.ok) {
    const e = refineRefusal(OPS.createRoom, r.error);
    // outcome unknown → the day re-read tells (no automatic retry); overlap → re-read the room day (card client_note)
    if (e.kind === 'outcome-unknown' || e.code === 'booking.spaces.already_booked') await ctx.rereadDays();
    return err(e);
  }
  const answer = parseCreateAnswer(r.value.body);
  if (!answer.ok) {
    await ctx.rereadDays();
    return answer;
  }
  const me = ctx.qc.getQueryData<Me>(queryKeys.me(ctx.generation));
  const a = answer.value;
  const auto = input.autoCheckIn;
  const booking: Booking = {
    id: a.id,
    title: req.title,
    start: a.start,
    end: a.end,
    roomIds: [req.roomId],
    // DEV-D-60: the device user's id in both paths; the name from the answer (= device name)
    organizer: { id: me?.id ?? a.organizer.id, fullName: a.organizer.fullName, email: a.organizer.email, role: a.organizer.role ?? me?.role ?? null },
    madeByDisplay: true,
    isVisible: true,
    checkIn: {
      remoteBy: auto?.remote ? AUTO_CHECKIN : null,
      remoteAt: auto?.remote ? a.start : null,
      strictBy: auto?.strict ? AUTO_CHECKIN : null,
      strictAt: auto?.strict ? a.start : null,
    },
    stopReason: null,
  };
  cachePatches.insertBooking(ctx.qc, ctx.generation, booking);
  return ok({ booking });
}

/** OP-BOOKINGS-CREATE-ROOM (quick book and booking form). */
export function useCreateRoomBookingCommand(): Command<CreateRoomBookingInput, CreateRoomBookingEffect> {
  return useCommand(createRoomBooking);
}
