import type { Clock } from '@/kernel';
import { createConsoleTelemetry, createSentryTelemetry, noopTelemetry, type Telemetry } from '@/platform/telemetry';

export interface AppTelemetry extends Telemetry {
  /** After config.json: start Sentry with the runtime DSN when no build DSN started it (once per page). */
  configure(runtimeDsn: string): void;
}

export interface AppTelemetryOptions {
  clock: Clock;
  /** VITE_SENTRY_DSN. */
  buildDsn?: string;
  environment?: string;
  release?: string;
  /** Dev build without a DSN → console adapter (same redaction). */
  dev?: boolean;
}

/**
 * Telemetry first (DEV-D-40, TEL-INIT): the adapter is picked before config.json is read; a runtime DSN from the config
 * upgrades a console / no-op start to Sentry. The returned object stays the same, so every module holds one instance.
 */
export function createAppTelemetry(o: AppTelemetryOptions): AppTelemetry {
  const sentry = (dsn: string): Telemetry => createSentryTelemetry({ dsn, environment: o.environment, release: o.release, clock: o.clock });
  let started = !!o.buildDsn;
  let target: Telemetry = o.buildDsn ? sentry(o.buildDsn) : o.dev ? createConsoleTelemetry({ clock: o.clock }) : noopTelemetry;
  return {
    captureError: (e, opts) => target.captureError(e, opts),
    captureEvent: (name, opts) => target.captureEvent(name, opts),
    setContext: (ctx) => target.setContext(ctx),
    flush: (ms) => target.flush(ms),
    configure(runtimeDsn) {
      if (started || !runtimeDsn) return;
      started = true;
      target = sentry(runtimeDsn);
    },
  };
}
