import { createContext, useContext, type ReactNode } from 'react';
import type { HttpClient } from './http';

/** What data/queries and data/commands need from the composition root. */
export interface DataServices {
  http: HttpClient;
  /** A dropped server item (invalid DTO); never receives the payload (ADR-0004 §2). Wire to telemetry. */
  onInvalidItem?: (info: { op: string; index?: number; issues: string[] }) => void;
}

const HttpContext = createContext<DataServices | null>(null);

export function HttpProvider({ services, children }: { services: DataServices; children: ReactNode }): JSX.Element {
  return <HttpContext.Provider value={services}>{children}</HttpContext.Provider>;
}

export function useDataServices(): DataServices {
  const s = useContext(HttpContext);
  if (!s) throw new Error('HttpProvider missing');
  return s;
}
