import { createContext, useContext, useEffect, useState, type ReactNode } from 'react';
import type { Clock } from './clock';
import type { Scheduler } from './scheduler';
import type { EventBus, AppEventType, AppEvent } from './events';

export interface Kernel {
  clock: Clock;
  scheduler: Scheduler;
  events: EventBus;
}

const KernelContext = createContext<Kernel | null>(null);

export function KernelProvider({ kernel, children }: { kernel: Kernel; children: ReactNode }): JSX.Element {
  return <KernelContext.Provider value={kernel}>{children}</KernelContext.Provider>;
}

export function useKernel(): Kernel {
  const k = useContext(KernelContext);
  if (!k) throw new Error('KernelProvider missing');
  return k;
}

export const useClock = (): Clock => useKernel().clock;
export const useScheduler = (): Scheduler => useKernel().scheduler;
export const useEvents = (): EventBus => useKernel().events;

const GRANULARITY_MS = { '1s': 1000, '5s': 5000, '10s': 10000, '30s': 30000, '60s': 60000 } as const;
export type Granularity = keyof typeof GRANULARITY_MS;

let nowJobSeq = 0;
/** Current time, re-rendered every `granularity` (ADR-0004 §5). Components never read time directly. */
export function useNow(granularity: Granularity = '1s'): number {
  const { clock, scheduler } = useKernel();
  const [now, setNow] = useState(() => clock.now());
  useEffect(() => {
    const name = `useNow-${granularity}-${++nowJobSeq}`;
    setNow(clock.now());
    scheduler.every(name, GRANULARITY_MS[granularity], () => setNow(clock.now()));
    return () => scheduler.cancel(name);
  }, [clock, scheduler, granularity]);
  return now;
}

/** Subscribe to an AppEvent for the component lifetime. */
export function useAppEvent<K extends AppEventType>(type: K, handler: (e: Extract<AppEvent, { type: K }>) => void): void {
  const events = useEvents();
  useEffect(() => events.on(type, handler), [events, type, handler]);
}
