import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { dayWindow, useBookingsDayQuery, type BookingsDayScope } from '@/data/queries';
import { overlaps, type Booking, type DateRange } from '@/domain/booking-model';
import { roomStatus, type RoomStatusView } from '@/domain/room-status';
import { workingRanges as rangesOfDay } from '@/domain/working-hours';
import { dayKey, useAppEvent, useClock } from '@/kernel';
import { useUiStore } from '@/state/ui';
import { useJobTick } from './header';
import { useRoomData, type RoomData } from './use-room-data';

export interface RoomScreenModel {
  data: RoomData | null;
  zone: string;
  now: number;
  view: RoomStatusView | null;
  bookings: readonly Booking[];
  dayRange: DateRange;
  workingRanges: readonly DateRange[];
  updatedAt: number | null;
  loadedDay: string | null;
}

/** Shown day: initial local day, then `day.changed` (RLD-MIDNIGHT) or a tick that sees a new day (TMR-ROOM-DAY-ROLLOVER). */
function useShownDay(zone: string, tick: number): string {
  const clock = useClock();
  const [day, setDay] = useState(() => dayKey(clock.now(), zone));
  useAppEvent('day.changed', useCallback(() => setDay(dayKey(clock.now(), zone)), [clock, zone]));
  useEffect(() => setDay(dayKey(clock.now(), zone)), [tick, clock, zone]);
  const first = useRef(day);
  useEffect(() => {
    if (day !== first.current) useUiStore.getState().resetSelection(); // new day: selections cleared
    first.current = day;
  }, [day]);
  return day;
}

/** "updated at": the instant a bookings read of the shown day last succeeded (patches do not count). */
function useUpdatedAt(isFetching: boolean, isSuccess: boolean): number | null {
  const clock = useClock();
  const [at, setAt] = useState<number | null>(null);
  const wasFetching = useRef(false);
  useEffect(() => {
    if (!isFetching && isSuccess && (wasFetching.current || at === null)) setAt(clock.now());
    wasFetching.current = isFetching;
  }, [isFetching, isSuccess, clock, at]);
  return at;
}

/** Keeps state/ui consistent with the evaluation (RULE-STATUS-PRE, DEV-D-118, DEV-D-124) and publishes it for the LED. */
function useReconcile(view: RoomStatusView | null, bookings: readonly Booking[]): void {
  useEffect(() => {
    useUiStore.getState().publishRoomStatus(view);
    if (!view || view.status === null) return;
    const s = useUiStore.getState();
    if (s.selectedRange && (!view.selectedRange || bookings.some((b) => overlaps(b, view.selectedRange!)))) s.closeForm();
    const selected = s.selectedBookingId ? bookings.find((b) => b.id === s.selectedBookingId) : undefined;
    if (s.selectedBookingId && (!selected || selected.stopReason)) s.selectBooking(null);
  }, [view, bookings]);
  useEffect(() => () => useUiStore.getState().publishRoomStatus(null), []); // DEV-D-93: LED only on this screen
}

const NO_BOOKINGS: readonly Booking[] = [];

/** Container logic of SCR-ROOM: data, shown day, the `status-5s` evaluation and its side effects. */
export function useRoomScreen(): RoomScreenModel {
  const clock = useClock();
  const zone = clock.zone();
  const tick = useJobTick('status-5s', 5000); // TMR-ROOM-TICK, TMR-ROOM-INFO-TICK
  const data = useRoomData(zone);
  const day = useShownDay(zone, tick);
  const scope = useMemo<BookingsDayScope | null>(() => (data ? { scope: 'room', roomId: data.room.id, day, tz: zone } : null), [data, day, zone]);
  const dayRange = useMemo(() => dayWindow({ scope: 'board', day, tz: zone }), [day, zone]);
  const hours = data?.hours ?? null;
  const ranges = useMemo(() => (hours ? rangesOfDay(dayRange.start, hours, zone) : []), [hours, dayRange, zone]);
  const q = useBookingsDayQuery(scope);
  const list = q.data ?? null;
  const selectedBookingId = useUiStore((s) => s.selectedBookingId);
  const selectedRange = useUiStore((s) => s.selectedRange);
  const inFlight = useUiStore((s) => s.quickBookingInFlight);
  const { now, view } = useMemo(() => {
    const at = clock.now() + tick * 0; // one `now` per evaluation; re-evaluated on every tick and change
    if (!data) return { now: at, view: null };
    const input = { now: at, bookings: list, workingRanges: ranges, selectedBookingId, selectedRange, room: data.statusRoom };
    return { now: at, view: roomStatus({ ...input, abilities: data.abilities, checkin: data.checkin, quickBookingInFlight: inFlight }) };
  }, [clock, tick, data, list, ranges, selectedBookingId, selectedRange, inFlight]);
  const bookings = list ?? NO_BOOKINGS;
  useReconcile(view, bookings);
  const updatedAt = useUpdatedAt(q.isFetching, q.isSuccess);
  return { data, zone, now, view, bookings, dayRange, workingRanges: ranges, updatedAt, loadedDay: list ? day : null };
}
