import { useId, useRef, useState } from 'react';
import { ChevronDownIcon, useClickOutside } from '@/ui/primitives';
import styles from './time-picker.module.css';

export interface TimeSelectProps {
  value: number;
  options: readonly number[];
  format: (ms: number) => string;
  onSelect: (ms: number) => void;
  /** Accessible name of the trigger (the visible text is the value). */
  ariaLabel: string;
  disabled: boolean;
}

/** One time dropdown (un-time-selector): readonly value + chevron; list of options below (max 200 px, scroll). */
export function TimeSelect({ value, options, format, onSelect, ariaLabel, disabled }: TimeSelectProps): JSX.Element {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  const listId = useId();
  useClickOutside(ref, () => setOpen(false), open);
  const isOpen = open && !disabled;
  return (
    <div ref={ref} className={[styles.selector, isOpen && styles.opened].filter(Boolean).join(' ')}>
      <button
        type="button"
        className={styles.header}
        aria-label={`${ariaLabel} ${format(value)}`}
        aria-haspopup="listbox"
        aria-expanded={isOpen}
        aria-controls={isOpen ? listId : undefined}
        disabled={disabled}
        onClick={() => setOpen((o) => !o)}
      >
        <span className={styles.value}>{format(value)}</span>
        {disabled ? null : (
          <span className={styles.toggle}>
            <ChevronDownIcon />
          </span>
        )}
      </button>
      {isOpen ? (
        <ul id={listId} role="listbox" aria-label={ariaLabel} className={styles.dropdown}>
          {options.map((ms) => (
            <li
              key={ms}
              role="option"
              aria-selected={ms === value}
              className={styles.item}
              onClick={() => {
                onSelect(ms);
                setOpen(false);
              }}
            >
              {format(ms)}
            </li>
          ))}
        </ul>
      ) : null}
    </div>
  );
}
