import { createContext, useContext, type ReactNode } from 'react';
import { QueryClientProvider } from '@tanstack/react-query';
import { KernelProvider } from '@/kernel';
import { I18nProvider } from '@/i18n';
import { HttpProvider } from '@/data/http';
import { SessionProvider } from '@/state/session';
import { ConnectivityProvider } from '@/platform/connectivity';
import type { AppContainer } from './container';

const ContainerContext = createContext<AppContainer | null>(null);

/** The composition root in React: every provider in one place (ARCHITECTURE §2 T02). */
export function AppProviders({ container: c, children }: { container: AppContainer; children: ReactNode }): JSX.Element {
  return (
    <ContainerContext.Provider value={c}>
      <KernelProvider kernel={c.kernel}>
        <I18nProvider>
          <SessionProvider store={c.session}>
            <HttpProvider services={c.dataServices}>
              <QueryClientProvider client={c.queryClient}>
                <ConnectivityProvider value={c.connectivity}>{children}</ConnectivityProvider>
              </QueryClientProvider>
            </HttpProvider>
          </SessionProvider>
        </I18nProvider>
      </KernelProvider>
    </ContainerContext.Provider>
  );
}

/** Services the shell needs beyond the module providers (telemetry, health, LED detector, reload). app/* only. */
export function useAppContainer(): AppContainer {
  const c = useContext(ContainerContext);
  if (!c) throw new Error('AppProviders missing');
  return c;
}
