import { byStart, type Booking } from '@/domain/booking-model';
import type { QueryClient } from '@tanstack/react-query';
import type { BookingsDayScope } from './query-keys';

/**
 * Read vs event race (ADR-0004 addendum, RK-TA-3): every booking patch gets a sequence number; a day read remembers
 * the sequence at its start and re-applies the patches recorded while it was in flight over its answer (deletes win).
 */
export type BookingPatch =
  | { kind: 'insert'; booking: Booking; filter: (b: Booking, s: BookingsDayScope) => boolean }
  | { kind: 'replace'; booking: Booking }
  | { kind: 'map'; id: string; fn: (b: Booking) => Booking }
  | { kind: 'remove'; id: string };

interface Entry {
  seq: number;
  generation: number;
  patch: BookingPatch;
}

interface Journal {
  seq: number;
  inFlight: number;
  entries: Entry[];
}

const journals = new WeakMap<QueryClient, Journal>();

function journalOf(qc: QueryClient): Journal {
  let j = journals.get(qc);
  if (!j) {
    j = { seq: 0, inFlight: 0, entries: [] };
    journals.set(qc, j);
  }
  return j;
}

/** Applies one patch to one day list; returns the same array when nothing changed. */
export function applyPatch(list: readonly Booking[], patch: BookingPatch, scope: BookingsDayScope): readonly Booking[] {
  const idx = list.findIndex((b) => b.id === (patch.kind === 'insert' || patch.kind === 'replace' ? patch.booking.id : patch.id));
  switch (patch.kind) {
    case 'insert':
      return idx >= 0 || !patch.filter(patch.booking, scope) ? list : [...list, patch.booking].sort(byStart);
    case 'replace':
      return idx < 0 ? list : list.map((b, i) => (i === idx ? patch.booking : b)).sort(byStart);
    case 'map':
      return idx < 0 ? list : list.map((b, i) => (i === idx ? patch.fn(b) : b)).sort(byStart);
    case 'remove':
      return idx < 0 ? list : list.filter((_, i) => i !== idx);
  }
}

export function recordPatch(qc: QueryClient, generation: number, patch: BookingPatch): void {
  const j = journalOf(qc);
  j.seq += 1;
  if (j.inFlight > 0) j.entries.push({ seq: j.seq, generation, patch });
}

/** Call when a day read starts; returns its start sequence. */
export function beginRead(qc: QueryClient): number {
  const j = journalOf(qc);
  j.inFlight += 1;
  return j.seq;
}

/** Re-applies patches recorded after `startSeq` (same generation) to a fresh answer, then closes the read. */
export function finishRead(qc: QueryClient, startSeq: number, generation: number, scope: BookingsDayScope, list: readonly Booking[] | null): Booking[] {
  const j = journalOf(qc);
  let out: readonly Booking[] = list ?? [];
  if (list) for (const e of j.entries) if (e.seq > startSeq && e.generation === generation) out = applyPatch(out, e.patch, scope);
  j.inFlight = Math.max(0, j.inFlight - 1);
  if (j.inFlight === 0) j.entries = [];
  return [...out];
}
