import i18next, { type i18n as I18nInstance } from 'i18next';
import ICU from 'i18next-icu';
import en from './locales/en.json';
import ru from './locales/ru.json';
import de from './locales/de.json';
import type { I18nKey } from './keys';

/** UI languages of the display (product/reference/i18n.yaml runtime.languages). */
export const LANGUAGES = ['en', 'ru', 'de'] as const;
export type Language = (typeof LANGUAGES)[number];
/** Fallback for a missing key and for an unknown browser language (DEV-D-79: as legacy, fallback en). */
export const FALLBACK_LANGUAGE: Language = 'en';

export type TranslateParams = Record<string, string | number>;

const NAMESPACE = 'display';
export const RESOURCES: Record<Language, typeof en> = { en, ru, de };

let instance: I18nInstance | null = null;

/**
 * Language rule (DEV-D-79 KEEP): the first browser preference mapped en_* → en, ru_* → ru, de_* → de, anything else → en.
 * Not stored, no switcher. [code] fe:src/js/unspot-display.ts:182-190
 */
export function detectLanguage(preferences: readonly string[] | undefined): Language {
  const first = (preferences?.[0] ?? '').toLowerCase().replace('_', '-');
  const base = first.split('-')[0];
  return (LANGUAGES as readonly string[]).includes(base ?? '') ? (base as Language) : FALLBACK_LANGUAGE;
}

function browserPreferences(): readonly string[] {
  if (typeof navigator === 'undefined') return [];
  if (navigator.languages && navigator.languages.length > 0) return navigator.languages;
  return navigator.language ? [navigator.language] : [];
}

function syncHtmlLang(lang: Language): void {
  // DEV-D-79: the html lang attribute follows the active language.
  if (typeof document !== 'undefined') document.documentElement.lang = lang;
}

/**
 * Creates (or re-creates) the i18next instance synchronously. `lang` omitted → detectLanguage(navigator.languages).
 * Call once at boot (app/bootstrap) before the first render; tests call it with an explicit language.
 */
export function initI18n(lang?: Language): I18nInstance {
  const language = lang ?? detectLanguage(browserPreferences());
  const next = i18next.createInstance();
  next.use(ICU).init({
    initAsync: false,
    showSupportNotice: false,
    lng: language,
    fallbackLng: FALLBACK_LANGUAGE,
    supportedLngs: [...LANGUAGES],
    ns: [NAMESPACE],
    defaultNS: NAMESPACE,
    resources: {
      en: { [NAMESPACE]: en },
      ru: { [NAMESPACE]: ru },
      de: { [NAMESPACE]: de },
    },
    keySeparator: '.',
    nsSeparator: false,
    returnNull: false,
    interpolation: { escapeValue: false },
    react: { useSuspense: false },
  });
  instance = next;
  syncHtmlLang(language);
  return next;
}

/** The current instance; initialises with the detected language on first use. */
export function getI18n(): I18nInstance {
  return instance ?? initI18n();
}

export function getLanguage(): Language {
  const lng = getI18n().language;
  return (LANGUAGES as readonly string[]).includes(lng) ? (lng as Language) : FALLBACK_LANGUAGE;
}

/** Switches the UI language (no UI switcher exists; used by boot and tests). */
export function setLanguage(lang: Language): void {
  void getI18n().changeLanguage(lang);
  syncHtmlLang(lang);
}

/** Translate outside React (e.g. telemetry-free error texts). Same output as `useT()`. */
export function translate(key: I18nKey, params?: TranslateParams): string {
  return getI18n().t(key, params ?? {});
}

/** True when `key` resolves to a string in `lang` without falling back. */
export function hasKey(key: string, lang: Language): boolean {
  let node: unknown = RESOURCES[lang];
  for (const part of key.split('.')) {
    if (typeof node !== 'object' || node === null) return false;
    node = (node as Record<string, unknown>)[part];
  }
  return typeof node === 'string';
}
