/** Text with `{…}` / `{{ … }}` placeholders (nested braces allowed) → anchored regex. */
export function textPattern(text: string): RegExp {
  let out = '';
  let depth = 0;
  for (const ch of text.trim()) {
    if (ch === '{') {
      if (depth === 0) out += '[\\s\\S]*?';
      depth++;
    } else if (ch === '}' && depth > 0) depth--;
    else if (depth === 0) out += ch.replace(/[.*+?^$()|[\]\\]/g, '\\$&');
  }
  return new RegExp(`^${out}$`);
}

const COMPILED = CARDS.map((c) => ({ ...c, patterns: c.texts.map(textPattern) }));
const matches = (patterns: readonly RegExp[], text: string | undefined): boolean =>
  text !== undefined && text.split('\n').some((t) => patterns.some((p) => p.test(t.trim())));

/** Card key for a refused answer of `op`, or null when no card matches. */
export function refusalCodeFor(op: string, serverText: string | undefined, fieldErrors?: Record<string, string>): string | null {
  const cards = COMPILED.filter((c) => c.ops.includes(op));
  for (const c of cards) if (c.field && matches(c.patterns, fieldErrors?.[c.field])) return c.code;
  for (const c of cards) if (!c.field && matches(c.patterns, serverText)) return c.code;
  return null;
}

/** Sets `op` and, for a `refused` error, replaces the http code by the refusal card key when the text matches. */
export function refineRefusal(op: string, error: AppError): AppError {
  if (error.kind !== 'refused') return { ...error, op };
  return { ...error, op, code: refusalCodeFor(op, error.serverText, error.fieldErrors) ?? error.code };
}
