import type { ReactNode } from 'react';

/** What a dialog renderer receives: `close(result)` closes this dialog (result undefined = dismissed). */
export interface DialogContext {
  close: (result?: unknown) => void;
}
export type DialogRender = (ctx: DialogContext) => ReactNode;

export interface DialogOptions {
  /** Tap on the overlay closes the dialog (ngDialog closeByDocument, default true). */
  closeOnOverlay?: boolean;
  /** Called once when the dialog closes, with the result (undefined when dismissed or by closeAll). */
  onClose?: (result: unknown) => void;
}

export interface DialogEntry {
  id: number;
  render: DialogRender;
  options: DialogOptions;
}

type Listener = () => void;

let entries: readonly DialogEntry[] = [];
let seq = 0;
const listeners = new Set<Listener>();
const emit = (): void => listeners.forEach((l) => l());

function close(id: number, result?: unknown): void {
  const entry = entries.find((e) => e.id === id);
  if (!entry) return;
  entries = entries.filter((e) => e.id !== id);
  emit();
  entry.options.onClose?.(result);
}

/**
 * App-wide dialog stack rendered by <DialogHost/> (SCR-CONFIRM, SCR-ROOM/ST-QR-MODAL, board dialogs).
 * `closeAll()` is called on `idle.timeout` by DialogHost (TMR-APP-IDLE-HOME) and by the router on navigation.
 */
export const dialogs = {
  open(render: DialogRender, options: DialogOptions = {}): number {
    const id = ++seq;
    entries = [...entries, { id, render, options }];
    emit();
    return id;
  },
  close,
  closeAll(): void {
    const all = entries;
    if (all.length === 0) return;
    entries = [];
    emit();
    all.forEach((e) => e.options.onClose?.(undefined));
  },
  isOpen(): boolean {
    return entries.length > 0;
  },
  /** @internal used by DialogHost */
  subscribe(listener: Listener): () => void {
    listeners.add(listener);
    return () => listeners.delete(listener);
  },
  /** @internal used by DialogHost */
  snapshot(): readonly DialogEntry[] {
    return entries;
  },
};
