import { errorMessageKey, errorMessageText, type TFn } from '@/i18n';
import type { AppError } from '@/kernel';
import { toast } from '@/ui/primitives';

/**
 * Texts to show for a failed write (SCR-ROOM/ST-ERROR-TOAST): none for silent errors (aborted, check-in refusals,
 * DEV-D-88); the field texts of `errors.<field>[]` one per toast when the server sent them (DEV-D-104); otherwise
 * the one text of `errorMessageText` (server text as plain text, DEV-D-37; connection lost, DEV-D-38).
 */
export function errorTexts(e: AppError, t: TFn): string[] {
  const text = errorMessageText(e, t);
  if (text === null) return [];
  if (errorMessageKey(e) === null && e.fieldErrors) {
    const fields = Object.values(e.fieldErrors)
      .flatMap((v) => v.split('\n'))
      .map((v) => v.trim())
      .filter(Boolean);
    if (fields.length) return fields;
  }
  return [text];
}

export function toastError(e: AppError, t: TFn): void {
  for (const text of errorTexts(e, t)) toast.error(text);
}
