import { useCallback, useEffect, useRef } from 'react';
import type { Booking } from '@/domain/booking-model';
import { can, type PermissionContext } from '@/domain/permissions';
import { blockTitles, type TitleText } from '@/domain/room-status';
import { slotFromTap } from '@/domain/booking-slots';
import { useClock } from '@/kernel';
import { useT } from '@/i18n';
import { dialogs } from '@/ui/primitives';
import { QrModal } from '@/ui/qr';
import type { TimelineHandle } from '@/ui/timeline';
import { useUiStore } from '@/state/ui';
import { RoomView } from './room-view';
import type { RoomScreenProps } from './types';
import { useRoomScreen } from './use-room-screen';

const reloadPage = (): void => window.location.reload();

function openQr(link: string): void {
  dialogs.open(({ close }) => <QrModal value={link} onClose={() => close()} />);
}

/**
 * SCR-ROOM — the meeting-room display for today. Container: queries, the `status-5s` evaluation (domain/room-status),
 * state/ui; renders `RoomView`. The booking actions come in as the `bookingPanel` slot (composition, ARCHITECTURE §3).
 */
export function RoomScreen({ bookingPanel: Panel, menuSlot, onReload = reloadPage }: RoomScreenProps): JSX.Element {
  const t = useT();
  const clock = useClock();
  const m = useRoomScreen();
  const { data, view, now, zone } = m;
  const timeline = useRef<TimelineHandle>(null);
  const scrollSeq = useUiStore((s) => s.scrollToNowSeq);
  useEffect(() => timeline.current?.scrollToNow(), [m.loadedDay, scrollSeq]);

  const pc = (booking: Booking | null): PermissionContext | null =>
    data ? { abilities: data.abilities, room: { isShared: data.statusRoom.isShared, privacyLevel: data.statusRoom.privacyLevel }, booking, now } : null;
  const ctx = pc(null);
  const text = useCallback((x: TitleText | null): string | null => (x === null ? null : 'text' in x ? x.text : t(x.key)), [t]);
  const titlesOf = (b: Booking) => {
    if (!ctx || !data) return { main: null, secondary: null };
    const r = blockTitles(b, { roomName: data.room.name, room: ctx.room, abilities: ctx.abilities, now });
    return { main: text(r.main), secondary: text(r.secondary) };
  };
  const onSlotTap = (tapAt: number): void => {
    if (!data) return;
    const slot = slotFromTap({ tapAt, now: clock.now(), bookings: m.bookings, workingRanges: m.workingRanges, limits: data.room });
    const ui = useUiStore.getState();
    ui.selectBooking(null);
    if (slot) ui.openForm(slot);
  };
  const onBookingTap = (b: Booking): void => {
    const c = pc(b);
    if (c && can('select-booking', c)) useUiStore.getState().selectBooking(b.id);
  };

  return (
    <RoomView
      view={view}
      now={now}
      zone={zone}
      hour12={data?.hour12 ?? false}
      american={data?.american ?? false}
      room={{ name: data?.room.name ?? '', capacity: data?.room.capacity ?? null }}
      logo={data?.logo ?? null}
      backgroundImage={data?.backgroundImage ?? null}
      qr={data?.qr ?? null}
      dayRange={m.dayRange}
      workingRanges={m.workingRanges}
      bookings={m.bookings}
      titlesOf={titlesOf}
      onSlotTap={ctx && can('slot-tap', ctx) ? onSlotTap : undefined}
      onBookingTap={view?.canSelectBooking ? onBookingTap : undefined}
      updatedAt={m.updatedAt}
      menuSlot={menuSlot}
      onReload={onReload}
      onOpenQr={openQr}
      timelineRef={timeline}
      renderPanel={(part) =>
        data && view ? (
          <Panel part={part} view={view} now={now} zone={zone} hour12={data.hour12} room={data.room} bookings={m.bookings} workingRanges={m.workingRanges} checkin={data.checkin} />
        ) : null
      }
    />
  );
}
