import logoUrl from '../../assets/img/unspot-logo.svg';
import inverseLogoUrl from '../../assets/img/unspot-inverse-logo.svg';
import reloadIconUrl from '../../assets/img/reload-button-icon.svg';
import arrowDownIconUrl from '../../assets/img/arrow-down-icon.svg';

/** Room status tones of the room screen (status_colours.table; legacy enum names, LED statuses use the same names). */
export const STATUS_TONES = ['FREE', 'OCCUPIED', 'CHECKIN', 'BOOKING_SELECTED'] as const;
export type StatusTone = (typeof STATUS_TONES)[number];

/**
 * Props for a screen root that sets the status accent: `<div {...statusToneAttrs(tone)}>`. Inside it CSS uses
 * `var(--status-accent)` and `var(--status-block)`; without it (or with null) the FREE pair applies (ST-LOADING).
 */
export function statusToneAttrs(tone: StatusTone | null | undefined): { 'data-status'?: StatusTone } {
  return tone ? { 'data-status': tone } : {};
}

/** CSS variable names exposed by theme.css (use as `var(...)` in CSS Modules). */
export const THEME_VARS = {
  statusAccent: '--status-accent',
  statusBlock: '--status-block',
  statusSelectedBlock: '--status-selected-block',
} as const;

/** Bundled images (URLs resolved by Vite): TOK-COMPANY-LOGO fallback, activation logo, reload and dropdown icons. */
export const ASSETS = {
  logo: logoUrl,
  inverseLogo: inverseLogoUrl,
  reloadIcon: reloadIconUrl,
  arrowDownIcon: arrowDownIconUrl,
} as const;

export interface TenantLook {
  subDomain?: string;
}

/**
 * No-op by design: the register has no per-tenant theme (design-tokens.yaml per_tenant_rule; the Skoltech theme never
 * loads, TOK-THEME-SKOLTECH; dark theme for all tenants, DEV-D-70/-71). Tenant visuals are data only: company white logo
 * and device background image, rendered by the screens. Kept as the seam named in ARCHITECTURE §2 (T26).
 */
export function applyTenantTheme(tenant?: TenantLook): void {
  void tenant; // intentionally no effect
}
