import { appError, err, ok, type AppError, type Clock, type Result } from '@/kernel';

/** OP-RT-TOKEN answer. `exp` = JWT `exp` claim in epoch seconds; omitted/0 → read from the token, else cached 30 s. */
export interface RealtimeToken {
  token: string;
  exp?: number;
}

/** Timings of OP-RT-TOKEN caching (legacy mercure-token.service). */
const EARLY_REFRESH_MS = 5 * 60_000;
const FALLBACK_MS = 30_000;

/** `exp` claim (epoch seconds) of a JWT, 0 when unreadable. Base64url decode, no library (mapping: angular-jwt). */
export function jwtExp(token: string): number {
  const part = token.split('.')[1];
  if (!part) return 0;
  try {
    const b64 = part.replace(/-/g, '+').replace(/_/g, '/');
    const payload = JSON.parse(atob(b64 + '='.repeat((4 - (b64.length % 4)) % 4))) as { exp?: unknown };
    return Number(payload.exp) || 0;
  } catch {
    return 0;
  }
}

export interface TokenCache {
  get(): Promise<Result<string, AppError>>;
  clear(): void;
}

/** OP-RT-TOKEN: reused until exp − 5 min; one shared request for parallel callers; `clear()` also orphans an in-flight one. */
export function createTokenCache(getToken: () => Promise<Result<RealtimeToken, AppError>>, clock: Clock): TokenCache {
  let cached: { token: string; expMs: number } | null = null;
  let inFlight: Promise<Result<string, AppError>> | null = null;
  let epoch = 0;
  return {
    get() {
      if (cached && clock.now() < cached.expMs - EARLY_REFRESH_MS) return Promise.resolve(ok(cached.token));
      if (inFlight) return inFlight;
      const mine = epoch;
      const request = getToken()
        .catch((): Result<RealtimeToken, AppError> => err(appError('unreachable', 'unreachable', { op: 'OP-RT-TOKEN' })))
        .then((r): Result<string, AppError> => {
          if (mine !== epoch) return r.ok ? ok(r.value.token) : r;
          inFlight = null;
          if (!r.ok) return r;
          const exp = r.value.exp || jwtExp(r.value.token);
          cached = { token: r.value.token, expMs: exp > 0 ? exp * 1000 : clock.now() + FALLBACK_MS };
          return ok(r.value.token);
        });
      inFlight = request;
      return request;
    },
    clear() {
      cached = null;
      inFlight = null;
      epoch += 1;
    },
  };
}
