import type { Booking, DateRange } from '@/domain/booking-model';

/** Room detail durations in minutes (null = not set). */
export interface RoomBookingLimits {
  defaultBookingDuration: number | null;
  maxBookingDuration: number | null;
}

/** RULE-SLOT-FREE-FOR: `minutes` is a REAL number from the start of the current minute; `until` = next unavailable moment. */
export interface FreeTime {
  minutes: number;
  until: number;
}

export interface QuickOptionsInput {
  /** Uncapped free minutes (FreeTime.minutes, 0 when none). */
  freeMinutes: number;
  limits: RoomBookingLimits;
  /** can('quick-book') — abilityToBook and not a shared room. */
  canQuickBook: boolean;
  /** Room meetingTitleRequired. */
  titleRequired: boolean;
  /** A quick booking request is in flight. */
  inFlight: boolean;
}

/** The quick-booking block of body A; null = no block at all (Another hidden too). */
export interface QuickOptions {
  durations: number[];
  another: boolean;
  /** DT-QUICK-07: a duration tap opens the form with that length instead of booking. */
  opensForm: boolean;
  /** DT-QUICK-08: duration buttons disabled ("Another" stays enabled). */
  disabled: boolean;
}

export const MINUTE = 60_000;
export const QUICK_DURATIONS: readonly number[] = [15, 30, 60];
export const DEFAULT_LENGTH_MIN = 30;
export const BOOK_AFTER_MIN_FREE = 5;
export const BOOK_AFTER_LENGTH_MIN = 30;

export const startOfMinute = (ms: number): number => Math.floor(ms / MINUTE) * MINUTE;

/** RULE-SLOT-FREE-FOR: next booking start (earliest booking with end > now), else end of the working range containing now. */
export function freeTime(bookings: readonly Booking[], workingRanges: readonly DateRange[], now: number): FreeTime | null {
  const ahead = bookings.filter((b) => b.end > now).sort((a, b) => a.start - b.start)[0];
  const until = ahead ? ahead.start : workingRanges.find((r) => r.start <= now && now < r.end)?.end;
  if (until === undefined) return null;
  const minutes = (until - startOfMinute(now)) / MINUTE;
  return minutes > 0 ? { minutes, until } : null;
}

/** RULE-SLOT-FREE-CAP: minutes used for the quick options are capped at maxBookingDuration. */
export function cappedFreeMinutes(freeMinutes: number, limits: RoomBookingLimits): number {
  return limits.maxBookingDuration ? Math.min(freeMinutes, limits.maxBookingDuration) : freeMinutes;
}

/**
 * DT-QUICK-01..08: block shown when capped free minutes > 14 and can('quick-book'); a duration N is offered when it
 * fits (DEV-D-133 CHANGE: floor(now + N) <= next unavailable moment, i.e. capped free minutes >= N).
 */
export function quickOptions(input: QuickOptionsInput): QuickOptions | null {
  const capped = cappedFreeMinutes(input.freeMinutes, input.limits);
  if (!input.canQuickBook || !(capped > 14)) return null;
  return {
    durations: QUICK_DURATIONS.filter((n) => capped >= n),
    another: true,
    opensForm: input.titleRequired,
    disabled: input.inFlight,
  };
}

/** RULE-SLOT-QUICK-REQUEST (DEV-D-126 KEEP): start = now with seconds, end = (now + N min) floored to the minute. */
export function quickBookingRange(now: number, minutes: number): DateRange {
  return { start: now, end: startOfMinute(now + minutes * MINUTE) };
}

function subtract(ranges: DateRange[], cut: DateRange): DateRange[] {
  return ranges.flatMap((r) => {
    if (cut.end <= r.start || cut.start >= r.end) return [r];
    return [
      { start: r.start, end: cut.start },
      { start: cut.end, end: r.end },
    ].filter((p) => p.end > p.start);
  });
}

/**
 * RULE-SLOT-FREE-RANGES: working ranges from `from` minus every booking that ends after `from` (booking end floored
 * to the minute); empty pieces dropped, sorted by start.
 */
export function freeSlots(bookings: readonly Booking[], workingRanges: readonly DateRange[], from: number): DateRange[] {
  let free = workingRanges.filter((r) => r.end > from).map((r) => ({ start: Math.max(r.start, from), end: r.end }));
  for (const b of bookings) {
    if (b.end > from) free = subtract(free, { start: b.start, end: startOfMinute(b.end) });
  }
  return free.filter((r) => r.end > r.start).sort((a, b) => a.start - b.start);
}

/** RULE-SLOT-DEFAULT-LENGTH: room default or 30 min, capped at maxBookingDuration. */
export function defaultLength(limits: RoomBookingLimits): number {
  const len = limits.defaultBookingDuration ?? DEFAULT_LENGTH_MIN;
  return limits.maxBookingDuration ? Math.min(len, limits.maxBookingDuration) : len;
}

/** The range cut to at most `minutes` from its start. */
export function cutTo(range: DateRange, minutes: number | null): DateRange {
  if (minutes === null) return range;
  return { start: range.start, end: Math.min(range.end, range.start + minutes * MINUTE) };
}

/** RULE-SLOT-FORM-OPEN: first free slot from now cut to `minutes` ('Another': defaultLength; quick with title: N). */
export function initialFormRange(bookings: readonly Booking[], workingRanges: readonly DateRange[], now: number, minutes: number): DateRange | null {
  const first = freeSlots(bookings, workingRanges, now)[0];
  return first ? cutTo(first, minutes) : null;
}

/** First free slot after `booking` (from its end, or from now for a booking that has ended). */
function slotAfter(booking: DateRange, bookings: readonly Booking[], workingRanges: readonly DateRange[], now: number): DateRange | null {
  return freeSlots(bookings, workingRanges, Math.max(booking.end, now))[0] ?? null;
}

/** RULE-SLOT-BOOK-AFTER-AVAILABLE (time part): the first free slot after the booking is >= 5 minutes. */
export function bookAfterAvailable(booking: DateRange, bookings: readonly Booking[], workingRanges: readonly DateRange[], now: number): boolean {
  const slot = slotAfter(booking, bookings, workingRanges, now);
  return slot !== null && slot.end - slot.start >= BOOK_AFTER_MIN_FREE * MINUTE;
}

/** RULE-SLOT-BOOK-AFTER-RANGE with DEV-D-58 CHANGE: first free slot after the booking cut to 30 min and to maxBookingDuration. */
export function bookAfterRange(
  booking: DateRange,
  bookings: readonly Booking[],
  workingRanges: readonly DateRange[],
  now: number,
  limits: RoomBookingLimits,
): DateRange | null {
  const slot = slotAfter(booking, bookings, workingRanges, now);
  if (!slot) return null;
  const max = limits.maxBookingDuration ? Math.min(BOOK_AFTER_LENGTH_MIN, limits.maxBookingDuration) : BOOK_AFTER_LENGTH_MIN;
  return cutTo(slot, max);
}

/** RULE-STATUS-PRE / RULE-SLOT-FORM-LIFETIME: a selected range starting in the past moves to now; null when it no longer has length. */
export function moveRangeToNow(range: DateRange, now: number): DateRange | null {
  const start = Math.max(range.start, now);
  return range.end > start ? { start, end: range.end } : null;
}
