import { QueryClient } from '@tanstack/react-query';

/**
 * ADR-0004 §1 defaults: no library retries, no focus/reconnect refetch, no refetchInterval (time is owned by the
 * scheduler: `startBookingsJobs`). Data stays fresh until a job, an event or a command invalidates or patches it.
 * networkMode 'always': the kiosk's own connectivity logic decides, not navigator.onLine.
 */
export function createQueryClient(): QueryClient {
  return new QueryClient({
    defaultOptions: {
      queries: {
        retry: false,
        refetchOnWindowFocus: false,
        refetchOnReconnect: false,
        refetchInterval: false,
        staleTime: Infinity,
        networkMode: 'always',
      },
      mutations: { retry: false, networkMode: 'always' },
    },
  });
}
