import type { Booking } from '@/domain/booking-model';

/** Device abilities from `me.device` (read once per boot, DEV-D-51). */
export interface DeviceAbilities {
  abilityToBook: boolean;
  abilityToStop: boolean;
  abilityToCheckin: boolean;
  abilityToCheckinByQR: boolean;
}

/** Room flags the rules read (room detail: isSharedRoom, privacyLevel 0/1/2 or null). */
export interface PermissionRoom {
  isShared: boolean;
  privacyLevel: number | null;
}

export interface PermissionContext {
  abilities: DeviceAbilities;
  room: PermissionRoom;
  /** The booking acted on (booking actions and visibility). */
  booking?: Booking | null;
  /** Evaluation instant (epoch ms) — the same `now` as the status of this tick (DEV-D-134). */
  now: number;
}

export type PermissionAction =
  | 'quick-book'
  | 'open-form'
  | 'slot-tap'
  | 'book-after'
  | 'stop'
  | 'delete'
  | 'check-in'
  | 'room-qr'
  | 'checkin-qr'
  | 'select-booking'
  | 'menu'
  | 'reload'
  | 'see-title'
  | 'see-organizer';

export const ALL_ABILITIES: DeviceAbilities = { abilityToBook: true, abilityToStop: true, abilityToCheckin: true, abilityToCheckinByQR: true };
export const NO_ABILITIES: DeviceAbilities = { abilityToBook: false, abilityToStop: false, abilityToCheckin: false, abilityToCheckinByQR: false };

/** RULE-PERM-READONLY: !abilityToBook || isSharedRoom. */
export function isReadOnly(abilities: DeviceAbilities, room: PermissionRoom): boolean {
  return !abilities.abilityToBook || room.isShared;
}

/** PERM-19: the event title may be shown (display-made: always; else booking.isVisible, resolved by the mapper, DEV-D-86). */
function titleVisible(b: Booking, room: PermissionRoom): boolean {
  return !room.isShared && (b.madeByDisplay || b.isVisible);
}

type Rule = (c: PermissionContext, b: Booking | null) => boolean;

const notShared: Rule = (c) => !c.room.isShared;
const withBooking = (rule: (c: PermissionContext, b: Booking) => boolean): Rule => (c, b) => b !== null && rule(c, b);

/** One row per action; the PERM ids and deviations each row implements are in permissions CLAUDE.md. */
const RULES: Record<PermissionAction, Rule> = {
  'quick-book': (c) => !isReadOnly(c.abilities, c.room),
  'open-form': (c) => !isReadOnly(c.abilities, c.room),
  'slot-tap': (c) => !isReadOnly(c.abilities, c.room),
  'book-after': withBooking((c) => !isReadOnly(c.abilities, c.room)),
  stop: withBooking((c, b) => c.abilities.abilityToStop && !c.room.isShared && b.start <= c.now && c.now < b.end),
  delete: withBooking((c, b) => b.madeByDisplay && !c.room.isShared && c.now < b.start),
  'check-in': withBooking((c) => c.abilities.abilityToCheckin),
  'room-qr': (c) => c.abilities.abilityToCheckinByQR && !c.room.isShared,
  'checkin-qr': withBooking((c) => c.abilities.abilityToCheckinByQR && !c.room.isShared),
  'select-booking': withBooking(notShared),
  menu: notShared,
  reload: () => true,
  'see-title': withBooking((c, b) => titleVisible(b, c.room)),
  'see-organizer': withBooking(
    (c, b) => !c.room.isShared && (titleVisible(b, c.room) || c.room.privacyLevel === 0 || c.room.privacyLevel === 1),
  ),
};

/** Is `action` offered in the UI? (RULE-PERMISSIONS; every refusable control asks this, room screen and board alike.) */
export function can(action: PermissionAction, ctx: PermissionContext): boolean {
  return RULES[action](ctx, ctx.booking ?? null);
}
