import { useCallback, useEffect } from 'react';
import { BrowserRouter, Navigate, Route, Routes, useLocation } from 'react-router-dom';
import { useCompanySettingsQuery, useMeQuery } from '@/data/queries';
import { useSession } from '@/state/session';
import { UiIdleWatcher } from '@/state/ui';
import { DialogHost, dialogs, ToastHost } from '@/ui/primitives';
import { ActivationScreen } from '@/features/activation';
import { KioskRuntime } from '@/features/kiosk-runtime';
import { useAppContainer } from '@/app/providers';
import { AnonymousOnly, BoardPage, ReadyOnly, RoomPage } from './guards';
import { ROUTES } from './routes';

/** React Router v7 behaviour now (silences the v6 future warnings; no route here depends on the old behaviour). */
export const ROUTER_FUTURE = { v7_startTransition: true, v7_relativeSplatPath: true } as const;

/** Route table (legacy paths kept); unknown URLs → /spaces/view, which the guards send to /login when not activated. */
export function AppRoutes(): JSX.Element {
  const { reload } = useAppContainer();
  const onActivated = useCallback(() => reload('login'), [reload]);
  return (
    <Routes>
      <Route path={ROUTES.login} element={<AnonymousOnly><ActivationScreen onActivated={onActivated} /></AnonymousOnly>} />
      <Route path={ROUTES.spacesView} element={<Navigate to={ROUTES.room} replace />} />
      <Route path={ROUTES.room} element={<ReadyOnly><RoomPage /></ReadyOnly>} />
      <Route path={ROUTES.board} element={<ReadyOnly><BoardPage /></ReadyOnly>} />
      <Route path="*" element={<Navigate to={ROUTES.spacesView} replace />} />
    </Routes>
  );
}

/** Shell inside a router: kiosk runtime around the screens; dialogs, toasts and the idle detector mounted once. */
export function AppShell(): JSX.Element {
  const c = useAppContainer();
  const { pathname } = useLocation();
  useEffect(() => {
    dialogs.closeAll(); // legacy closeByNavigation
  }, [pathname]);
  const ready = useSession((s) => s.status === 'ready');
  const me = useMeQuery();
  const settings = useCompanySettingsQuery();
  const hasRoom = ready && !!me.data?.device?.space;
  // Display zone: room timezone → company default (ADR-0004 §5); the boot init sets it on the clock.
  const zone = me.data?.device?.space?.timezone || settings.data?.defaultTimezone || undefined;
  return (
    <>
      <KioskRuntime telemetry={c.telemetry} reload={c.reload} health={c.health} homePath={hasRoom ? ROUTES.room : null} zone={zone}>
        <AppRoutes />
      </KioskRuntime>
      <DialogHost />
      <ToastHost />
      <UiIdleWatcher />
    </>
  );
}

/** ADR-0005 §1: basename = Vite base (`/` on the display host, `/display-web-2-hosting/` on the preview). */
export function AppRouter({ basename = import.meta.env.BASE_URL }: { basename?: string }): JSX.Element {
  return (
    <BrowserRouter basename={basename} future={ROUTER_FUTURE}>
      <AppShell />
    </BrowserRouter>
  );
}
