import { formatInTimeZone } from 'date-fns-tz';
import { de as deLocale, enUS, ru as ruLocale } from 'date-fns/locale';
import type { Locale } from 'date-fns';
import { getLanguage, getI18n, type Language } from './i18n';

const DATE_LOCALES: Record<Language, Locale> = { en: enUS, ru: ruLocale, de: deLocale };

export interface TimeFormatOptions {
  /** Company timeFormat "12 hour" (american): 'hh:mm am'. Default 24 h 'HH:mm'. */
  hour12?: boolean;
}

export interface DateFormatOptions {
  /** Company dateFormat american: month before day ('November 24'). */
  american?: boolean;
  /** 'dd.MM.yyyy' (used by SPACE.LAST_UPDATED_WITH_DATE; legacy ignores the american order here). */
  numeric?: boolean;
}

/**
 * Wall time of `ms` in `zone`: 'HH:mm', or 'hh:mm am|pm' for 12-hour companies (legacy localeDateTimeFormatter
 * 'HH:mm a'; meridiem is always latin lower-case am/pm, ru forced to am/pm too — DEV-D-79). `lang` is accepted for
 * symmetry; digits do not depend on it.
 */
export function formatTime(ms: number, zone: string, _lang?: Language, opts: TimeFormatOptions = {}): string {
  return formatInTimeZone(ms, zone, opts.hour12 ? 'hh:mm aaa' : 'HH:mm', { locale: enUS });
}

/**
 * Date of `ms` in `zone`: header 'dd MMMM' ('24 November' / '24 ноября' / '24 November'), american 'MMMM dd',
 * numeric 'dd.MM.yyyy'. Month names in the UI language (lower-case in ru; the header capitalises by CSS).
 */
export function formatDate(ms: number, zone: string, lang: Language = getLanguage(), opts: DateFormatOptions = {}): string {
  if (opts.numeric) return formatInTimeZone(ms, zone, 'dd.MM.yyyy');
  return formatInTimeZone(ms, zone, opts.american ? 'MMMM dd' : 'dd MMMM', { locale: DATE_LOCALES[lang] });
}

/**
 * Free-time duration of SPACE.FREE_UNTIL {FOR}: legacy moment-duration-format template
 * `h [SPACE.H] mm [SPACE.MIN]` with trim 'both' (fe:…/space-view.component.ts:898-902):
 * 97 → '1 h 37 mins', 125 → '2 h 05 mins', 120 → '2 h', 38 → '38 mins', 1 → '1 min'.
 * Fractional minutes are rounded (moment-duration-format default). In en the plugin pluralises the 'min' label
 * ([stand] parity/baseline CP-01 "1 h 13 mins", ST1 "5 h 12 mins"); other languages keep SPACE.MIN as is.
 */
export function formatRemain(minutes: number, lang: Language = getLanguage()): string {
  const total = Math.max(0, Math.round(minutes));
  const h = Math.floor(total / 60);
  const m = total % 60;
  const t = getI18n().getFixedT(lang);
  const hLabel = t('SPACE.H');
  const minBase = t('SPACE.MIN');
  const minLabel = lang === 'en' && minBase === 'min' && m !== 1 ? 'mins' : minBase;
  if (h > 0 && m > 0) return `${h} ${hLabel} ${String(m).padStart(2, '0')} ${minLabel}`;
  if (h > 0) return `${h} ${hLabel}`;
  return `${m} ${minLabel}`;
}
