/** Port (T30): one server-sent-events stream. Adapter over EventSource; fake in tests. */
export interface RealtimeStreamHandlers {
  onOpen(): void;
  /** Raw `data` of a message frame. */
  onMessage(data: string): void;
  /** Stream error or end (a clean EOF from the hub is reported here too). */
  onError(): void;
}

export interface RealtimeConnection {
  close(): void;
}

export interface RealtimeTransport {
  open(url: string, handlers: RealtimeStreamHandlers): RealtimeConnection;
}

type EventSourceCtor = new (url: string) => Pick<EventSource, 'close' | 'addEventListener'>;

/** EventSource adapter. On error the source is closed at once: the client owns reconnecting (TMR-MERCURE-RECONNECT). */
export function createEventSourceTransport(Ctor: EventSourceCtor = EventSource): RealtimeTransport {
  return {
    open(url, handlers) {
      const source = new Ctor(url);
      source.addEventListener('open', () => handlers.onOpen());
      source.addEventListener('message', (e) => handlers.onMessage(String((e as MessageEvent).data)));
      source.addEventListener('error', () => {
        source.close();
        handlers.onError();
      });
      return { close: () => source.close() };
    },
  };
}
