import { useId, type ReactNode } from 'react';
import { Button, type ButtonVariant } from './button';
import { Dialog } from './dialog';
import { dialogs } from './dialogs';
import styles from './dialog.module.css';

export interface ConfirmDialogProps {
  /** Already translated, plain text (DEV-D-37), e.g. t('SPACE.DO_YOU_WANT_TO_DELETE_BOOKING'). */
  question: string;
  confirmLabel: string;
  cancelLabel: string;
  confirmIcon?: ReactNode;
  confirmVariant?: ButtonVariant;
  onConfirm: () => void;
  onCancel: () => void;
}

/** SCR-CONFIRM room-screen variant: question (h4), confirm (warning) + cancel (secondary outline), close X. */
export function ConfirmDialog({ question, confirmLabel, cancelLabel, confirmIcon, confirmVariant = 'warning', onConfirm, onCancel }: ConfirmDialogProps): JSX.Element {
  const id = useId();
  return (
    <Dialog labelledBy={id} onClose={onCancel} className={styles.confirm}>
      <h4 id={id} className={styles.question}>
        {question}
      </h4>
      <div className={styles.footer}>
        <Button variant={confirmVariant} icon={confirmIcon} onClick={onConfirm}>
          {confirmLabel}
        </Button>
        <Button variant="secondary-outline" onClick={onCancel}>
          {cancelLabel}
        </Button>
      </div>
    </Dialog>
  );
}

export type ConfirmOptions = Omit<ConfirmDialogProps, 'onConfirm' | 'onCancel'>;

/**
 * Opens a ConfirmDialog through the DialogHost. Resolves true only on confirm; false on cancel, X, overlay tap,
 * Escape, closeAll (legacy: closePromise.value !== true → nothing). The dialog closes BEFORE the caller sends the
 * request (SCR-ROOM/ST-CONFIRM in_flight).
 */
export function confirmDialog(options: ConfirmOptions): Promise<boolean> {
  return new Promise((resolve) => {
    dialogs.open(
      ({ close }) => <ConfirmDialog {...options} onConfirm={() => close(true)} onCancel={() => close(false)} />,
      { onClose: (result) => resolve(result === true) },
    );
  });
}
