import type { EventBus } from '@/kernel';
import { SKIP_WAITING, isApiCacheName } from './sw-rules';

type SwContainer = Pick<ServiceWorkerContainer, 'register' | 'addEventListener' | 'controller'>;

export interface RegisterServiceWorkerOptions {
  /** Vite base (`import.meta.env.BASE_URL`): worker at `<base>sw.js`, scope `<base>` (ADR-0005 §1). */
  base?: string;
  /** Build env `VITE_SW`: 'off' disables registration. Default: `import.meta.env.VITE_SW !== 'off'`. */
  enabled?: boolean;
  /** RLD-SW-UPDATE: called once when the worker this page activated takes control. Default: `location.reload()`. */
  onUpdateReady?: () => void;
  /** Registration failure (the page keeps working without a worker). Default: console.warn. */
  onError?: (error: unknown) => void;
  /** Test seam; default `navigator.serviceWorker`. */
  container?: SwContainer;
}

function envEnabled(): boolean {
  return import.meta.env.VITE_SW !== 'off';
}

function afterLoad(): Promise<void> {
  if (typeof document === 'undefined' || document.readyState === 'complete') return Promise.resolve();
  return new Promise((resolve) => window.addEventListener('load', () => resolve(), { once: true }));
}

/**
 * SW-UPDATE / DEV-D-31 page side: register after window load, call update(); a waiting worker gets SKIP_WAITING; a worker
 * that finishes installing while the page is controlled gets SKIP_WAITING; `onUpdateReady` once on a controllerchange
 * this page asked for. Never throws; resolves null when disabled, unsupported or failed.
 */
export async function registerServiceWorker(options: RegisterServiceWorkerOptions = {}): Promise<ServiceWorkerRegistration | null> {
  const enabled = options.enabled ?? envEnabled();
  const container = options.container ?? (typeof navigator !== 'undefined' ? navigator.serviceWorker : undefined);
  if (!enabled || !container) return null;
  const base = (options.base ?? import.meta.env.BASE_URL ?? '/').replace(/\/?$/, '/');
  const onError = options.onError ?? ((e: unknown) => console.warn('[sw] registration failed', e));
  const onUpdateReady = options.onUpdateReady ?? (() => window.location.reload());
  let requested = false;
  let reloaded = false;

  try {
    await afterLoad();
    container.addEventListener('controllerchange', () => {
      if (!requested || reloaded) return;
      reloaded = true;
      onUpdateReady();
    });
    const activate = (reg: ServiceWorkerRegistration): void => {
      if (!reg.waiting) return;
      requested = true;
      reg.waiting.postMessage(SKIP_WAITING);
    };
    const reg = await container.register(`${base}sw.js`, { scope: base });
    reg.update().catch(onError);
    activate(reg);
    reg.addEventListener('updatefound', () => {
      const installing = reg.installing;
      installing?.addEventListener('statechange', () => {
        if (installing.state === 'installed' && container.controller) activate(reg);
      });
    });
    return reg;
  } catch (e) {
    onError(e);
    return null;
  }
}

/** DEV-D-30: delete every API cache (all builds + legacy `api-3.17.16`). Resolves with the number deleted; never rejects. */
export async function purgeApiCache(cacheStorage: CacheStorage | undefined = globalThis.caches): Promise<number> {
  if (!cacheStorage) return 0;
  try {
    const doomed = (await cacheStorage.keys()).filter(isApiCacheName);
    await Promise.all(doomed.map((n) => cacheStorage.delete(n)));
    return doomed.length;
  } catch {
    return 0;
  }
}

/** Wires DEV-D-30 to the bus: `session.expired` → `purgeApiCache()`. Returns the unsubscribe. */
export function bindApiCachePurge(events: EventBus, cacheStorage?: CacheStorage): () => void {
  return events.on('session.expired', () => void purgeApiCache(cacheStorage ?? globalThis.caches));
}
