import type { Booking, DateRange } from '@/domain/booking-model';
import { byStart } from '@/domain/booking-model';
import { awaitingCheckin, type AwaitingCheckin } from '@/domain/checkin-windows';
import { moveRangeToNow } from '@/domain/booking-slots';
import { can, isReadOnly } from '@/domain/permissions';
import { bookingBody, formBody, freeBody, type BodyContext } from './bodies';
import { ledColour, statusAccent } from './colours';
import type { RoomStatus, RoomStatusInput, RoomStatusView } from './types';

/** RULE-STATUS-CURRENT with DEV-D-134: the first booking (by start) with start <= now < end. */
export function currentBooking(bookings: readonly Booking[], now: number): Booking | null {
  return [...bookings].sort(byStart).find((b) => b.start <= now && now < b.end) ?? null;
}

/** The next booking that starts after now. */
export function nextBooking(bookings: readonly Booking[], now: number): Booking | null {
  return [...bookings].sort(byStart).find((b) => b.start > now) ?? null;
}

/**
 * Status rows read top-down, first match wins (RULE-STATUS-PRECEDENCE): range selected -> FREE (DT-STATUS-04/05,
 * DEV-D-110 KEEP); outside working hours -> OCCUPIED (DT-STATUS-06..09); awaiting check-in -> CHECKIN; another booking
 * selected -> BOOKING_SELECTED (DEV-D-112 KEEP); current -> OCCUPIED; else FREE.
 */
function pickStatus(
  range: DateRange | null,
  isWorkingTime: boolean,
  awaiting: AwaitingCheckin | null,
  selected: Booking | null,
  current: Booking | null,
): RoomStatus {
  if (range) return 'FREE';
  if (!isWorkingTime) return 'OCCUPIED';
  if (awaiting) return 'CHECKIN';
  if (selected && selected.id !== current?.id) return 'BOOKING_SELECTED';
  return current ? 'OCCUPIED' : 'FREE';
}

function loadingView(input: RoomStatusInput): RoomStatusView {
  const pc = { abilities: input.abilities, room: { isShared: input.room.isShared, privacyLevel: input.room.privacyLevel }, now: input.now };
  return {
    status: null,
    accent: statusAccent(null),
    led: null,
    body: 'spinner',
    isWorkingTime: input.workingRanges.some((r) => r.start <= input.now && input.now < r.end),
    current: null,
    next: null,
    selectedBookingId: null,
    selectedRange: null,
    awaiting: null,
    free: null,
    booking: null,
    form: null,
    menu: can('menu', pc),
    readOnly: true,
    canSelectBooking: false,
  };
}

/**
 * One evaluation of the room screen (RULE-STATUS-ENGINE): everything the screen shows for this `now` — status,
 * accent, LED, which body, its texts and buttons. Pure; call it on every tick (status-5s) and after every change.
 */
export function roomStatus(input: RoomStatusInput): RoomStatusView {
  if (input.bookings === null) return loadingView(input);
  const { now, workingRanges, abilities, room } = input;
  const bookings = input.bookings;
  const isWorkingTime = workingRanges.some((r) => r.start <= now && now < r.end);
  const selected = input.selectedBookingId ? (bookings.find((b) => b.id === input.selectedBookingId) ?? null) : null;
  const range = input.selectedRange ? moveRangeToNow(input.selectedRange, now) : null;
  const current = currentBooking(bookings, now);
  const awaiting =
    isWorkingTime && !range ? awaitingCheckin({ bookings, selected, current, settings: input.checkin, now }) : null;
  const status = pickStatus(range, isWorkingTime, awaiting, selected, current);
  const ctx: BodyContext = { input, bookings, current, awaiting, isWorkingTime };
  const shown = range ? null : (selected ?? current ?? awaiting?.booking ?? null);
  const pc = { abilities, room: { isShared: room.isShared, privacyLevel: room.privacyLevel }, now };
  return {
    status,
    accent: statusAccent(status),
    led: ledColour(status),
    body: range ? 'form' : shown ? 'booking' : 'free',
    isWorkingTime,
    current,
    next: nextBooking(bookings, now),
    selectedBookingId: range ? null : (selected?.id ?? null),
    selectedRange: range,
    awaiting,
    free: !range && !shown ? freeBody(ctx) : null,
    booking: shown ? bookingBody(ctx, shown) : null,
    form: range ? formBody(ctx, range) : null,
    menu: can('menu', pc),
    readOnly: isReadOnly(abilities, room),
    canSelectBooking: !room.isShared,
  };
}
