/** Result of every IO call (ADR-0004 addendum). */
export type Result<T, E = AppError> = { ok: true; value: T } | { ok: false; error: E };

export type AppErrorKind = 'refused' | 'unreachable' | 'timeout' | 'invalid-response' | 'outcome-unknown' | 'aborted' | 'unauthorized';

/** codes come from refusal cards in product/contract/operations/display.yaml; `aborted` is never shown (DEV-D-88). */
export interface AppError {
  kind: AppErrorKind;
  code: string;
  op?: string;
  status?: number;
  /** Server text, plain text only (DEV-D-37, -104). */
  serverText?: string;
  fieldErrors?: Record<string, string>;
}

export const ok = <T>(value: T): Result<T, never> => ({ ok: true, value });
export const err = <E = AppError>(error: E): Result<never, E> => ({ ok: false, error });
export const appError = (kind: AppErrorKind, code: string, extra: Partial<AppError> = {}): AppError => ({ kind, code, ...extra });
