import { appError, err, ok, type AppError, type EventBus, type Result, type Scheduler } from '@/kernel';

/** Which origin answers: the tenant API (session), the auth host (config), or an explicit origin (PIN login). */
export type Host = 'tenant' | 'auth' | { origin: string };
export type Method = 'GET' | 'POST' | 'PATCH' | 'DELETE';
export type Query = Record<string, string | number | boolean | null | undefined>;

export interface RequestOptions {
  /** OP-* id of the card (AppError.op). */
  op: string;
  host?: Host;
  query?: Query;
  signal?: AbortSignal;
  timeoutMs?: number;
  /** false: 401 / 404 CLIENT_NOT_FOUND is a plain refusal, no `session.expired` (PIN login DEV-D-11, real-time token). */
  expireSession?: boolean;
}

export interface HttpRequest extends RequestOptions {
  method: Method;
  path: string;
  body?: unknown;
}

/** Success envelope `{message, body}` (envelope.success). */
export interface HttpAnswer {
  status: number;
  message: string | null;
  body: unknown;
}

export type HttpResult = Result<HttpAnswer, AppError>;

export interface HttpClient {
  request(req: HttpRequest): Promise<HttpResult>;
  get(path: string, opts: RequestOptions): Promise<HttpResult>;
  post(path: string, body: unknown, opts: RequestOptions): Promise<HttpResult>;
  patch(path: string, body: unknown, opts: RequestOptions): Promise<HttpResult>;
  delete(path: string, body: unknown, opts: RequestOptions): Promise<HttpResult>;
}

export interface HttpDeps {
  authOrigin: () => string;
  session: () => { apiOrigin: string | null; token: string | null };
  events: EventBus;
  scheduler: Scheduler;
  /** UI language for Accept-Language (DEV-D-80); default 'ru'. */
  language?: () => string;
  fetchFn?: typeof fetch;
  /** navigator.onLine; a write sent while offline is `unreachable`, not `outcome-unknown`. */
  isOnline?: () => boolean;
  timeouts?: { readMs: number; writeMs: number };
}

const DEFAULT_TIMEOUTS = { readMs: 30_000, writeMs: 30_000 };
let seq = 0;

function buildUrl(base: string, path: string, query?: Query): string {
  const qs = Object.entries(query ?? {})
    .filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`)
    .join('&');
  return `${base}${path}${qs ? `?${qs}` : ''}`;
}

/** `errors` of the error envelope → {field: texts joined by \n}; the `code` entry is not a field. */
function fieldErrorsOf(errors: unknown): Record<string, string> | undefined {
  if (!errors || typeof errors !== 'object' || Array.isArray(errors)) return undefined;
  const out: Record<string, string> = {};
  for (const [k, v] of Object.entries(errors as Record<string, unknown>)) {
    if (k === 'code') continue;
    const texts = (Array.isArray(v) ? v : [v]).filter((t): t is string => typeof t === 'string');
    if (texts.length) out[k] = texts.join('\n');
  }
  return Object.keys(out).length ? out : undefined;
}

interface Parsed {
  json: Record<string, unknown> | null;
}

async function readJson(res: Response): Promise<Parsed> {
  const text = await res.text();
  try {
    const v: unknown = JSON.parse(text);
    return { json: v !== null && typeof v === 'object' && !Array.isArray(v) ? (v as Record<string, unknown>) : null };
  } catch {
    return { json: null };
  }
}

function classify(req: HttpRequest, status: number, json: Record<string, unknown> | null, emit: (reason: string) => void): HttpResult {
  const write = req.method !== 'GET';
  const message = typeof json?.message === 'string' ? json.message : null;
  if (status >= 200 && status < 300) {
    if (!json) return err(appError('invalid-response', 'invalid-response', { op: req.op, status }));
    return ok({ status, message, body: json.body ?? null });
  }
  const expire = req.expireSession !== false;
  const errors = json?.errors as { code?: unknown } | undefined;
  const clientNotFound = status === 404 && errors?.code === 'CLIENT_NOT_FOUND';
  if (expire && (status === 401 || clientNotFound)) {
    emit(status === 401 ? 'http_401' : 'http_404'); // DEV-D-21
    return err(appError('unauthorized', clientNotFound ? 'CLIENT_NOT_FOUND' : 'http_401', { op: req.op, status, ...(message ? { serverText: message } : {}) }));
  }
  if (status >= 500 || !json) {
    return err(appError(write && status >= 500 ? 'outcome-unknown' : 'unreachable', `http_${status}`, { op: req.op, status }));
  }
  const fieldErrors = clientNotFound ? undefined : fieldErrorsOf(json.errors);
  return err(
    appError('refused', clientNotFound ? 'CLIENT_NOT_FOUND' : `http_${status}`, {
      op: req.op,
      status,
      ...(message ? { serverText: message } : {}),
      ...(fieldErrors ? { fieldErrors } : {}),
    }),
  );
}

export function createHttpClient(deps: HttpDeps): HttpClient {
  const fetchFn = deps.fetchFn ?? ((input: RequestInfo | URL, init?: RequestInit) => fetch(input, init));
  const timeouts = deps.timeouts ?? DEFAULT_TIMEOUTS;

  const baseOf = (host: Host): { base: string | null; withToken: boolean } => {
    if (host === 'auth') return { base: deps.authOrigin() || null, withToken: false };
    if (host === 'tenant') return { base: deps.session().apiOrigin, withToken: true };
    return { base: host.origin, withToken: false };
  };

  async function request(req: HttpRequest): Promise<HttpResult> {
    const write = req.method !== 'GET';
    const { base, withToken } = baseOf(req.host ?? 'tenant');
    if (!base) return err(appError('unauthorized', req.host === 'auth' ? 'no-auth-origin' : 'no-session', { op: req.op }));
    if (req.signal?.aborted) return err(appError('aborted', 'aborted', { op: req.op }));
    const token = withToken ? deps.session().token : null;
    const headers: Record<string, string> = { Accept: 'application/json', 'Accept-Language': deps.language?.() ?? 'ru' };
    if (token) headers.Authorization = `Bearer ${token}`; // DEV-D-89: tenant host only
    if (req.body !== undefined) headers['Content-Type'] = 'application/json';

    const ctrl = new AbortController();
    let timedOut = false;
    const onCallerAbort = (): void => ctrl.abort();
    req.signal?.addEventListener('abort', onCallerAbort, { once: true });
    const job = `http-timeout-${++seq}`;
    deps.scheduler.after(job, req.timeoutMs ?? (write ? timeouts.writeMs : timeouts.readMs), () => {
      timedOut = true;
      ctrl.abort();
    });
    const offlineAtSend = deps.isOnline ? !deps.isOnline() : false;
    const emit = (reason: string): void => deps.events.emit({ type: 'session.expired', reason });
    try {
      const res = await fetchFn(buildUrl(base, req.path, req.query), {
        method: req.method,
        headers,
        body: req.body === undefined ? undefined : JSON.stringify(req.body),
        signal: ctrl.signal,
      });
      const { json } = await readJson(res);
      return classify(req, res.status, json, emit);
    } catch {
      if (req.signal?.aborted) return err(appError('aborted', 'aborted', { op: req.op })); // DEV-D-88
      if (timedOut) return err(appError(write ? 'outcome-unknown' : 'timeout', 'timeout', { op: req.op }));
      return err(appError(write && !offlineAtSend ? 'outcome-unknown' : 'unreachable', 'network', { op: req.op }));
    } finally {
      deps.scheduler.cancel(job);
      req.signal?.removeEventListener('abort', onCallerAbort);
    }
  }

  return {
    request,
    get: (path, opts) => request({ ...opts, method: 'GET', path }),
    post: (path, body, opts) => request({ ...opts, method: 'POST', path, body }),
    patch: (path, body, opts) => request({ ...opts, method: 'PATCH', path, body }),
    delete: (path, body, opts) => request({ ...opts, method: 'DELETE', path, body }),
  };
}
