import { createContext, useContext, useSyncExternalStore, type ReactNode } from 'react';
import type { Connectivity, ConnectivityState } from './connectivity';

const ConnectivityContext = createContext<Connectivity | null>(null);

/** app/providers mounts this with the single `createConnectivity(...)` instance. */
export function ConnectivityProvider({ value, children }: { value: Connectivity; children: ReactNode }): JSX.Element {
  return <ConnectivityContext.Provider value={value}>{children}</ConnectivityContext.Provider>;
}

/** Current CONN-STATES value; re-renders on change. */
export function useConnectivity(): ConnectivityState {
  const c = useContext(ConnectivityContext);
  if (!c) throw new Error('ConnectivityProvider missing');
  return useSyncExternalStore(c.subscribe, c.state);
}
